package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
@Data
@AllArgsConstructor
@NoArgsConstructor
public class DocumentExtractionResult {
    private Map<Integer, Page> pages;
    private Integer noOfPages;
    private AccountSummary accountSummary;
    private boolean isStatementWithReversedOrder;
    // this field indicate statement is in ascending order but transactions in particular date is in reverse
    private boolean isStatementWithReverseOrderPerDate;
    private PreProcessVerificationResult preProcessVerificationResult;
    private Integer transactionDateIndexByHeader;
    private Integer valueDateIndexByHeader;
    private Boolean bankSpecificProcessing = Boolean.FALSE;
    private BankSpecificStatementMetadata bankSpecificStatementMetadata;
    private boolean isStatementWithoutBalance;
    private boolean skipFurtherProcessing = false;

    public DocumentExtractionResult copy() {
        Map<Integer, Page> copyPages = this.pages.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));


        return new DocumentExtractionResult(
            copyPages,
            this.noOfPages,
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );  
    }

    public DocumentExtractionResult copy(Integer numberOfPages) {
        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> entry.getKey() <= numberOfPages)
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                    entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
            filteredPages,
            Math.min(numberOfPages, filteredPages.size()),
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );
    }

    public DocumentExtractionResult copyOfPage(Integer pageNumber) {

        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> Objects.equals(entry.getKey(), pageNumber))
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
                filteredPages,
                Math.min(1, filteredPages.size()),
                this.accountSummary != null ? this.accountSummary.copy() : null,
                this.isStatementWithReversedOrder,
                this.isStatementWithReverseOrderPerDate,
                this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing
        );
    }

}

package com.finboost.bank.statement.parser.service.document.extraction.azure;

import com.azure.ai.documentintelligence.models.AnalyzeResult;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.AccountSummary;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.io.IOException;
import java.util.Date;

@Service
@Slf4j
public class AzureDocumentExtractionServiceImpl implements DocumentExtractionService {

    private AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor;
    private AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper;
    private HistogramColumnDetectionService histogramColumnDetectionService;
    private MeanShiftColumnDetectionService meanShiftColumnDetectionService;
    private AnalyzeDocuments analyzeDocuments;
    private EPdfCharacterExtractionService ePdfCharacterExtractionService;
    private IBankSpecificParsingService bankSpecificParsingService;

    @Autowired
    public void setAzureDocumentIntelligenceProcessor(AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor) {
        this.azureDocumentIntelligenceProcessor = azureDocumentIntelligenceProcessor;
    }

    @Autowired
    public void setAzureDocumentIntelligenceResponseMapper(AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper) {
        this.azureDocumentIntelligenceResponseMapper = azureDocumentIntelligenceResponseMapper;
    }

    @Autowired
    public void setHistogramColumnDetectionService(HistogramColumnDetectionService histogramColumnDetectionService) {
        this.histogramColumnDetectionService = histogramColumnDetectionService;
    }

    @Autowired
    public void setMeanShiftColumnDetectionService(MeanShiftColumnDetectionService meanShiftColumnDetectionService) {
        this.meanShiftColumnDetectionService = meanShiftColumnDetectionService;
    }

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    @Autowired
    public void setEPdfCharacterExtractionService(EPdfCharacterExtractionService ePdfCharacterExtractionService) {
        this.ePdfCharacterExtractionService = ePdfCharacterExtractionService;
    }

    @Autowired
    public void setBankSpecificParsingService(IBankSpecificParsingService bankSpecificParsingService) {
        this.bankSpecificParsingService = bankSpecificParsingService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try{
            documentExtractionRequest.setStatementFromDate(BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        }catch (Exception e){
            log.warn("Failed to parse statement-from-date from date string {}", bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        // Process with Azure Document Intelligence
        AnalyzeResult analyzeResult = azureDocumentIntelligenceProcessor.processDocument(request.getStatementFile());
        DocumentExtractionResult result = azureDocumentIntelligenceResponseMapper.mapAnalyzeResultToDocument(analyzeResult);

        // Enhance with character-level information right after mapping
        try {
            boolean enhanced = ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
            if (enhanced) {
                log.info("Successfully enhanced document with character-level information");
            } else {
                log.info("Document could not be enhanced with character-level information (likely a scanned PDF)");
            }
        } catch (Exception e) {
            log.warn("Failed to enhance document with character-level information: {}", e.getMessage());
        }

        //check if the bank statement parsing happen bank specific
        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if(result.isSkipFurtherProcessing()){
            return result;
        }

        // Continue with the rest of the processing
        DocumentExtractionResult preProcessedResultByHeader = analyzeDocuments.preProcessForVerificationByHeader(result,5);
        if(preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        }else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, analyzeResult.getPages().size());
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);
//        analyzeDocuments.extractBasicDetails(result);

        return result;
    }
}
package com.finboost.bank.statement.parser.service.document.extraction.azure;

import com.azure.ai.documentintelligence.DocumentIntelligenceClient;
import com.azure.ai.documentintelligence.DocumentIntelligenceClientBuilder;
import com.azure.ai.documentintelligence.models.*;
import com.azure.core.credential.AzureKeyCredential;
import com.azure.core.util.polling.SyncPoller;
import com.finboost.bank.statement.parser.config.document.extraction.azure.DocumentIntelligenceConfig;
import com.finboost.bank.statement.parser.config.requestlog.RequestStatus;
import com.finboost.bank.statement.parser.exception.InvalidRequestException;
import com.finboost.bank.statement.parser.representation.structureLogging.ExceptionDetails;
import com.finboost.bank.statement.parser.service.requestlog.RequestLogService;
import com.finboost.bank.statement.parser.util.JsonUtil;
import com.finboost.bank.statement.parser.util.logging.LoggingPropertiesUtil;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.concurrent.TimeUnit;


@Service
@Slf4j
public class AzureDocumentIntelligenceProcessor {

    private final DocumentIntelligenceClient client;
    private final DocumentIntelligenceConfig properties;

    @Setter(onMethod_ = @Autowired)
    private RequestLogService requestLogService;

    public AzureDocumentIntelligenceProcessor(@Autowired DocumentIntelligenceConfig properties) {
        this.properties = properties;
        this.client = createDocumentIntelligenceClient();
        log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog("", "DocumentIntelligenceService initialized with endpoint: " + properties.getEndpoint())));
    }

    private DocumentIntelligenceClient createDocumentIntelligenceClient() {
        return new DocumentIntelligenceClientBuilder()
                .credential(new AzureKeyCredential(properties.getApiKey()))
                .endpoint(properties.getEndpoint())
                .buildClient();
    }

    public AnalyzeResult processDocument(File document) throws IOException {

        String clientId = LoggingPropertiesUtil.getValueFromMDC("clientId");
        String jobId = LoggingPropertiesUtil.getValueFromMDC("jobId");

        log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.DOCUMENT_ANALYSIS_STARTED.name(), "Starting document analysis for file: " + document.getName())));
        long startTime = System.currentTimeMillis();

        try (FileInputStream fileInputStream = new FileInputStream(document)) {
            AnalyzeDocumentOptions options = new AnalyzeDocumentOptions(fileInputStream.readAllBytes());
            options.setOutputContentFormat(DocumentContentFormat.MARKDOWN);
            SyncPoller<AnalyzeOperationDetails, AnalyzeResult> analyzeDocumentPoller =
                    client.beginAnalyzeDocument(properties.getModelId(), options);

            AnalyzeResult analyzeResult = analyzeDocumentPoller.getFinalResult();
            long endTime = System.currentTimeMillis();
            long totalTime = endTime - startTime;
            log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.DOCUMENT_ANALYSIS_COMPLETED.name(), "Document analysis completed successfully for file: " + document.getName() + "and total time taken to complete: " + TimeUnit.MILLISECONDS.toSeconds(totalTime) + " seconds," + totalTime + "milliseconds")));

            return analyzeResult;
        } catch (IOException e) {
            log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.DOCUMENT_ANALYSIS_FAILED.name(), "Error reading document file: " + document.getName(), ExceptionDetails.exceptionDetails(e.getMessage()))));
            throw new IOException("Error reading the document file: " + e.getMessage(), e);
        } catch (Exception e) {
            log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.DOCUMENT_ANALYSIS_FAILED.name(), "Error processing document: " + document.getName(), ExceptionDetails.exceptionDetails(e))));
            throw new InvalidRequestException("ERROR", "Error while processing document");
        }
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;
import java.util.Map;
