@Data
@AllArgsConstructor
@NoArgsConstructor
public class Page {
    private Double width;
    private Double height;
    private Integer pageNumber;
    private List<Word> words;
    private String content;
    private Map<Integer, Table> tables;

    public Page copy() {
        return new Page(
            this.width,
            this.height,
            this.pageNumber,
            this.words.stream().map(Word::copy).collect(Collectors.toList()),
            this.content,
            this.tables.entrySet().stream()
                .collect(Collectors.toMap(
                    Map.Entry::getKey,
                    entry -> entry.getValue().copy()
                ))
        );
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class Table {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private Integer pageNumber;
    private List<ColumnDataType> colType;
    private List<ColumnTransactionType> txnColType;
    private Map<Integer, Map<Integer, TableCell>> cells;
    private boolean isBankTransactions;
    private Integer totalRows;
    private Integer totalColumns;
    private Integer spanOffset;
    private Integer spanLength;
    private List<Float> columnBoundaries;

    public boolean getIsTransactionTable() {
        return isBankTransactions;
    }

    /**
     * Gets the content of a specific row as a space-separated string
     * @param rowIndex the index of the row to retrieve
     * @return String containing the contents of all cells in the row, or empty string if row doesn't exist
     */
    public String getRowContent(Integer rowIndex) {
        if (cells == null || !cells.containsKey(rowIndex)) {
            return "";
        }

        Map<Integer, TableCell> rowCells = cells.get(rowIndex);
        if (rowCells == null || rowCells.isEmpty()) {
            return "";
        }

        return rowCells.values().stream()
                .sorted(Comparator.comparing(TableCell::getColindex))
                .map(TableCell::getContent)
                .filter(content -> content != null && !content.isEmpty())
                .collect(Collectors.joining(" "));

    }

    public Table copy() {


        return new Table(
            this.x1,
            this.y1,    
            this.x2,
            this.y2,
            this.x3,
            this.y3,
            this.x4,
            this.y4,    
            this.pageNumber,
            this.colType,
            this.txnColType,
            this.cells.entrySet().stream()
                .collect(Collectors.toMap(
                    Map.Entry::getKey,
                    entry -> entry.getValue().entrySet().stream()
                        .collect(Collectors.toMap(
                            Map.Entry::getKey,
                            cellEntry -> cellEntry.getValue().copy()
                        ))
                ))
            ,
            this.isBankTransactions,
            this.totalRows,
            this.totalColumns,
            this.spanOffset,
            this.spanLength,
            this.columnBoundaries
        );
    }

}

package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class TableCell {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private Integer colspan;
    private Integer rowspan;
    private Integer rowindex;
    private Integer colindex;
    private List<Word> words;
    private boolean isHeaderOrFooterCell=false;

    public String getContent() {
        if (words == null || words.isEmpty()) {
            return "";
        }

        // Sort words first by pageIndex then by wordIndex (lower values first)
        List<Word> sortedWords = new ArrayList<>(words);
        Collections.sort(sortedWords, new Comparator<Word>() {
            @Override
            public int compare(Word w1, Word w2) {
                // First compare by pageIndex (lower page first)
                int pageCompare = Integer.compare(w1.getPageIndex(), w2.getPageIndex());
                if (pageCompare != 0) {
                    return pageCompare;
                }

                // If same page, compare by wordIndex (lower word first)
                return Integer.compare(w1.getWordIndex(), w2.getWordIndex());
            }
        });

        // Sort words by x1 coordinate (left to right)
        Collections.sort(sortedWords, Comparator.comparing(Word::getActualX1));

        // Sort words by y1 coordinate (top to bottom)
        Collections.sort(sortedWords, Comparator.comparing(Word::getActualY1));

        return sortedWords.stream()
                .map(Word::getContent)
                .collect(Collectors.joining(" "))
                .trim();
        //return words.stream().map(Word::getContent).collect(Collectors.joining(" "));
    }

    public TableCell copy() {
        return new TableCell(
            this.x1,
            this.y1,
            this.x2,  
            this.y2,
            this.x3,
            this.y3,
            this.x4,
            this.y4,
            this.colspan,
            this.rowspan,
            this.rowindex,
            this.colindex,
            this.words.stream().map(Word::copy).collect(Collectors.toList()),
            this.isHeaderOrFooterCell
        );
    }

}
package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class Word {
    private Float x1;
    private Float y1;
    private Float x2;
    private Float y2;
    private Float x3;
    private Float y3;
    private Float x4;
    private Float y4;
    private String content;
    private Integer pageNumber;
    private Float width;
    private Float height;
    private int pageIndex;
    private int wordIndex;
    private EPdfWord ePdfWord; // New field for character-level information

    // Constructor without EPdfWord for backward compatibility
    public Word(String content, float x1, float y1, float x2, float y2, float x3, float y3, float x4, float y4,
                int pageNumber, float width, float height, int pageIndex, int wordIndex) {
        this.content = content;
        this.x1 = x1;
        this.y1 = y1;
        this.x2 = x2;
        this.y2 = y2;
        this.x3 = x3;
        this.y3 = y3;
        this.x4 = x4;
        this.y4 = y4;
        this.pageNumber = pageNumber;
        this.width = width;
        this.height = height;
        this.pageIndex = pageIndex;
        this.wordIndex = wordIndex;
    }

    public Word copy() {
        Word copy = new Word(
                this.content,
                this.x1,
                this.y1,
                this.x2,
                this.y2,
                this.x3,
                this.y3,
                this.x4,
                this.y4,
                this.pageNumber,
                this.width,
                this.height,
                this.pageIndex,
                this.wordIndex
        );

        // Copy EPdfWord if present
        if (this.ePdfWord != null) {
            copy.setEPdfWord(this.ePdfWord.copy());
        }

        return copy;
    }

    public String getContent() {
        if(null != ePdfWord && ePdfWord.getContent() != null && !ePdfWord.getContent().isEmpty()) {
            return ePdfWord.getContent().trim();
        }
        if(null != content && !content.isEmpty()) {
            return content.trim();
        }
        return content;
    }

    public Float getActualX1(){
        if(null != ePdfWord && ePdfWord.getX1() != 0.0f) return ePdfWord.getX1();

        return x1;
    }

    public Float getActualY1(){
        if(null != ePdfWord &&  ePdfWord.getY1() != 0.0f) return ePdfWord.getY1();

        return y1;
    }
}
package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.Data;

@Data
public class CellRange {
    private Float x1;
    private Float x2;
    private Float width;

    public CellRange(Float x1, Float x2) {
        this.x1 = x1;
        this.x2 = x2;
        this.width = x2 - x1;
    }

    public void updateRange(Float newX1, Float newX2) {
        this.x1 = Math.min(this.x1, newX1);
        this.x2 = Math.max(this.x2, newX2);
        this.width = this.x2 - this.x1;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.azure;

import com.azure.ai.documentintelligence.models.*;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.stream.Collectors;

@Service
public class AzureDocumentIntelligenceResponseMapper {

    public DocumentExtractionResult mapAnalyzeResultToDocument(AnalyzeResult analyzeResult) {
        DocumentExtractionResult document = new DocumentExtractionResult();
        Map<Integer, Page> pages = new HashMap<>();

        for (DocumentPage docPage : analyzeResult.getPages()) {
            Page page = mapPage(docPage,analyzeResult);

            // Map words at page level
            List<Word> pageWords = mapWords(docPage.getWords(), docPage.getPageNumber());
            page.setWords(pageWords);

            // Map tables
            Map<Integer, Table> tables = mapTables(
                    analyzeResult.getTables().stream()
                            .filter(table -> table.getBoundingRegions().stream()
                                    .anyMatch(region -> region.getPageNumber() == docPage.getPageNumber()))
                            .collect(Collectors.toList()),
                    pageWords,
                    docPage.getPageNumber()
            );
            page.setTables(tables);

            pages.put(docPage.getPageNumber(), page);
        }

        document.setPages(pages);
        document.setNoOfPages(analyzeResult.getPages().size());
        assignWordIndices(document);
        return document;
    }

    public void assignWordIndices(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) {
            return;
        }

        int currentWordIndex = 1;

        // Process each page in order
        List<Integer> pageNumbers = new ArrayList<>(result.getPages().keySet());
        Collections.sort(pageNumbers);

        for (Integer pageNumber : pageNumbers) {
            Page page = result.getPages().get(pageNumber);
            if (page.getTables() == null) {
                continue;
            }

            // Process each table in order
            List<Integer> tableIndices = new ArrayList<>(page.getTables().keySet());
            Collections.sort(tableIndices);

            for (Integer tableIndex : tableIndices) {
                Table table = page.getTables().get(tableIndex);
                if (table.getCells() == null) {
                    continue;
                }

                // Process each row in order
                List<Integer> rowIndices = new ArrayList<>(table.getCells().keySet());
                Collections.sort(rowIndices);

                for (Integer rowIndex : rowIndices) {
                    Map<Integer, TableCell> row = table.getCells().get(rowIndex);
                    if (row == null) {
                        continue;
                    }

                    // Process each cell in order
                    List<Integer> cellIndices = new ArrayList<>(row.keySet());
                    Collections.sort(cellIndices);

                    for (Integer cellIndex : cellIndices) {
                        TableCell cell = row.get(cellIndex);
                        if (cell.getWords() == null) {
                            continue;
                        }

                        // Assign indices to words in the cell
                        for (Word word : cell.getWords()) {
                            word.setPageIndex(pageNumber);
                            word.setWordIndex(currentWordIndex++);
                        }
                    }
                }
            }
        }
    }


    private Page mapPage(DocumentPage docPage, AnalyzeResult analyzeResult) {
        Page page = new Page();
        page.setPageNumber(docPage.getPageNumber());
        page.setHeight(docPage.getHeight());
        page.setWidth(docPage.getWidth());

        int offset = docPage.getSpans().get(0).getOffset();
        int length = docPage.getSpans().get(0).getLength();
        page.setContent(analyzeResult.getContent().substring(offset, offset + length));
        return page;
    }



    private List<Word> mapWords(List<DocumentWord> documentWords, int pageNumber) {
        return documentWords.stream()
                .map(docWord -> {
                    Word word = new Word();
                   // BoundingRegion region = docWord.getBoundingRegions().get(0);
                    List<Double> polygon = docWord.getPolygon();

                    word.setContent(docWord.getContent());
                    word.setPageNumber(pageNumber);
                    word.setX1(polygon.get(0).floatValue());
                    word.setY1(polygon.get(1).floatValue());
                    word.setX2(polygon.get(2).floatValue());
                    word.setY2(polygon.get(3).floatValue());
                    word.setX3(polygon.get(4).floatValue());
                    word.setY3(polygon.get(5).floatValue());
                    word.setX4(polygon.get(6).floatValue());
                    word.setY4(polygon.get(7).floatValue());

                    // Calculate width and height
                    float width = Math.max(
                            Math.abs(word.getX2() - word.getX1()),
                            Math.abs(word.getX4() - word.getX3())
                    );
                    float height = Math.max(
                            Math.abs(word.getY3() - word.getY1()),
                            Math.abs(word.getY4() - word.getY2())
                    );
                    word.setWidth(width);
                    word.setHeight(height);

                    return word;
                })
                .collect(Collectors.toList());
    }

    private Map<Integer, Table> mapTables(List<DocumentTable> documentTables, List<Word> pageWords, int pageNumber) {
        Map<Integer, Table> tables = new HashMap<>();
        int tableIndex = 0;

        for (DocumentTable docTable : documentTables) {
            Table table = new Table();
            BoundingRegion region = docTable.getBoundingRegions().get(0);
            List<Double> polygon = region.getPolygon();

            table.setPageNumber(pageNumber);
            table.setX1(polygon.get(0).floatValue());
            table.setY1(polygon.get(1).floatValue());
            table.setX2(polygon.get(2).floatValue());
            table.setY2(polygon.get(3).floatValue());
            table.setX3(polygon.get(4).floatValue());
            table.setY3(polygon.get(5).floatValue());
            table.setX4(polygon.get(6).floatValue());
            table.setY4(polygon.get(7).floatValue());

            table.setTotalRows(docTable.getRowCount());
            table.setTotalColumns(docTable.getColumnCount());
            table.setSpanOffset(docTable.getSpans().get(0).getOffset());
            table.setSpanLength(docTable.getSpans().get(0).getLength());

            // Map cells
            Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
            for (DocumentTableCell docCell : docTable.getCells()) {
                TableCell cell = mapTableCell(docCell, pageWords);

                // Initialize row map if not exists
                cells.computeIfAbsent(cell.getRowindex(), k -> new LinkedHashMap<>())
                        .put(cell.getColindex(), cell);
            }
            table.setCells(cells);

            // Initialize with default column types
            table.setColType(new ArrayList<>());
            table.setTxnColType(new ArrayList<>());

            tables.put(tableIndex++, table);
        }

        return tables;
    }

    private TableCell mapTableCell(DocumentTableCell docCell, List<Word> pageWords) {
        TableCell cell = new TableCell();
        BoundingRegion region = docCell.getBoundingRegions().get(0);
        List<Double> polygon = region.getPolygon();

        cell.setRowindex(docCell.getRowIndex());
        cell.setColindex(docCell.getColumnIndex());
        cell.setRowspan(docCell.getRowSpan()!= null ? docCell.getRowSpan() : 1);
        cell.setColspan(docCell.getColumnSpan() != null ? docCell.getColumnSpan() : 1);

        cell.setHeaderOrFooterCell((docCell.getKind() != null && docCell.getKind() == DocumentTableCellKind.COLUMN_HEADER));

        cell.setX1(polygon.get(0).floatValue());
        cell.setY1(polygon.get(1).floatValue());
        cell.setX2(polygon.get(2).floatValue());
        cell.setY2(polygon.get(3).floatValue());
        cell.setX3(polygon.get(4).floatValue());
        cell.setY3(polygon.get(5).floatValue());
        cell.setX4(polygon.get(6).floatValue());
        cell.setY4(polygon.get(7).floatValue());

        // Find words that fall within this cell's coordinates
        List<Word> cellWords = findWordsInCell(pageWords, cell);
        cell.setWords(cellWords);

        return cell;
    }

    private List<Word> findWordsInCell(List<Word> pageWords, TableCell cell) {
        return pageWords.stream()
                .filter(word -> isWordInCell(word, cell))
                .collect(Collectors.toList());
    }

    private boolean isWordInCell(Word word, TableCell cell) {
        // Calculate cell bounds
        float cellMinX = Math.min(Math.min(Math.min(cell.getX1(), cell.getX2()), cell.getX3()), cell.getX4());
        float cellMaxX = Math.max(Math.max(Math.max(cell.getX1(), cell.getX2()), cell.getX3()), cell.getX4());
        float cellMinY = Math.min(Math.min(Math.min(cell.getY1(), cell.getY2()), cell.getY3()), cell.getY4());
        float cellMaxY = Math.max(Math.max(Math.max(cell.getY1(), cell.getY2()), cell.getY3()), cell.getY4());

        // Calculate word center point
        float wordCenterX = (word.getX1() + word.getX2() + word.getX3() + word.getX4()) / 4;
        float wordCenterY = (word.getY1() + word.getY2() + word.getY3() + word.getY4()) / 4;

        // Check if word center falls within cell bounds with a small tolerance
        float tolerance = 0.0f; // Adjust this value based on your needs
        return wordCenterX >= (cellMinX - tolerance) &&
                wordCenterX <= (cellMaxX + tolerance) &&
                wordCenterY >= (cellMinY - tolerance) &&
                wordCenterY <= (cellMaxY + tolerance);
    }
}

