    @Setter(onMethod_ = @Autowired)
    private SaraswatBankUtil saraswatBankUtil;

    @Setter(onMethod_ = @Autowired)
    private StandardCharteredBankUtil standardCharteredBankUtil;

    @Setter(onMethod_ = @Autowired)
    private CatholicSyrianBankUtil catholicSyrianBankUtil;

    @Setter(onMethod_ = @Autowired)
    private MayBankUtil mayBankUtil;

    @Setter(onMethod_ = @Autowired)
    private PublicBankUtil publicBankUtil;

    public void identifyBankSpecificStatementProcess(DocumentExtractionResult result, DocumentExtractionRequest request) {

        if (null == request || null == request.getBankName() || request.getBankName().isEmpty()) return;

        try{
            switch (request.getBankName()){
                case "SBI":
                    SBIBankUtil.identifyStatementFormatSpecificColumnType(result, request);
                    break;
                case "IDBI":
                    IDBIBankUtil.identifyWithoutBalanceStatementFormatSpecificColumnType(result, request);
                    break;
                case "ICICI":
                    ICICIBankUtil.identifyWithoutBalanceStatementFormatSpecificColumnType(result, request);
                    break;
                case "DHANLAXMI":
                    DhanLaxmiBankUtil.identifyStatementFormatSpecificColumnType(result, request);
                    break;
                case "HDFC":
                    hdfcBankUtil.identifyStatementFormatSpecificColumnType(result, request);
                    break;
                case "FEDERAL":
                    FederalBankUtil.identifyStatementFormatSpecificColumnType(result, request);
                    break;
                case "MAY_BANK":
                    mayBankUtil.identifyStatementFormatSpecificColumnType(result,request);
                    break;
                case "PUBLIC_BANK":
                    publicBankUtil.identifyStatementFormatSpecificColumnType(result,request);
                    break;
//                case "SARASWAT":
//                    saraswatBankUtil.identifyStatementFormatSpecificColumnType(result,request);
                case "STANDARD_CHARTERED":
                    standardCharteredBankUtil.identifyStatementFormatSpecificColumnType(result, request);
                case "CATHOLIC_SYRIAN":
                    catholicSyrianBankUtil.identifyStatementFormatSpecificColumnType(result, request);



            }
        }catch (Exception e){
            e.printStackTrace();

        }
    }

    public void reassignColumnTransactionTypes(DocumentExtractionResult result){
        if(!result.getBankSpecificProcessing()){
            return;
        }

        if(result.getBankSpecificStatementMetadata() == null){
            return;
        }

        result.getPages().values().forEach(page -> {
            if (page.getTables() != null) {
                page.getTables().values().forEach(table -> {processTable(table, result);});
            }
        });
    }

    private void processTable(Table table, DocumentExtractionResult result){
        BankSpecificStatementMetadata bankSpecificStatementMetadata = result.getBankSpecificStatementMetadata();
        if(table.getTotalColumns() == null || table.getTotalColumns() < bankSpecificStatementMetadata.getNoOfColumn()) {
            return;
        }

        if(!table.getIsTransactionTable()){
            return;
        }

        table.setTxnColType(bankSpecificStatementMetadata.getColumnTransactionTypes());
    }
}
