    public DocumentExtractionResult analyzeDocument(DocumentExtractionResult result, boolean performColumnNormalization, boolean performRowNormalization, boolean transformTables) {

        if (performColumnNormalization) {
            result = tableColumnNormalizer.normalizeTableColumn(result);
        }

        if (performRowNormalization) {
            result = tableRowNormalizer.normalizeTableRows(result);
        }

        columnTypeIdentifier.identifyColumnTypes(result);
        bankTransactionTableHeaderIdentifier.identifyAndMarkHeaderCells(result);
        bankTransactionTableFooterIdentifier.IdentifyAndMarkFooterCells(result);
        bankTransactionColumnTypeIdentifier.identifyColumnTransactionTypeByHeader(result);
        bankTransactionColumnTypeIdentifier.assignColumnTransactionTypes(result);
        bankTransactionTableIdentifier.identifyBankTransactionTables(result);
        bankSpecificParsingService.reassignColumnTransactionTypes(result);
        bankTransactionColumnTypeIdentifier.reassignColumnTransactionTypesIfReverseOrder(result);
        if (transformTables) {
            bankTransactionRowNormalizer.transformTables(result);
        }
        return result;
    }

    public AccountSummary extractBasicDetails(DocumentExtractionResult result) {
        AccountSummary basicDetail = statementBasicDetailExtractor.getBasicDetails(result);
        result.setAccountSummary(basicDetail);
        return basicDetail;
    }

    public DocumentExtractionResult preProcessForVerification(DocumentExtractionResult result, int numberOfPages) {

        if(numberOfPages < 1){
            return result;
        }


        // Create a deep copy of the first N pages
        DocumentExtractionResult copyResult = result.copy(numberOfPages);
        copyResult = analyzeDocument(copyResult, true, true, false);
        // Process each table in the copied result to identify column ranges
        List<Table> validTables = new LinkedList<>();
        for (Map.Entry<Integer, Page> pageEntry : copyResult.getPages().entrySet()) {
            Page page = pageEntry.getValue();
            for (Map.Entry<Integer, Table> tableEntry : page.getTables().entrySet()) {
                if (tableEntry.getValue() != null && tableEntry.getValue().isBankTransactions()) {
                    List<BankStatementVO> bankStatementVOList = new LinkedList<>();
                    BankStatementVO bankStatementVO = new BankStatementVO();
                    bankStatementVO.setDocumentExtractionResult(copyResult.copyOfPage(page.getPageNumber()));
                    bankStatementVOList.add(bankStatementVO);
                    BankStatementProcessorImpl.extractTransactions(bankStatementVOList, false);
                    if(!bankStatementVOList.isEmpty() && bankStatementVOList.get(0).getBankTransactions() != null && !bankStatementVOList.get(0).getBankTransactions().isEmpty()) {
                        Integer inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(bankStatementVOList.get(0).getBankTransactions());
                        if (inconsistencyCount != null && inconsistencyCount == 0 && validTransactionList(bankStatementVOList.get(0).getBankTransactions())){
                            validTables.add(tableEntry.getValue());
                        }else{
                            List<BankTransactionVO> bankTransactionVOListReverse = new LinkedList<>();
                            for(int i = bankStatementVOList.get(0).getBankTransactions().size()-1; i >= 0; i--) {
                                bankTransactionVOListReverse.add(bankStatementVOList.get(0).getBankTransactions().get(i));
                            }
                            inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(bankTransactionVOListReverse);
                            if (inconsistencyCount != null && inconsistencyCount == 0 && validTransactionList(bankTransactionVOListReverse)) {
                                validTables.add(tableEntry.getValue());
                                copyResult.setStatementWithReversedOrder(true);
                            }
                        }

                    }
                }
                if (validTables.size() == 1){
                    break;
                }
            }
            if (validTables.size() == 1){
                break;
            }

        }

        if (!validTables.isEmpty()) {
            Map<Table, Map<Integer, TableCell>> tableCells = new LinkedHashMap<>();
            for (Table table : validTables) {
                tableCells.put(table, getMostAppropriateRowFromTable(table));
            }
            Map.Entry<Table,Map<Integer, TableCell>> validTableCells = null;
            int maxColumnIndex = 0;
            for(Map.Entry<Table, Map<Integer, TableCell>> tableCellMap : tableCells.entrySet()){
                if (tableCellMap != null && tableCells.get(tableCellMap.getKey()) != null && tableCells.get(tableCellMap.getKey()).size() > maxColumnIndex) {
                    maxColumnIndex = tableCells.get(tableCellMap.getKey()).size();
                    validTableCells = tableCellMap;
                }
            }
            if(validTableCells != null){
                List<ColumnTransactionType> columnTransactionTypes = validTableCells.getKey().getTxnColType();
                List<ColumnRange> columnRanges = new LinkedList<>();
                validTableCells.getValue().entrySet().stream()
                    .sorted(Map.Entry.comparingByKey())
                    .forEach(entry -> {
                        ColumnRange columnRange = getColumnRangeFromTableCell(entry.getValue());
                        if (columnRange != null) {
                            columnRanges.add(columnRange);
                        }
                    });
                copyResult.setPreProcessVerificationResult(new PreProcessVerificationResult(columnRanges, validTables,columnTransactionTypes, copyResult.isStatementWithReversedOrder()));
            }

        }

        return copyResult;
    }

    private boolean validTransactionList(List<BankTransactionVO> bankTransactionVOList) {
        if (bankTransactionVOList == null || bankTransactionVOList.size() < 2) {
            return false;
        }

        boolean hasCredit = false;
        boolean hasDebit = false;

        for (BankTransactionVO transaction : bankTransactionVOList) {
            if (transaction.getTransactionType() != null) {
                if (transaction.getTransactionType() == TransactionType.CREDIT) {
                    hasCredit = true;
                } else if (transaction.getTransactionType() == TransactionType.DEBIT) {
                    hasDebit = true;
                }
            }

            if (hasCredit && hasDebit) {
                return true;
            }
        }

        return false;
    }

    private Map<Integer, TableCell> getMostAppropriateRowFromTable(Table table){
        Map<Integer, TableCell> mostAppropriateRow = null;

        if (table != null && table.getCells() != null) {
            int maxColumns = 0;

            // Find row with maximum columns
            for (Map.Entry<Integer, Map<Integer, TableCell>> rowEntry : table.getCells().entrySet()) {
                if (rowEntry.getValue() != null && rowEntry.getValue().size() > maxColumns) {
                    maxColumns = rowEntry.getValue().size();
                    mostAppropriateRow = rowEntry.getValue();
                }
            }
        }

        return mostAppropriateRow;
    }

    private ColumnRange getColumnRangeFromTableCell(TableCell cell){
        ColumnRange columnRange = null;
        if (cell != null) {
            columnRange = new ColumnRange(
                cell.getX1(),
                cell.getY1(), 
                cell.getX2(),
                cell.getY2(),
                cell.getX3(),
                cell.getY3(),
                cell.getX4(),
                cell.getY4()
            );
        }
        return columnRange;
    }

