                        if (inconsistencyCount != null && inconsistencyCount == 0 && validTransactionList(bankStatementVOList.get(0).getBankTransactions())){
                            validTables.add(tableEntry.getValue());
                        }else{
                            List<BankTransactionVO> bankTransactionVOListReverse = new LinkedList<>();
                            for(int i = bankStatementVOList.get(0).getBankTransactions().size()-1; i >= 0; i--) {
                                bankTransactionVOListReverse.add(bankStatementVOList.get(0).getBankTransactions().get(i));
                            }
                            inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(bankTransactionVOListReverse);
                            if (inconsistencyCount != null && inconsistencyCount == 0 && validTransactionList(bankTransactionVOListReverse)) {
                                validTables.add(tableEntry.getValue());
                                copyResult.setStatementWithReversedOrder(true);
                            }
                        }

                    }
                }
                if (validTables.size() == 1){
                    break;
                }
            }
            if (validTables.size() == 1){
                break;
            }

        }

        if (!validTables.isEmpty()) {
            Map<Table, Map<Integer, TableCell>> tableCells = new LinkedHashMap<>();
            for (Table table : validTables) {
                tableCells.put(table, getMostAppropriateRowFromTable(table));
            }
            Map.Entry<Table,Map<Integer, TableCell>> validTableCells = null;
            int maxColumnIndex = 0;
            for(Map.Entry<Table, Map<Integer, TableCell>> tableCellMap : tableCells.entrySet()){
                if (tableCellMap != null && tableCells.get(tableCellMap.getKey()) != null && tableCells.get(tableCellMap.getKey()).size() > maxColumnIndex) {
                    maxColumnIndex = tableCells.get(tableCellMap.getKey()).size();
                    validTableCells = tableCellMap;
                }
            }
            if(validTableCells != null){
                List<ColumnTransactionType> columnTransactionTypes = validTableCells.getKey().getTxnColType();
                List<ColumnRange> columnRanges = new LinkedList<>();
                validTableCells.getValue().entrySet().stream()
                        .sorted(Map.Entry.comparingByKey())
                        .forEach(entry -> {
                            ColumnRange columnRange = getColumnRangeFromTableCell(entry.getValue());
                            if (columnRange != null) {
                                columnRanges.add(columnRange);
                            }
                        });
                copyResult.setPreProcessVerificationResult(new PreProcessVerificationResult(columnRanges, validTables,columnTransactionTypes, copyResult.isStatementWithReversedOrder()));
            }

        }

        return copyResult;



    }


