    /**
     * Removes duplicate transactions from the list while handling description variations.
     * The method:
     * 1. Groups transactions by date, type, amount, and balance
     * 2. Within each group, compares cleaned descriptions to identify duplicates
     * 3. Preserves the original order of transactions
     * 4. Prioritizes keeping transactions from files with lower fileIndex values
     *
     * @param transactions List of transactions to process
     * @return List of transactions with duplicates removed
     */
    private List<BankTransactionVO> removeDuplicateTransactions(List<BankTransactionVO> transactions) {
        if (transactions == null || transactions.isEmpty()) {
            return new ArrayList<>();
        }

        // Step 1: Group transactions by date, type, amount, and balance
        Map<String, List<BankTransactionVO>> groupedTransactions = transactions.stream()
                .collect(Collectors.groupingBy(transaction -> {
                    // Create a key based on date, type, amount, and balance
                    return transaction.getTransactionDate() + "|" +
                            transaction.getTransactionType() + "|" +
                            transaction.getTransactionAmount() + "|" +
                            transaction.getTransactionBalance();
                }));

        // Set to track transactions to be removed
        Set<BankTransactionVO> duplicatesToRemove = new HashSet<>();

        // Step 2: Process each group to identify duplicates
        for (List<BankTransactionVO> group : groupedTransactions.values()) {
            // If group has only one transaction, no duplicates to check
            if (group.size() <= 1) {
                continue;
            }

            // First, sort by fileIndex to prioritize keeping transactions from earlier files
            List<BankTransactionVO> sortedByFileIndex = new ArrayList<>(group);
            sortedByFileIndex.sort(Comparator.comparing(t ->
                    Optional.ofNullable(t.getFileIndex()).orElse(Integer.MAX_VALUE)));

            // Create a map to track transactions by fileIndex
            Map<Integer, List<BankTransactionVO>> transactionsByFileIndex = new HashMap<>();

            // Group transactions by fileIndex
            for (BankTransactionVO transaction : sortedByFileIndex) {
                Integer fileIndex = Optional.ofNullable(transaction.getFileIndex()).orElse(Integer.MAX_VALUE);
                transactionsByFileIndex.computeIfAbsent(fileIndex, k -> new ArrayList<>()).add(transaction);
            }

            // If all transactions are from the same file, skip duplicate removal
            if (transactionsByFileIndex.size() <= 1) {
                continue;
            }

            // Process transactions across different fileIndexes
            List<Integer> fileIndexes = new ArrayList<>(transactionsByFileIndex.keySet());
            Collections.sort(fileIndexes); // Sort fileIndexes in ascending order

            for (int i = 0; i < fileIndexes.size(); i++) {
                Integer fileIndex1 = fileIndexes.get(i);
                List<BankTransactionVO> transactions1 = transactionsByFileIndex.get(fileIndex1);

                for (int j = i + 1; j < fileIndexes.size(); j++) {
                    Integer fileIndex2 = fileIndexes.get(j);
                    List<BankTransactionVO> transactions2 = transactionsByFileIndex.get(fileIndex2);

                    // Compare transactions between different fileIndexes
                    for (BankTransactionVO transaction1 : transactions1) {
                        if (duplicatesToRemove.contains(transaction1)) {
                            continue;
                        }

                        for (BankTransactionVO transaction2 : transactions2) {
                            if (duplicatesToRemove.contains(transaction2)) {
                                continue;
                            }

                            // Check if descriptions are similar
                            if (areTransactionsEquivalent(transaction1, transaction2)) {
                                // Keep transaction from lower fileIndex, remove from higher fileIndex
                                duplicatesToRemove.add(transaction2);
                            }
                        }
                    }
                }
            }
        }

        // Step 3: Remove duplicates while preserving original order
        List<BankTransactionVO> result = new ArrayList<>();
        for (BankTransactionVO transaction : transactions) {
            if (!duplicatesToRemove.contains(transaction)) {
                result.add(transaction);
            }
        }

        return result;
    }

    /**
     * Determines if two transactions are equivalent (duplicates) based on their descriptions and other attributes.
     * 
     * @param transaction1 First transaction
     * @param transaction2 Second transaction
     * @return true if transactions are equivalent
     */
    private boolean areTransactionsEquivalent(BankTransactionVO transaction1, BankTransactionVO transaction2) {
        // Check if transaction dates are equal
        if (!transaction1.getTransactionDate().equals(transaction2.getTransactionDate())) {
            return false;
        }

        // Check if transaction types are equal
        if (transaction1.getTransactionType() != transaction2.getTransactionType()) {
            return false;
        }

        // Check if transaction amounts are equal
        if (transaction1.getTransactionAmount().compareTo(transaction2.getTransactionAmount()) != 0) {
            return false;
        }

        // Check descriptions
        String desc1 = transaction1.getTransactionDescription();
        String desc2 = transaction2.getTransactionDescription();

        if (desc1 == null && desc2 == null) {
            return true;
        }

        if (desc1 == null || desc2 == null) {
            return false;
        }

        // Clean descriptions for comparison
        String cleanDesc1 = cleanDescription(desc1);
        String cleanDesc2 = cleanDescription(desc2);

        // Check for exact match after cleaning
        if (cleanDesc1.equals(cleanDesc2)) {
            return true;
        }

        // Check if one is contained in the other
        if (cleanDesc1.contains(cleanDesc2) || cleanDesc2.contains(cleanDesc1)) {
            return true;
        }

        // Check for high similarity using word matching
        return calculateWordSimilarity(cleanDesc1, cleanDesc2) >= 0.9;
    }

    /**
     * Cleans a transaction description for comparison.
     * 
     * @param description The description to clean
     * @return Cleaned description
     */
    private String cleanDescription(String description) {
        if (description == null) {
            return "";
        }

        return description
                .replaceAll("[^a-zA-Z0-9]", "")
//                .replaceAll("\\s+", "") // Normalize whitespace
//                .replaceAll("[^a-zA-Z0-9\\s]", "") // Remove special characters
//                .replaceAll("\\s+", "") // Replace multiple spaces with a single space
                .trim()
                .toLowerCase();
    }

    /**
     * Calculates similarity between two descriptions based on word matching.
     * 
     * @param desc1 First description
     * @param desc2 Second description
     * @return Similarity score between 0 and 1
     */
    private double calculateWordSimilarity(String desc1, String desc2) {
        // Clean descriptions first
        String cleanDesc1 = cleanDescriptionForWordSimilarity(desc1);
        String cleanDesc2 = cleanDescriptionForWordSimilarity(desc2);
        // Split into words
        String[] words1 = cleanDesc1.split("\\s+");
        String[] words2 = cleanDesc2.split("\\s+");
        // Count matching words
        int matchCount = 0;
        Set<Integer> matchedIndices = new HashSet<>();
        for (String word1 : words1) {
            if (word1.length() <= 2) continue; // Skip very short words
            for (int i = 0; i < words2.length; i++) {
                if (matchedIndices.contains(i)) continue; // Skip already matched words
                String word2 = words2[i];
                if (word2.length() <= 2) continue; // Skip very short words
                // Check for exact match
                if (word1.equals(word2)) {
                    matchCount++;
                    matchedIndices.add(i);
                    break;
                }
                // Check for substring match for longer words
                if (word1.length() > 4 && word2.length() > 4) {
                    if (word1.contains(word2) || word2.contains(word1)) {
                        matchCount++;
                        matchedIndices.add(i);
                        break;
                    }
                }
                // Alternative to Levenshtein: Check if words are almost same length and share most characters
                if (word1.length() > 4 && word2.length() > 4) {
                    // Check if length difference is small
                    if (Math.abs(word1.length() - word2.length()) <= 2) {
                        // For longer words, check if they share at least 80% of characters
                        int commonChars = 0;
                        String shorterWord = word1.length() <= word2.length() ? word1 : word2;
                        String longerWord = word1.length() > word2.length() ? word1 : word2;
                        for (char c : shorterWord.toCharArray()) {
                            if (longerWord.indexOf(c) >= 0) {
                                commonChars++;
                            }
                        }
                        double similarityRatio = (double) commonChars / shorterWord.length();
                        if (similarityRatio >= 0.8) {
                            matchCount++;
                            matchedIndices.add(i);
                            break;
                        }
                    }
                }
            }
        }
        // Calculate similarity score (Jaccard similarity coefficient)
        double totalWords = words1.length + words2.length - matchCount;
        return totalWords > 0 ? (double) matchCount / totalWords : 0;
    }

    private String cleanDescriptionForWordSimilarity(String description) {
        if (description == null) {
            return "";
        }
        return description
                .replaceAll("[^a-zA-Z0-9\\s]", "") // Remove special characters
                .replaceAll("\\s+", " ")          // Replace multiple spaces with single space
                .trim()                           // Remove leading/trailing spaces
                .toLowerCase();                   // Convert to lowercase
    }

    private static void processDebitCreditAmount(BankTransactionVO transaction, TableCell cell, ColumnTransactionType colType,
         Integer amountTypeColIndex, Map<Integer, TableCell> row, Integer balanceTypeColIndex) {

        if (!isValidContent(cell.getContent())) {
            return;
        }

        String content = cell.getContent().trim();


        // Case 1: When we have separate AmountType column
        if ((amountTypeColIndex != null && balanceTypeColIndex != null && amountTypeColIndex < balanceTypeColIndex) ||
                (amountTypeColIndex != null && balanceTypeColIndex == null)) {
            // Get the DR/CR indicator from the AmountType column for the current row
            TableCell amountTypeCell = row.get(amountTypeColIndex);
            if (amountTypeCell != null && amountTypeCell.getContent() != null) {
                String type = amountTypeCell.getContent().trim().toLowerCase();
                BigDecimal amount = AmountParserUtil.getAmount(cell.getContent());

                if (type.contains("debit") || type.contains("dr") || (type.contains("d") && type.length() == 1)) {
                    transaction.setTransactionType(TransactionType.DEBIT);
                } else if (type.contains("credit") || type.contains("cr") || (type.contains("c") && type.length() == 1)) {
                    transaction.setTransactionType(TransactionType.CREDIT);
                }
                transaction.setTransactionAmount(getDebitCreditAmount(amount));
            }
        } else if(content.toLowerCase().contains("dr") || content.toLowerCase().contains("cr")) {
            // Case 2: When CR/DR is in parentheses in the amount column itself

            String lowerContent = content.toLowerCase();
            // Remove the (DR) or (CR) from amount string
            BigDecimal amount = AmountParserUtil.getAmount(content.replaceAll("(?i)\\((?:cr|dr)\\)", "").trim());

            if (lowerContent.contains("dr")) {
                transaction.setTransactionType(TransactionType.DEBIT);
            } else if (lowerContent.contains("cr")) {
                transaction.setTransactionType(TransactionType.CREDIT);
            }
            transaction.setTransactionAmount(getDebitCreditAmount(amount));
        } else if(content.contains("-") || content.contains("+")){
            //Case 3: When -/+ sign present in the amount column itself
            BigDecimal amount = AmountParserUtil.getAmount(content);
            if(content.contains("-")){
                transaction.setTransactionType(TransactionType.DEBIT);
            }else if(content.contains("+")){
                transaction.setTransactionType(TransactionType.CREDIT);
            }
            transaction.setTransactionAmount(getDebitCreditAmount(amount));
        } else {
            // Case 4: Default case - separate debit/credit columns
            BigDecimal amount = AmountParserUtil.getAmount(cell.getContent());
            transaction.setTransactionAmount(getDebitCreditAmount(amount));
            transaction.setTransactionType(colType == ColumnTransactionType.Debit ?
                        TransactionType.DEBIT : TransactionType.CREDIT);
        }
    }

    private static BigDecimal getDebitCreditAmount(BigDecimal amount) {
        return null == amount ? null : amount.abs();
    }

    private static boolean isValidContent(String content) {
        if (content == null || content.trim().isEmpty()) {
            return false;
        }

        String cleanContent = content.trim();

        // Check for single hyphen or dash
        if (cleanContent.equals("_") || cleanContent.equals("-") ||
            cleanContent.contains("NA") || cleanContent.contains("na") ||
            cleanContent.contains("n/a") || cleanContent.contains("N/A")) {
            return false;
        }

        // Check for zero values in different formats
        if(cleanContent.equals("0") || cleanContent.equals("0.00") || cleanContent.equals("0.0")){
            return false;
        }
        return true;
    }

    private BigDecimal parseAmount(String amount) {
        return new BigDecimal(amount.replaceAll("[^\\d.]", ""));
    }

