    private Map<String, AccountVO> mergeExistingAccounts(Map<String, AccountVO> accounts) {
        Map<String, AccountVO> mergedAccounts = new HashMap<>();

        String clientId = LoggingPropertiesUtil.getValueFromMDC("clientId");

        for (Map.Entry<String, AccountVO> entry : accounts.entrySet()) {
            AccountVO newAccount = entry.getValue();
            String key = entry.getKey();


            // Find existing account
            BankAccountEntity existingAccount = bankAccountRepository.findByAccountNumberAndAccountTypeAndBankCodeAndClientIdAndBusinessUserId(
                    KmsEncryptDecrypt.encryptData(newAccount.getBankAccountDetails().getAccountNumber()),
                    newAccount.getBankAccountDetails().getAccountType().toString(),
                    newAccount.getBankAccountDetails().getBankCode(),
                    clientId, LoggingPropertiesUtil.getValueFromMDC("businessUserId")
            );

            if (existingAccount != null) {
                LoggingPropertiesUtil.storeValueToMDC("accountUid", existingAccount.getAccountUid());

                newAccount.setExistingAccountDetails(existingAccount);

                // Update statement date range
                try {
                    // Parse existing account dates
                    Date existingFromDate = null;
                    Date existingToDate = null;
                    if (existingAccount.getStatementFrom() != null && !existingAccount.getStatementFrom().trim().isEmpty()) {
                        existingFromDate = parseDate(existingAccount.getStatementFrom());
                    }
                    if (existingAccount.getStatementTo() != null && !existingAccount.getStatementTo().trim().isEmpty()) {
                        existingToDate = parseDate(existingAccount.getStatementTo());
                    }

                    // Parse new account dates
                    Date newFromDate = null;
                    Date newToDate = null;
                    if (newAccount.getBankAccountDetails().getStatementFrom() != null &&
                            !newAccount.getBankAccountDetails().getStatementFrom().trim().isEmpty()) {
                        newFromDate = parseDate(newAccount.getBankAccountDetails().getStatementFrom());
                    }
                    if (newAccount.getBankAccountDetails().getStatementTo() != null &&
                            !newAccount.getBankAccountDetails().getStatementTo().trim().isEmpty()) {
                        newToDate = parseDate(newAccount.getBankAccountDetails().getStatementTo());
                    }

                    // Find the earliest from date
                    Date earliestFrom = null;
                    if (existingFromDate != null && newFromDate != null) {
                        earliestFrom = existingFromDate.before(newFromDate) ? existingFromDate : newFromDate;
                    } else if (existingFromDate != null) {
                        earliestFrom = existingFromDate;
                    } else if (newFromDate != null) {
                        earliestFrom = newFromDate;
                    }

                    // Find the latest to date
                    Date latestTo = null;
                    if (existingToDate != null && newToDate != null) {
                        latestTo = existingToDate.after(newToDate) ? existingToDate : newToDate;
                    } else if (existingToDate != null) {
                        latestTo = existingToDate;
                    } else if (newToDate != null) {
                        latestTo = newToDate;
                    }

                    SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

                    // Update the account details with the merged date range
                    if (earliestFrom != null) {
                        newAccount.getBankAccountDetails().setStatementFrom(sdf.format(earliestFrom));
                    }
                    if (latestTo != null) {
                        newAccount.getBankAccountDetails().setStatementTo(sdf.format(latestTo));
                    }
                } catch (Exception e) {
                    log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.FAILED.name(), "Error merging statement dates for account: " + newAccount.getAccountUid(), ExceptionDetails.exceptionDetails(e))));
                }


//                // Get existing transactions
//                List<BankTransactionEntity> existingTransactions = bankTransactionRepository
//                        .findAllByClientIdAndAccountUid(clientId, existingAccount.getAccountUid());

                // Get existing transactions
                List<BankTransactionEntity> existingTransactions = bankTransactionFetchService.fetchBankTransactions(existingAccount.getAccountUid(), clientId, true, true);

                if(existingTransactions != null && !existingTransactions.isEmpty()) {
                    // Convert to BankTransactionVO and set fileIndex=0 for existing transactions
                    List<BankTransactionVO> existingTransactionVOs = existingTransactions.stream()
                            .map(BankTransactionVO::new)
                            .peek(tx -> tx.setFileIndex(0))
                            .collect(Collectors.toList());

                    existingTransactionVOs.sort(Comparator.comparing(BankTransactionVO::getTransactionDate));

                    newAccount.setExistingTransactions(existingTransactionVOs);
                    newAccount.setIsExistingAccountInDatabase(true);

                    // Set fileIndex=1 for new transactions
                    newAccount.getBankTransactions().forEach(tx -> tx.setFileIndex(1));

                    // Merge transactions
                    List<BankTransactionVO> allTransactions = new ArrayList<>();
                    allTransactions.addAll(existingTransactionVOs);
                    allTransactions.addAll(newAccount.getBankTransactions());

                    // Remove duplicates
                    List<BankTransactionVO> uniqueTransactions = removeDuplicateTransactions(allTransactions);
                    uniqueTransactions.sort(Comparator.comparing(BankTransactionVO::getTransactionDate));

                    uniqueTransactions = uniqueTransactions.stream()
                            .filter(tx -> !tx.getTransactionDescription().contains("INCONSISTENT"))
                            .collect(Collectors.toList());

                    newAccount.setBankTransactions(uniqueTransactions);
                    newAccount.setAccountUid(existingAccount.getAccountUid());
                }
            }

            mergedAccounts.put(key, newAccount);
        }

        return mergedAccounts;
    }

    public boolean isOverDraftAccount(List<BankTransactionVO> bankTransactions){
        boolean overDraftAccount = Boolean.FALSE;

        if(null == bankTransactions || bankTransactions.isEmpty()) {
            return overDraftAccount;
        }

        // Group transactions by date
        Map<Date, List<BankTransactionVO>> bankTransactionListDateWise =
                bankTransactions.stream()
                        .filter(txn -> txn.getTransactionDescription() != null && !txn.getTransactionDescription().equalsIgnoreCase("<<<< INCONSISTENT >>>>"))
                        .collect(Collectors.groupingBy(BankTransactionVO::getTransactionDate));

        // Iterate through each date and its transactions
        for (Map.Entry<Date, List<BankTransactionVO>> entry : bankTransactionListDateWise.entrySet()) {
            Date date = entry.getKey();
            List<BankTransactionVO> transactions = entry.getValue();

            // Filter transactions with date less than or equal to current date
            List<BankTransactionVO> dateWiseTransactionForOD = transactions.stream()
                    .filter(transaction -> transaction.getTransactionDate().compareTo(date) <= 0)
                    .toList();

            // Check if last transaction has negative balance
            if (!dateWiseTransactionForOD.isEmpty()) {
                BigDecimal balance = dateWiseTransactionForOD.get(dateWiseTransactionForOD.size() - 1)
                        .getTransactionBalance();

                if (balance != null && balance.compareTo(BigDecimal.ZERO) < 0) {
                    overDraftAccount = Boolean.TRUE;
                    break; // We can exit early once we've found an overdraft
                }
            }
        }

        return overDraftAccount;


    }

    public void calculateEstimatedODLimit(List<BankTransactionVO> bankTransactionList, BankAccountDetailsVO bankAccount) {
        // New OD limit code which calculates lowest EOD balance and date
        try {
            OpeningAndClosingBalanceVO openingAndClosingBalancePerDay = bankAccountAnalysisService.findOpeningAndClosingBalancePerDay(bankTransactionList);

            // Sort by balance value and take the first entry (lowest balance)
            Map<Date, BigDecimal> closingBalanceMap = openingAndClosingBalancePerDay.getClosingBalance().entrySet().stream()
                    .sorted(Map.Entry.comparingByValue())
                    .limit(1)
                    .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

            Date txnDate = null;
            BigDecimal balance = BigDecimal.ZERO;

            if (!closingBalanceMap.isEmpty()) {
                // In Java we need to explicitly iterate over the map entry
                Map.Entry<Date, BigDecimal> entry = closingBalanceMap.entrySet().iterator().next();
                txnDate = entry.getKey();
                balance = entry.getValue();
            }

            if (balance.compareTo(BigDecimal.ZERO) < 0) {
                if (bankAccount.getAccountLimit() != null) {
                    BigDecimal absBalance = balance.abs().setScale(2, RoundingMode.HALF_UP);

                    if (bankAccount.getAccountLimit().compareTo(absBalance) < 0) {

                        bankAccount.setAccountLimit(absBalance);
                    }

                    if (bankAccount.getHighestODLimitUtilizationDate() == null) {
                        bankAccount.setHighestODLimitUtilizationDate(txnDate);
                    }
                } else {
                    bankAccount.setAccountLimit(balance.abs());
                    bankAccount.setHighestODLimitUtilizationDate(txnDate);
                }
            }
        } catch (Exception e) {
            log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.FAILED.name(), "Something went wrong while calculating OD limit", ExceptionDetails.exceptionDetails(e.getMessage()))));
        }
    }

    private static Integer findAmountTypeColumnIndex(Table table) {
        List<ColumnTransactionType> columnTypes = table.getTxnColType();
        for (int i = 0; i < columnTypes.size(); i++) {
            if (columnTypes.get(i) == ColumnTransactionType.AmountType) {
                return i;
            }
        }
        return null;
    }

    private static Integer findBalanceTypeColumnIndex(Table table) {
        List<ColumnTransactionType> columnTypes = table.getTxnColType();
        for (int i = 0; i < columnTypes.size(); i++) {
            if (columnTypes.get(i) == ColumnTransactionType.Balance) {
                return i;
            }
        }
        return null;
    }

    /**
     * Creates and adds an opening balance transaction to the beginning of the transaction list.
     * IMPORTANT: The opening balance transaction is for display purposes only and should not be included in analysis calculations.
     *
     * @param transactions List of existing transactions
     * @return Updated list with opening balance transaction as the first entry
     */
    private List<BankTransactionVO> addOpeningBalanceTransaction(List<BankTransactionVO> transactions) {
        if (transactions == null || transactions.isEmpty()) {
            return transactions;
        }

        // Get the first transaction to calculate opening balance
        BankTransactionVO firstTransaction = transactions.get(0);

        // Create opening balance transaction
        BankTransactionVO openingBalanceTransaction = new BankTransactionVO();

        // Set basic transaction details
        openingBalanceTransaction.setTransactionDate(firstTransaction.getTransactionDate());
        openingBalanceTransaction.setTransactionValueDate(firstTransaction.getTransactionValueDate());
        openingBalanceTransaction.setTransactionDescription("Opening Balance");
        openingBalanceTransaction.setUniqueTransactionId(UUID.randomUUID().toString());
        openingBalanceTransaction.setFileId(firstTransaction.getFileId());
        openingBalanceTransaction.setFileIndex(firstTransaction.getFileIndex());

        // Calculate opening balance based on first transaction's type
        BigDecimal openingBalance = firstTransaction.getTransactionType().equals(TransactionType.DEBIT)
                ? firstTransaction.getTransactionBalance().add(firstTransaction.getTransactionAmount())
                : firstTransaction.getTransactionBalance().subtract(firstTransaction.getTransactionAmount());

        // Set financial details
        openingBalanceTransaction.setTransactionBalance(openingBalance);
        openingBalanceTransaction.setTransactionAmount(BigDecimal.ZERO);
        openingBalanceTransaction.setTransactionType(TransactionType.CREDIT);
        openingBalanceTransaction.setTransactionCategoryLevel1(TransactionCategoryLevel1.OPENING_BALANCE);
        openingBalanceTransaction.setTransactionCategoryLevel2(TransactionCategoryLevel2.OPENING_BALANCE);

        // Create new list with opening balance as first transaction
        List<BankTransactionVO> updatedTransactions = new LinkedList<>();
        updatedTransactions.add(openingBalanceTransaction);
        updatedTransactions.addAll(transactions);

        return updatedTransactions;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.post.processor;

