import java.util.stream.Collectors;

/**
 * Service for extracting characters from PDF files with their coordinates
 * converted to inches and positioned relative to the top-left corner.
 */
@Service
@Slf4j
public class EPdfCharacterExtractionService {

    // Constants for conversion
    private static final float POINTS_PER_INCH = 72.0f;

    /**
     * Extracts characters from a PDF file with their coordinates and dimensions in inches.
     *
     * @param file The PDF file to process
     * @return A list of PageCharacters objects containing character information for each page
     * @throws IOException If there's an error reading the PDF
     */
    public List<EPdfPageCharacters> extractCharactersFromPDF(File file) throws IOException {
        List<EPdfPageCharacters> allPageCharacters = new LinkedList<>();

        try (PDDocument document = Loader.loadPDF(file)) {
            int pageCount = document.getNumberOfPages();
            log.info("Processing PDF with {} pages", pageCount);

            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();
                float pageHeightInPoints = cropBox.getHeight();

                CharacterExtractor extractor = new CharacterExtractor(pageHeightInPoints);
                //extractor.setSortByPosition(false);
                extractor.setStartPage(pageIndex + 1);
                extractor.setEndPage(pageIndex + 1);
                extractor.getText(document);

                EPdfPageCharacters pageCharacters = new EPdfPageCharacters();
                pageCharacters.setPageNumber(pageIndex + 1);
                pageCharacters.setWidth(convertPointsToInches(cropBox.getWidth()));
                pageCharacters.setHeight(convertPointsToInches(pageHeightInPoints));
                pageCharacters.setCharacters(extractor.getCharacters());

                allPageCharacters.add(pageCharacters);
                log.debug("Extracted {} characters from page {}",
                        extractor.getCharacters().size(), pageIndex + 1);
            }
        } catch (IOException e) {
            log.error("Error extracting characters from PDF: {}", e.getMessage(), e);
            throw e;
        }

        return allPageCharacters;
    }

    /**
     * Extracts characters from a PDDocument with their coordinates and dimensions in inches.
     *
     * @param document The PDDocument to process
     * @return A list of PageCharacters objects containing character information for each page
     * @throws IOException If there's an error reading the PDF
     */
    public List<EPdfPageCharacters> extractCharacters(PDDocument document) throws IOException {
        List<EPdfPageCharacters> allPageCharacters = new LinkedList<>();

        try {
            int pageCount = document.getNumberOfPages();
            log.info("Processing PDF document with {} pages", pageCount);

            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();
                float pageHeightInPoints = cropBox.getHeight();

                CharacterExtractor extractor = new CharacterExtractor(pageHeightInPoints);
                extractor.setSortByPosition(false);
                extractor.setStartPage(pageIndex + 1);
                extractor.setEndPage(pageIndex + 1);
                extractor.getText(document);

                EPdfPageCharacters pageCharacters = new EPdfPageCharacters();
                pageCharacters.setPageNumber(pageIndex + 1);
                pageCharacters.setWidth(convertPointsToInches(cropBox.getWidth()));
                pageCharacters.setHeight(convertPointsToInches(pageHeightInPoints));
                pageCharacters.setCharacters(extractor.getCharacters());

                allPageCharacters.add(pageCharacters);
                log.debug("Extracted {} characters from page {}",
                        extractor.getCharacters().size(), pageIndex + 1);
            }
        } catch (IOException e) {
            log.error("Error extracting characters from PDF document: {}", e.getMessage(), e);
            throw e;
        }

        return allPageCharacters;
    }

    /**
     * Enhances a DocumentExtractionResult with character-level information from a PDF file.
     * This method will add EPdfWord objects to each Word in the result if the PDF is electronic.
     *
     * @param result The DocumentExtractionResult to enhance
     * @param pdfFile The PDF file to extract character information from
     * @return true if enhancement was successful, false otherwise
     */
    public boolean enhanceDocumentWithCharacterInfo(DocumentExtractionResult result, File pdfFile) {
        try {
            // Extract character information from the PDF
            List<EPdfPageCharacters> pageCharactersList = extractCharactersFromPDF(pdfFile);

            // Print character information for each page
//            for (EPdfPageCharacters pageCharacters : pageCharactersList) {
//                log.info("Page {}: Character Information", pageCharacters.getPageNumber());
//
//                if (pageCharacters.getCharacters() != null) {
//                    for (EPdfCharacterInfo character : pageCharacters.getCharacters()) {
//                        log.info("Character: '{}', Position: x={}, y={}, width={}, height={}",
//                            character.getCharacter(),
//                            character.getX(), character.getY()
//                        , character.getWidth(), character.getHeight());
//                    }
//                }
//            }

            // If we have character information, enhance the document
            if (pageCharactersList != null && !pageCharactersList.isEmpty()) {
                enhanceDocumentWithCharacterInfo(result, pageCharactersList);
                return true;
            }

            return false;
        } catch (Exception e) {
            log.warn("Failed to enhance document with character-level information: {}", e.getMessage(), e);
            return false;
        }
    }

    /**
     * Enhances a DocumentExtractionResult with character-level information.
     * This method will add EPdfWord objects to each Word in the result.
     *
     * @param result The DocumentExtractionResult to enhance
     * @param pageCharactersList List of EPdfPageCharacters containing character information
     */
    public void enhanceDocumentWithCharacterInfo(DocumentExtractionResult result, List<EPdfPageCharacters> pageCharactersList) {
        if (result == null || pageCharactersList == null || pageCharactersList.isEmpty()) {
            return;
        }

        // Create a map for easier access by page number
        Map<Integer, EPdfPageCharacters> pageCharactersMap = new HashMap<>();
        for (EPdfPageCharacters pageCharacters : pageCharactersList) {
            pageCharactersMap.put(pageCharacters.getPageNumber(), pageCharacters);
        }

        // Process each page in the result
        for (Map.Entry<Integer, Page> pageEntry : result.getPages().entrySet()) {
            int pageNumber = pageEntry.getKey();
            Page page = pageEntry.getValue();

            // Get characters for this page
            EPdfPageCharacters pageCharacters = pageCharactersMap.get(pageNumber);
            if (pageCharacters == null || pageCharacters.getCharacters() == null || pageCharacters.getCharacters().isEmpty()) {
                continue;
            }

            // Process each word in the page
            enhancePageWithCharacterInfo(page, pageCharacters);
        }
    }

    /**
     * Enhances all words in a page with character-level information
     */
    private void enhancePageWithCharacterInfo(Page page, EPdfPageCharacters pageCharacters) {
        // Also process words that might be outside tables
        if (page.getWords() != null) {
            for (Word word : page.getWords()) {
                EPdfWord ePdfWord = createEPdfWordFromCharacters(word, pageCharacters);
                if (ePdfWord != null) {
                    word.setEPdfWord(ePdfWord);
                }
            }
        }

        // After initial assignment, check for unassigned characters and assign them to nearby words
        assignUnassignedCharactersToWords(page, pageCharacters);
    }

    /**
     * Assigns unassigned characters to the most appropriate nearby words
     * 
     * @param page The page containing words
     * @param pageCharacters The character information for the page
     */
    private void assignUnassignedCharactersToWords(Page page, EPdfPageCharacters pageCharacters) {
        if (page.getWords() == null || page.getWords().isEmpty() || 
            pageCharacters == null || pageCharacters.getCharacters() == null) {
            return;
        }

        // Get all unassigned characters
        List<EPdfCharacterInfo> unassignedCharacters = pageCharacters.getCharacters().stream()
                .filter(c -> !c.isAssigned())
                .collect(Collectors.toList());

        if (unassignedCharacters.isEmpty()) {
            return;
        }

        log.debug("Found {} unassigned characters on page {}", 
                unassignedCharacters.size(), pageCharacters.getPageNumber());

        // Filter words that have EPdfWord assigned
        List<Word> wordsWithEPdf = page.getWords().stream()
                .filter(w -> w.getEPdfWord() != null)
                .collect(Collectors.toList());

        // For each unassigned character, find the appropriate word based on horizontal proximity
        for (EPdfCharacterInfo character : unassignedCharacters) {
            Word bestMatchWord = findBestMatchingWord(character, wordsWithEPdf);

            if (bestMatchWord != null) {
                // Add the character to the word's EPdfWord
                EPdfWord ePdfWord = bestMatchWord.getEPdfWord();
                ePdfWord.getCharacters().add(character);
                ePdfWord.setContent(ePdfWord.generateContent());
                character.setAssigned(true);

                // Recalculate the word's polygon to include the new character
                calculateEPdfWordPolygon(ePdfWord, ePdfWord.getCharacters());

                log.debug("Assigned character '{}' to word '{}'", 
                        character.getCharacter(), bestMatchWord.getContent());
            }
        }
    }

    /**
     * Finds the best matching word for an unassigned character based on horizontal proximity
     * and vertical alignment.
     * 
     * @param character The character to find a word for
     * @param words List of words to search through
     * @return The best matching word, or null if none is found
     */
    private Word findBestMatchingWord(EPdfCharacterInfo character, List<Word> words) {
        // Character position
        float charX = character.getX();
        float charEndX = charX + character.getWidth();
        float charY = character.getY();
        float charHeight = character.getHeight();
        float midY = character.getY() - ( character.getHeight() / 2.0f);
        float midX = character.getX() + ( character.getWidth() / 2.0f);

        // Vertical tolerance - characters should be roughly on the same line
        final float VERTICAL_TOLERANCE = 0.03f; // in inches

        // Horizontal extension factor - how far beyond word boundaries to look
        float HORIZONTAL_EXTENSION = 0.02f; // in inches

        Word bestMatch = null;
        float minDistance = Float.MAX_VALUE;

        for (Word word : words) {
            Word ePdfWord = word;

            // Check vertical alignment first - characters should be on roughly the same line
//            float wordMidY = (ePdfWord.getY1() + ePdfWord.getY3()) / 2;
//            if (Math.abs(charY - wordMidY) > VERTICAL_TOLERANCE) {
//                continue; // Skip words that are not on the same line
//            }
            if( !(Math.min(Math.min(word.getY1(), word.getY2()),Math.min(word.getY3(), word.getY4()))< midY &&
                    Math.max(Math.max(word.getY1(), word.getY2()),Math.max(word.getY3(), word.getY4()))> midY)) {
                continue;
            }

            if(word.getEPdfWord() != null && !CollectionUtils.isEmpty(word.getEPdfWord().getCharacters())){
                HORIZONTAL_EXTENSION= word.getEPdfWord().getCharacters().stream().map(EPdfCharacterInfo::getWidth).max(Comparator.naturalOrder()).orElse(HORIZONTAL_EXTENSION);
            }

            // Word boundaries with extension
            float wordStartX = ePdfWord.getX1() - (HORIZONTAL_EXTENSION/4.0f);
            float wordEndX = ePdfWord.getX3() + (HORIZONTAL_EXTENSION/4.0f);

            if(midX >= wordStartX && wordEndX >= midX){
                return word;
            }

//            // Check if character is to the left of the word
//            else if (charEndX < wordStartX) {
//                float distance = wordStartX - charEndX;
//                if (distance < minDistance) {
//                    minDistance = distance;
//                    bestMatch = word;
//                }
//            }
//            // Check if character is to the right of the word
//            else if (charX > wordEndX) {
//                float distance = charX - wordEndX;
//                if (distance < minDistance) {
//                    minDistance = distance;
//                    bestMatch = word;
//                }
//            }
//            // Character overlaps with word's extended boundaries
//            else if (charX >= wordStartX && charEndX <= wordEndX) {
//                // This is a direct match within extended boundaries
//                return word;
//            }
        }

        // Only return a match if it's reasonably close
//        if (minDistance <= HORIZONTAL_EXTENSION * 2) {
//            return bestMatch;
//        }

        return null;
    }

    /**
     * Creates an EPdfWord object by finding characters that fall within the Word's polygon
     */
    private EPdfWord createEPdfWordFromCharacters(Word word, EPdfPageCharacters pageCharacters) {
        if (word == null || pageCharacters == null || pageCharacters.getCharacters() == null) {
            return null;
        }

        // Get the polygon coordinates of the word
        float x1 = word.getX1();
        float y1 = word.getY1();
        float x2 = word.getX2();
        float y2 = word.getY2();
        float x3 = word.getX3();
        float y3 = word.getY3();
        float x4 = word.getX4();
        float y4 = word.getY4();

        // Find characters that fall within the word's polygon
        List<EPdfCharacterInfo> matchingCharacters = pageCharacters.getCharacters().stream().filter(ePdfCharacterInfo -> !ePdfCharacterInfo.isAssigned())
                .filter(character -> isCharacterInWordPolygon(character, x1, y1, x2, y2, x3, y3, x4, y4))
                .collect(Collectors.toList());

        if (matchingCharacters.isEmpty()) {
            return null;
        }

        // Create EPdfWord with the matching characters
        EPdfWord ePdfWord = new EPdfWord();
        ePdfWord.setCharacters(matchingCharacters);
        matchingCharacters.forEach(character -> {character.setAssigned(true);});

        // Calculate polygon coordinates for the EPdfWord based on character positions
        calculateEPdfWordPolygon(ePdfWord, matchingCharacters);

        return ePdfWord;
    }

    /**
     * Determines if a character falls within a word's polygon
     */
    private boolean isCharacterInWordPolygon(EPdfCharacterInfo character, 
                                            float x1, float y1, float x2, float y2, 
                                            float x3, float y3, float x4, float y4) {
        // Get character bounds
        float charX = character.getX();
        float charY = character.getY();
        float charWidth = character.getWidth();
        float charHeight = character.getHeight();

        // Character center point
        float charCenterX = charX + (charWidth / 2);
        float charCenterY = charY - (charHeight / 2);

        // Simple bounding box check (for efficiency)
        float minX = Math.min(Math.min(x1, x2), Math.min(x3, x4));
        float maxX = Math.max(Math.max(x1, x2), Math.max(x3, x4));
        float minY = Math.min(Math.min(y1, y2), Math.min(y3, y4));
        float maxY = Math.max(Math.max(y1, y2), Math.max(y3, y4));

        // Relative height reducing to resolve very near line in pdf
        //float reduceY = 0.0f; // 2%

        // Check if character center is within the word's bounding box
//        return charCenterX >= minX && charCenterX <= maxX &&
//               charCenterY >= (minY + ((maxY-minY) * reduceY))  && charCenterY <= (maxY - ((maxY-minY) * reduceY));
        return charCenterX >= minX && charCenterX <= maxX &&
               charCenterY >= minY  && charCenterY <= maxY;
    }

    /**
     * Calculates the polygon coordinates for an EPdfWord based on its characters
     */
    private void calculateEPdfWordPolygon(EPdfWord ePdfWord, List<EPdfCharacterInfo> characters) {
        if (characters.isEmpty()) return;

        // Initialize with extreme values
        float minX = Float.MAX_VALUE;
        float minY = Float.MAX_VALUE;
        float maxX = Float.MIN_VALUE;
        float maxY = Float.MIN_VALUE;

        // Find the bounding box of all characters
        for (EPdfCharacterInfo character : characters) {
            float charX = character.getX();
            float charY = character.getY();
            float charWidth = character.getWidth();
            float charHeight = character.getHeight();

            minX = Math.min(minX, charX);
            minY = Math.min(minY, charY);
            maxX = Math.max(maxX, charX + charWidth);
            maxY = Math.max(maxY, charY + charHeight);
        }

        // Set polygon coordinates for the EPdfWord
        // Top-left
        ePdfWord.setX1(minX);
        ePdfWord.setY1(minY);

        // Top-right
        ePdfWord.setX2(maxX);
        ePdfWord.setY2(minY);

        // Bottom-right
        ePdfWord.setX3(maxX);
        ePdfWord.setY3(maxY);

        // Bottom-left
        ePdfWord.setX4(minX);
        ePdfWord.setY4(maxY);
    }

    /**
     * Converts points to inches
     */
    private float convertPointsToInches(float points) {
        return points / POINTS_PER_INCH;
    }

    /**
     * Custom PDF text stripper that extracts character information
     */
    private class CharacterExtractor extends PDFTextStripper {
        private final float pageHeight;
        private final List<EPdfCharacterInfo> characters;

        public CharacterExtractor(float pageHeight) throws IOException {
            super();
            this.pageHeight = pageHeight;
            this.characters = new LinkedList<>();
            this.setSortByPosition(true);
        }

        public List<EPdfCharacterInfo> getCharacters() {
            return characters;
        }

        @Override
        protected void processTextPosition(TextPosition text) {
            // Skip empty or whitespace-only characters
            String character = text.getUnicode();
            if (character == null) {
                return;
            }

            // Convert coordinates to top-left origin system and to inches
            float x = convertPointsToInches(text.getXDirAdj());
            // Flip y-coordinate to have origin at top-left
            float y = convertPointsToInches(text.getYDirAdj());
            float width = convertPointsToInches(text.getWidth());
            float height = convertPointsToInches(text.getHeight());

            // Create character info object
            EPdfCharacterInfo charInfo = new EPdfCharacterInfo();
            charInfo.setCharacter(character);
            charInfo.setX(x);
            charInfo.setY(y);
            charInfo.setWidth(width);
            charInfo.setHeight(height);
            charInfo.setFontSize(text.getFontSize() / POINTS_PER_INCH);
            charInfo.setFontName(text.getFont().getName());

            characters.add(charInfo);
        }
    }
}

package com.finboost.bank.statement.parser;

import com.finboost.bank.statement.parser.service.TestCaseGenerationService;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.data.mongodb.config.EnableMongoAuditing;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.web.client.RestTemplate;

import java.util.concurrent.Executor;
import java.util.concurrent.ThreadPoolExecutor;

@SpringBootApplication
@Configuration
@EnableMongoAuditing
@EnableAsync
@EnableScheduling
public class BankStatementParserApplication {

	public static void main(String[] args) {
		SpringApplication.run(BankStatementParserApplication.class, args);
	}

	@Bean
	public RestTemplate getRestTemplate() {
		return new RestTemplate();
	}

	@Bean
	public Executor taskExecutor() {
		ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
		executor.setCorePoolSize(4);
		executor.setMaxPoolSize(8);
		executor.setQueueCapacity(100);
		executor.setThreadNamePrefix("BankStatement-Processor-");
		executor.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());
		executor.setWaitForTasksToCompleteOnShutdown(true);
		executor.setAwaitTerminationSeconds(60);
		executor.initialize();
		return executor;
	}

	@Bean
	@Profile("generate-tests")
	public CommandLineRunner generateTestCases(TestCaseGenerationService testCaseGenerationService) {
		return args -> {
			// Default paths - can be overridden via command line args
			String pdfPath = "src/test/resources/pdf-samples-latest/TEST";
			String outputPath = "src/test/resources/pdf-test-config-latest_test.json";

			// Override if provided in args
			if (args.length >= 2) {
				pdfPath = args[0];
				outputPath = args[1];
			}

			testCaseGenerationService.generateTestCasesFromPdfSamples(pdfPath, outputPath);

			// If this is a standalone run just for test generation, exit
			if (System.getProperty("spring.profiles.active", "").contains("generate-tests-only")) {
				System.exit(0);
			}
		};
	}
