package com.finboost.bank.statement.parser.service.cache;
import com.azure.ai.documentintelligence.models.AnalyzeResult;
import com.azure.json.JsonOptions;
import com.azure.json.implementation.DefaultJsonReader;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.finboost.bank.statement.parser.representation.document.extraction.AccountSummary;
import org.apache.commons.io.FileUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

@Service
public class DocumentCacheService {
    private final ObjectMapper objectMapper;
    private final String cacheDirectoryTransaction;
    private final String cacheDirectoryBasicDetails;

    @Autowired
    public DocumentCacheService(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
        // Set cache directory to a subdirectory in the project
        this.cacheDirectoryTransaction = "src/test/resources/document-cache/transaction/";
        this.cacheDirectoryBasicDetails = "src/test/resources/document-cache/basicDetails/";
        createCacheDirectoryIfNotExists();
    }

    private void createCacheDirectoryIfNotExists() {
        File directory = new File(cacheDirectoryTransaction);
        if (!directory.exists()) {
            directory.mkdirs();
        }
        File directory2 = new File(cacheDirectoryBasicDetails);
        if (!directory2.exists()) {
            directory2.mkdirs();
        }
    }

    // Azure Document Intelligence cache methods
    public boolean isAzureResultCached(File documentFile) {
        String cacheFilePath = getAzureCacheFilePath(documentFile);
        return new File(cacheFilePath).exists();
    }

    public AnalyzeResult getAzureResultFromCache(File documentFile) throws IOException {
        String fileContent = FileUtils.readFileToString(new File(getAzureCacheFilePath(documentFile)), StandardCharsets.UTF_8);
        return AnalyzeResult.fromJson(DefaultJsonReader.fromString(fileContent, new JsonOptions()));
    }

    public void saveAzureResultToCache(File documentFile, AnalyzeResult analyzeResult) throws IOException {
        String cacheFilePath = getAzureCacheFilePath(documentFile);
        try (FileOutputStream fileOutputStream = new FileOutputStream(cacheFilePath)) {
            analyzeResult.toJson( fileOutputStream);
        }
    }

    private String getAzureCacheFilePath(File documentFile) {
        String fileName = documentFile.getName();
        String baseName = StringUtils.stripFilenameExtension(fileName);

        // Get the parent directory name (bank name)
        String bankName = documentFile.getParentFile().getName();

        return cacheDirectoryTransaction + bankName + "-" + baseName + "-azure-cache.json";
    }

    // Basic Details (OpenAI) cache methods
    public boolean isBasicDetailsCached(File documentFile) {
        String cacheFilePath = getBasicDetailsCacheFilePath(documentFile);
        return new File(cacheFilePath).exists();
    }

    public String getBasicDetailsFromCache(File documentFile) throws IOException {
        String cacheFilePath = getBasicDetailsCacheFilePath(documentFile);
        return objectMapper.readValue(new File(cacheFilePath),String.class);
    }

    public void saveBasicDetailsToCache(File documentFile, String accountSummary) throws IOException {
        String cacheFilePath = getBasicDetailsCacheFilePath(documentFile);
        objectMapper.writeValue(new File(cacheFilePath), accountSummary);
    }

    private String getBasicDetailsCacheFilePath(File documentFile) {
        String fileName = documentFile.getName();
        String baseName = StringUtils.stripFilenameExtension(fileName);

        // Get the parent directory name (bank name)
        String bankName = documentFile.getParentFile().getName();

        return cacheDirectoryBasicDetails  + bankName + "-" + baseName + "-basic-details-new-cache.json";
    }
