package com.finboost.bank.statement.parser.service.document.extraction.post.processor;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import lombok.Data;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class TableRowNormalizer {

    public DocumentExtractionResult normalizeTableRows(DocumentExtractionResult result) {
        if (result.getPages() == null) return result;

        // Process each page
        for (Map.Entry<Integer, Page> pageEntry : result.getPages().entrySet()) {
            Page page = pageEntry.getValue();
            if (page.getTables() == null) continue;

            // Process each table in the page
            for (Map.Entry<Integer, Table> tableEntry : page.getTables().entrySet()) {
                Table table = tableEntry.getValue();

                // Check if it's a bank transaction table
                //if (!table.isBankTransactions()) continue;

                // Find and normalize tables with rowspan
                if (hasRowspan(table)) {
                    Table normalizedTable = normalizeTableFromMaxRowspan(table);
                    page.getTables().put(tableEntry.getKey(), normalizedTable);
                }
            }
        }
        return result;
    }

    private boolean hasRowspan(Table table) {
        return table.getCells().values().stream()
                .flatMap(row -> row.values().stream())
                .anyMatch(cell -> cell.getRowspan() != null && cell.getRowspan() > 1);
    }

    private Table normalizeTableFromMaxRowspan(Table table) {
        // Create new table with same properties
        Table normalizedTable = new Table();
        copyTableProperties(table, normalizedTable);

        // Copy the original table cells to work with
        Map<Integer, Map<Integer, TableCell>> workingCells = new HashMap<>();
        for (Map.Entry<Integer, Map<Integer, TableCell>> rowEntry : table.getCells().entrySet()) {
            workingCells.put(rowEntry.getKey(), new HashMap<>(rowEntry.getValue()));
        }
        int loopCounter = 0;

        // Process until no rowspan cells remain
        while (hasRowspan(new Table() {{ setCells(workingCells); }})) {
            // Find the max rowspan cell
            loopCounter++;
            TableCell maxRowspanCell = findMaxRowspanCell(workingCells);
            if (maxRowspanCell == null) break;

            int startRowIndex = maxRowspanCell.getRowindex();
            int rowspan = maxRowspanCell.getRowspan();
            int colIndex = maxRowspanCell.getColindex();

            // Find row segments for the rows affected by this rowspan
            List<RowSegment> segments = new ArrayList<>();
            for (int i = 0; i < rowspan; i++) {
                int currentRowIndex = startRowIndex+i;
                Map<Integer, TableCell> row = workingCells.get(currentRowIndex);

                if (row != null) {
                    // Calculate row boundaries using cells without rowspan
                    Float rowStartY = row.values().stream()
                            .filter(cell -> cell.getRowspan() == null || cell.getRowspan() == 1)
                            .map(cell -> Math.min(cell.getY1(), cell.getY2()))
                            .min(Float::compareTo)
                            .orElse(null);

                    Float rowEndY = row.values().stream()
                            .filter(cell -> cell.getRowspan() == null || cell.getRowspan() == 1)
                            .map(cell -> Math.max(cell.getY3(), cell.getY4()))
                            .max(Float::compareTo)
                            .orElse(null);

                    // If we couldn't determine boundaries from non-rowspan cells, use adjacent rows
                    if (rowStartY == null || rowEndY == null) {
                        // Try to infer from adjacent rows
                        if (i > 0) {
                            RowSegment prevSegment = segments.get(i - 1);
                            rowStartY = prevSegment.getEndY();
                            // Estimate row height based on previous rows
                            float avgRowHeight = (prevSegment.getEndY() - prevSegment.getStartY());
                            rowEndY = rowStartY + avgRowHeight;
                        } else if (i < rowspan - 1) {
                            // Will be adjusted in a second pass
                            rowStartY = maxRowspanCell.getY1();
                            rowEndY = rowStartY; // Temporary
                        }
                    }

                    RowSegment segment = new RowSegment();
                    segment.setRowIndex(currentRowIndex);
                    segment.setStartY(rowStartY);
                    segment.setEndY(rowEndY);
                    segments.add(segment);
                }
            }

            // Adjust segments if needed
            if (!segments.isEmpty()) {
                // Ensure first segment starts at the rowspan cell's top
                //segments.get(0).setStartY(Math.min(maxRowspanCell.getY1(), maxRowspanCell.getY2()));

                // Ensure last segment ends at the rowspan cell's bottom
                //segments.get(segments.size() - 1).setEndY(Math.max(maxRowspanCell.getY3(), maxRowspanCell.getY4()));

                // Distribute words to segments
                List<Word> allWords = new ArrayList<>(maxRowspanCell.getWords());
                for (Word word : allWords) {
                    boolean assigned = false;
                    for (RowSegment segment : segments) {
                        if (isWordInSegment(word, segment)) {
                            segment.getWords().add(word);
                            assigned = true;
                            break;
                        }
                    }

                    // If word wasn't assigned to any segment, put it in the first segment
                    if (!assigned && !segments.isEmpty()) {
                        segments.get(0).getWords().add(word);
                    }
                }

                // Create new cells for each segment
                for (RowSegment segment : segments) {
                    TableCell newCell = new TableCell();
                    copyBasicCellProperties(maxRowspanCell, newCell, segment);
                    newCell.setWords(segment.getWords());
                    newCell.setRowspan(1);

