import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;

import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.*;

public class Analyze {

    static class Seg {
        float x1, y1, x2, y2;
        Seg(float x1, float y1, float x2, float y2) { this.x1=x1; this.y1=y1; this.x2=x2; this.y2=y2; }
    }

    static class Rect {
        float x, y, w, h;
        Rect(float x, float y, float w, float h) { this.x=x; this.y=y; this.w=w; this.h=h; }
    }

    static class Engine extends PDFGraphicsStreamEngine {
        List<Seg> segs = new ArrayList<>();
        List<Rect> rects = new ArrayList<>();
        List<Point2D> path = new ArrayList<>();
        List<float[]> pendingRects = new ArrayList<>();
        float ph;

        Engine(PDPage page) { super(page); ph = page.getCropBox().getHeight(); }

        void run() throws IOException { processPage(getPage()); }

        @Override public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minx = (float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX()));
            float maxx = (float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX()));
            float miny = (float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY()));
            float maxy = (float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY()));
            pendingRects.add(new float[]{minx, miny, maxx - minx, maxy - miny});
        }
        @Override public void drawImage(PDImage pdImage) {}
        @Override public void clip(int windingRule) {}
        @Override public void moveTo(float x, float y) { path.add(new Point2D.Float(x, y)); }
        @Override public void lineTo(float x, float y) { path.add(new Point2D.Float(x, y)); }
        @Override public Point2D getCurrentPoint() { return path.isEmpty() ? new Point2D.Float(0,0) : path.get(path.size()-1); }
        @Override public void closePath() {}
        @Override public void endPath() { path.clear(); pendingRects.clear(); }
        @Override public void strokePath() { flush(); }
        @Override public void fillPath(int windingRule) { flush(); }
        @Override public void fillAndStrokePath(int windingRule) { flush(); }
        @Override public void shadingFill(COSName shadingName) {}
        @Override public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) { path.add(new Point2D.Float(x3, y3)); }

        void flush() {
            for (int i = 0; i + 1 < path.size(); i++) {
                Point2D a = path.get(i), b = path.get(i+1);
                segs.add(new Seg((float) a.getX(), (float) a.getY(), (float) b.getX(), (float) b.getY()));
            }
            for (float[] r : pendingRects) rects.add(new Rect(r[0], r[1], r[2], r[3]));
            path.clear();
            pendingRects.clear();
        }
    }

    public static void main(String[] args) throws Exception {
        File root = new File(args[0]);
        File[] banks = root.listFiles();
        Arrays.sort(banks);
        for (File bank : banks) {
            if (!bank.isDirectory()) continue;
            File[] pdfs = bank.listFiles();
            Arrays.sort(pdfs);
            for (File pdf : pdfs) {
                try {
                    analyze(bank.getName(), pdf);
                } catch (Exception e) {
                    System.out.printf("%s/%s ERROR %s%n", bank.getName(), pdf.getName(), e);
                }
            }
        }
    }

    static void analyze(String bank, File pdf) throws IOException {
        try (PDDocument doc = Loader.loadPDF(pdf)) {
            int pages = doc.getNumberOfPages();
            int maxPage = Math.min(pages, 3);
            int hLines = 0, vLines = 0, boxes = 0, thinRects = 0;
            Set<Integer> hys = new TreeSet<>(), vxs = new TreeSet<>();
            float pw = 0, ph = 0;
            int longH = 0, longV = 0;
            for (int i = 0; i < maxPage; i++) {
                PDPage page = doc.getPage(i);
                PDRectangle cb = page.getCropBox();
                pw = cb.getWidth(); ph = cb.getHeight();
                Engine e = new Engine(page);
                try { e.run(); } catch (Exception ex) { }
                for (Seg s : e.segs) {
                    float dx = Math.abs(s.x2 - s.x1), dy = Math.abs(s.y2 - s.y1);
                    if (dy <= 1.0f && dx > 20) { hLines++; hys.add(Math.round(s.y1)); if (dx > pw * 0.4) longH++; }
                    else if (dx <= 1.0f && dy > 20) { vLines++; vxs.add(Math.round(s.x1)); if (dy > 60) longV++; }
                }
                for (Rect r : e.rects) {
                    if (r.h <= 1.5f && r.w > 20) { hLines++; thinRects++; hys.add(Math.round(r.y)); if (r.w > pw*0.4) longH++; }
                    else if (r.w <= 1.5f && r.h > 20) { vLines++; thinRects++; vxs.add(Math.round(r.x)); if (r.h > 60) longV++; }
                    else if (r.w > 20 && r.h > 5) boxes++;
                }
            }
            PDFTextStripper st = new PDFTextStripper();
            st.setStartPage(1); st.setEndPage(Math.min(pages, 2));
            String text = st.getText(doc);
            int chars = text.replaceAll("\\s", "").length();
            System.out.printf("%-32s %-12s pages=%-3d hL=%-4d vL=%-4d longH=%-4d longV=%-4d hy=%-3d vx=%-3d boxes=%-5d text=%-6d%n",
                    bank, pdf.getName(), pages, hLines, vLines, longH, longV, hys.size(), vxs.size(), boxes, chars);
        }
    }
}

