import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpHeaders;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.UUID;
import java.math.BigDecimal;
import java.text.SimpleDateFormat;
import java.text.ParseException;
import java.util.List;
import java.util.ArrayList;

@RestController
@RequestMapping("/api/document")
public class TestController {
    private static final Logger logger = LoggerFactory.getLogger(TestController.class);

    private DocumentExtractionService documentExtractionService;

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setDocumentExtractionService(DocumentExtractionService documentExtractionService) {
        this.documentExtractionService = documentExtractionService;
    }

    @Autowired
    private IBankTransactionCategorisationService bankTransactionCategorisationService;

    @PostMapping(
            value = "/analyze",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
            produces = MediaType.TEXT_HTML_VALUE
    )
    public ResponseEntity<?> analyzeDocument(@RequestParam("file") MultipartFile file, @RequestParam(name = "bank" ,required = false) String bank, @RequestParam(name = "fromDate" ,required = false) String fromDate) {
        try {
            // Validate file
            if (file.isEmpty()) {
                return ResponseEntity.badRequest().body("Please upload a file");
            }

            // Create temp file
            String originalFilename = file.getOriginalFilename();
            String fileExtension = originalFilename != null ?
                    originalFilename.substring(originalFilename.lastIndexOf(".")) : ".tmp";
            Path tempFile = Files.createTempFile("upload_", fileExtension);

            // Transfer multipart file to temp file
            file.transferTo(tempFile.toFile());

            try {
                SimpleDateFormat sdf = new SimpleDateFormat("dd-MM-yyyy");
                DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
                documentExtractionRequest.setStatementFile(tempFile.toFile());
                documentExtractionRequest.setBankName(bank);
                if(fromDate != null) {
                    documentExtractionRequest.setStatementFromDate(sdf.parse(fromDate));
                }
                // Process the document
                DocumentExtractionResult documentExtractionResult = documentExtractionService.extractDocument(documentExtractionRequest);

                // Add wrapper HTML to make it display properly in browser
                String fullHtmlContent = DocumentExtractionResultHtmlConverterUtil.convertToHtml(documentExtractionResult);

                // Set headers for proper HTML display
                HttpHeaders headers = new HttpHeaders();
                headers.setContentType(MediaType.TEXT_HTML);

                return ResponseEntity.ok()
                        .headers(headers)
                        .body(fullHtmlContent);

            } finally {
                // Clean up temp file
                Files.deleteIfExists(tempFile);
            }

        } catch (IOException e) {
            logger.error("Error processing file upload", e);
            return ResponseEntity.internalServerError()
                    .body("Error processing file: " + e.getMessage());
        } catch (Exception e) {
            logger.error("Unexpected error during document analysis", e);
            return ResponseEntity.internalServerError()
                    .body("Unexpected error: " + e.getMessage());
        }
    }

    // Optional: Add an endpoint to download the HTML
    @PostMapping(
            value = "/analyze/download",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
            produces = MediaType.TEXT_HTML_VALUE
    )
    public ResponseEntity<?> downloadAnalysis(@RequestParam("file") MultipartFile file) {
        try {
            // Validate file
            if (file.isEmpty()) {
                return ResponseEntity.badRequest().body("Please upload a file");
            }

            // Create temp file
            Path tempFile = Files.createTempFile("upload_", ".tmp");
            file.transferTo(tempFile.toFile());
            String originalFilename = getFileNameWithoutExtension(file);

            try {
                DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
                documentExtractionRequest.setStatementFile(tempFile.toFile());
                documentExtractionRequest.setBankName(null);
                // Process the document
                DocumentExtractionResult documentExtractionResult = documentExtractionService.extractDocument(documentExtractionRequest);

                // Add wrapper HTML to make it display properly in browser
                String fullHtmlContent = DocumentExtractionResultHtmlConverterUtil.convertToHtml(documentExtractionResult);

                // Set headers for file download
                HttpHeaders headers = new HttpHeaders();
                headers.setContentType(MediaType.TEXT_HTML);
                headers.setContentDispositionFormData("attachment", originalFilename+"_analysis_result.html");

                return ResponseEntity.ok()
                        .headers(headers)
                        .body(fullHtmlContent);

            } finally {
                // Clean up temp file
                Files.deleteIfExists(tempFile);
            }

        } catch (Exception e) {
            logger.error("Error processing file for download", e);
            return ResponseEntity.internalServerError()
                    .body("Error processing file: " + e.getMessage());
        }
    }

    private String getFileNameWithoutExtension(MultipartFile file) {
        String originalFileName = file.getOriginalFilename();

        // Check if file name is null or empty
        if (originalFileName == null || originalFileName.isEmpty()) {
            return "";
        }

        // Find the last occurrence of '.' in the filename
        int lastDotIndex = originalFileName.lastIndexOf('.');

        // If no extension exists, return the original filename
        if (lastDotIndex == -1) {
            return originalFileName;
        }

        // Return substring from start to last dot
        return originalFileName.substring(0, lastDotIndex);
    }

    @PostMapping(
            value = "/process-statement",
            consumes = MediaType.APPLICATION_JSON_VALUE,
            produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<?> processStatement(@RequestBody StatementRequestDTO requestDTO) {
        try {
            logger.info("Processing statement for account: {}", requestDTO.getAccount_number());

            // Create BankStatementVO
            BankStatementVO bankStatementVO = new BankStatementVO();
            bankStatementVO.setBank(requestDTO.getBank_name());

            // Map account type
            try {
                bankStatementVO.setAccountType(AccountType.valueOf(requestDTO.getAccount_type()));
            } catch (IllegalArgumentException e) {
                logger.warn("Invalid account type: {}", requestDTO.getAccount_type());
                return ResponseEntity.badRequest().body("Invalid account type: " + requestDTO.getAccount_type());
            }

            // Create BankAccountDetailsVO
            BankAccountDetailsVO bankAccountDetailsVO = new BankAccountDetailsVO();
            bankAccountDetailsVO.setAccountHolderName(requestDTO.getAccount_holder_name());
            bankAccountDetailsVO.setAccountNumber(requestDTO.getAccount_number());
            bankAccountDetailsVO.setAccountType(bankStatementVO.getAccountType());

            // Create list of BankTransactionVO
            List<BankTransactionVO> transactions = new ArrayList<>();

            if (requestDTO.getTransactions() != null) {
                for (TransactionDTO transactionDTO : requestDTO.getTransactions()) {
                    BankTransactionVO transactionVO = new BankTransactionVO();
                    transactionVO.setUniqueTransactionId(transactionDTO.getTransaction_id());

                    // Parse dates
                    try {
                        SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");
                        if (transactionDTO.getTransaction_date() != null) {
                            transactionVO.setTransactionDate(dateFormat.parse(transactionDTO.getTransaction_date()));
                        }
                        if (transactionDTO.getValue_date() != null) {
                            transactionVO.setTransactionValueDate(dateFormat.parse(transactionDTO.getValue_date()));
                        }
                    } catch (ParseException e) {
                        logger.warn("Error parsing date: {}", e.getMessage());
                    }

                    transactionVO.setTransactionDescription(transactionDTO.getDescription());

                    // Map transaction type
                    if ("DEBIT".equals(transactionDTO.getTransaction_type())) {
                        transactionVO.setTransactionType(TransactionType.DEBIT);
                    } else if ("CREDIT".equals(transactionDTO.getTransaction_type())) {
                        transactionVO.setTransactionType(TransactionType.CREDIT);
                    }

                    // Set amount and balance
                    if (transactionDTO.getAmount() != null) {
                        transactionVO.setTransactionAmount(BigDecimal.valueOf(transactionDTO.getAmount()));
                    }
                    if (transactionDTO.getBalance() != null) {
                        transactionVO.setTransactionBalance(BigDecimal.valueOf(transactionDTO.getBalance()));
                    }

                    transactions.add(transactionVO);
                }
            }

            // Assign to BankStatementVO
            bankStatementVO.setBankAccountDetailsVO(bankAccountDetailsVO);
            bankStatementVO.setBankTransactions(transactions);

            // Categorize transactions
            List<BankTransactionVO> categorizedTransactions = bankTransactionCategorisationService.categoriseBankTransaction(bankStatementVO);

            // Update the bank statement with categorized transactions
            bankStatementVO.setBankTransactions(categorizedTransactions);

            // Convert to response format
            StatementResponseDTO responseDTO = convertToResponseFormat(bankStatementVO);

            return ResponseEntity.ok(responseDTO);

        } catch (Exception e) {
            logger.error("Error processing statement", e);
            return ResponseEntity.internalServerError()
                    .body("Error processing statement: " + e.getMessage());
        }
    }

    private StatementResponseDTO convertToResponseFormat(BankStatementVO bankStatementVO) {
        StatementResponseDTO responseDTO = new StatementResponseDTO();

        // Set basic details
        responseDTO.setBank_name(bankStatementVO.getBank());
        responseDTO.setAccount_type(bankStatementVO.getAccountType() != null ?
                bankStatementVO.getAccountType().name() : null);

        // Set account details
        if (bankStatementVO.getBankAccountDetailsVO() != null) {
            responseDTO.setAccount_holder_name(bankStatementVO.getBankAccountDetailsVO().getAccountHolderName());
            responseDTO.setAccount_number(bankStatementVO.getBankAccountDetailsVO().getAccountNumber());
        }

        // Set transactions
        List<TransactionResponseDTO> transactionDTOs = new ArrayList<>();
        if (bankStatementVO.getBankTransactions() != null) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("dd/MM/yyyy");

            for (BankTransactionVO transaction : bankStatementVO.getBankTransactions()) {
                TransactionResponseDTO transactionDTO = new TransactionResponseDTO();

                transactionDTO.setTransaction_id(transaction.getUniqueTransactionId());

                if (transaction.getTransactionDate() != null) {
                    transactionDTO.setTransaction_date(dateFormat.format(transaction.getTransactionDate()));
                }

                if (transaction.getTransactionValueDate() != null) {
                    transactionDTO.setValue_date(dateFormat.format(transaction.getTransactionValueDate()));
                }

                transactionDTO.setDescription(transaction.getTransactionDescription());

                if (transaction.getTransactionType() != null) {
                    transactionDTO.setTransaction_type(transaction.getTransactionType().name());
                }

                if (transaction.getTransactionAmount() != null) {
                    transactionDTO.setAmount(transaction.getTransactionAmount().doubleValue());
                }

                if (transaction.getTransactionBalance() != null) {
                    transactionDTO.setBalance(transaction.getTransactionBalance().doubleValue());
                }

                // Set categorization details
                if (transaction.getTransactionCategoryLevel1() != null) {
                    transactionDTO.setTransactionCategoryLevel1(transaction.getTransactionCategoryLevel1().name());
                }

                if (transaction.getTransactionCategoryLevel2() != null) {
                    transactionDTO.setTransactionCategoryLevel2(transaction.getTransactionCategoryLevel2().name());
                }

                transactionDTO.setMerchantName(transaction.getMerchantName());
                transactionDTO.setTransactionMode(transaction.getTransactionMode());

                transactionDTOs.add(transactionDTO);
            }
        }

        responseDTO.setTransactions(transactionDTOs);

        return responseDTO;
    }

    // Inner DTOs for request parsing
    @Data
    private static class StatementRequestDTO {
        private String bank_name;
        private String account_type;
        private String account_holder_name;
        private String account_number;
        private List<TransactionDTO> transactions;
    }

    @Data
    private static class TransactionDTO {
        private String transaction_id;
        private String transaction_date;
        private String value_date;
        private String description;
        private String transaction_type;
        private Double amount;
        private Double balance;
    }

    // Response DTOs
    @Data
    private static class StatementResponseDTO {
        private String bank_name;
        private String account_type;
        private String account_holder_name;
        private String account_number;
        private List<TransactionResponseDTO> transactions;
    }

    @Data
    private static class TransactionResponseDTO {
        private String transaction_id;
        private String transaction_date;
        private String value_date;
        private String description;
        private String transaction_type;
        private Double amount;
        private Double balance;
        private String transactionCategoryLevel1;
        private String transactionCategoryLevel2;
        private String merchantName;
        private String transactionMode;
    }
}
package com.finboost.bank.statement.parser.service;

import com.finboost.bank.statement.parser.util.TestCaseGenerator;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;

@Service
public class TestCaseGenerationService {

    private final TestCaseGenerator testCaseGenerator;

    @Autowired
    public TestCaseGenerationService(TestCaseGenerator testCaseGenerator) {
        this.testCaseGenerator = testCaseGenerator;
    }

    public void generateTestCasesFromPdfSamples(String pdfSamplesPath, String outputJsonPath) {
        System.out.println("Starting test case generation...");
        try {
            // Ensure the output directory exists
            File outputFile = new File(outputJsonPath);
            File outputDir = outputFile.getParentFile();
            if (outputDir != null && !outputDir.exists()) {
                outputDir.mkdirs();
                System.out.println("Created output directory: " + outputDir.getAbsolutePath());
            }

            // Generate test cases (now with incremental support)
            testCaseGenerator.generateTestCases(pdfSamplesPath, outputJsonPath);
            System.out.println("Test case generation completed successfully!");
        } catch (Exception e) {
            System.err.println("Error generating test cases: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

