package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * Indicates how the transaction tables of a statement (or of an account, once the
 * statement level values are aggregated) have been extracted.
 *
 * <ul>
 *     <li>{@link #NATIVE} - the offline/native table extraction produced the tables and no
 *     remote ML extraction has been invoked at all.</li>
 *     <li>{@link #ML} - the remote ML (Azure Document Intelligence) extraction produced the
 *     tables. This is the default for unknown/unsupported layouts.</li>
 *     <li>{@link #NATIVE_FALLBACK_ML} - the native extraction was attempted for a supported
 *     layout, did not produce a usable transaction table, and the remote ML extraction was
 *     used instead.</li>
 * </ul>
 */
public enum ExtractionMode {

    NATIVE,
    ML,
    NATIVE_FALLBACK_ML;

    /**
     * Aggregates the extraction mode of several statements into a single account level value.
     * When every statement resolved to the same mode that mode is returned. A mixed result
     * always means that at least one statement of the account had to be processed by the
     * remote ML extraction after a native attempt, therefore it is reported as
     * {@link #NATIVE_FALLBACK_ML}.
     *
     * @param current  already aggregated value, may be {@code null}
     * @param addition the mode of the next statement, may be {@code null}
     * @return the aggregated extraction mode
     */
    public static ExtractionMode aggregate(ExtractionMode current, ExtractionMode addition) {
        if (addition == null) {
            return current;
        }
        if (current == null || current == addition) {
            return addition;
        }
        return NATIVE_FALLBACK_ML;
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * Diagnostics describing which extraction path has been used for a single statement.
 * The information is surfaced on the API objects and stored with the request logs so that
 * the native / ML mix of a request can be analysed afterwards.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeExtractionDiagnostics {

    /** Whether the statement was parsed natively, remotely (ML) or natively with an ML fallback. */
    private ExtractionMode extractionMode = ExtractionMode.ML;

    /** The layout that produced the native tables, {@code null} when the ML path was used. */
    private NativeTableLayout appliedLayout;

    /** The layouts that were attempted before a result (or the fallback) was reached. */
    private List<NativeTableLayout> attemptedLayouts = new ArrayList<>();

    /** Why the native path was skipped or abandoned, {@code null} when the native path succeeded. */
    private String fallbackReason;

    /** Number of native table rows handed over to the downstream analysis. */
    private Integer nativeRowCount;

    /** Number of native tables handed over to the downstream analysis. */
    private Integer nativeTableCount;

    public static NativeExtractionDiagnostics ml(String reason) {
        NativeExtractionDiagnostics diagnostics = new NativeExtractionDiagnostics();
        diagnostics.setExtractionMode(ExtractionMode.ML);
        diagnostics.setFallbackReason(reason);
        return diagnostics;
    }

    public NativeExtractionDiagnostics copy() {
        return new NativeExtractionDiagnostics(
                this.extractionMode,
                this.appliedLayout,
                this.attemptedLayouts == null ? new ArrayList<>() : new ArrayList<>(this.attemptedLayouts),
                this.fallbackReason,
                this.nativeRowCount,
                this.nativeTableCount
        );
    }

    public String getAppliedLayoutName() {
        return appliedLayout == null ? null : appliedLayout.name();
    }

    public String getExtractionModeName() {
        return extractionMode == null ? null : extractionMode.name();
    }
}

