@Data
@NoArgsConstructor
public class EPdfWord {
    private List<EPdfCharacterInfo> characters;
    private String content; // New field to store the text content

    // Polygon coordinates (from top-left corner)
    private float x1; // Top-left x
    private float y1; // Top-left y
    private float x2; // Top-right x
    private float y2; // Top-right y
    private float x3; // Bottom-right x
    private float y3; // Bottom-right y
    private float x4; // Bottom-left x
    private float y4; // Bottom-left y

    /**
     * Constructor that automatically sets the content field
     */
    public EPdfWord(List<EPdfCharacterInfo> characters, 
                   float x1, float y1, float x2, float y2, 
                   float x3, float y3, float x4, float y4) {
        this.characters = characters;
        this.x1 = x1;
        this.y1 = y1;
        this.x2 = x2;
        this.y2 = y2;
        this.x3 = x3;
        this.y3 = y3;
        this.x4 = x4;
        this.y4 = y4;
        this.content = generateContent();
    }

    /**
     * Sets the characters and automatically updates the content
     */
    public void setCharacters(List<EPdfCharacterInfo> characters) {
        this.characters = characters;
        this.content = generateContent();
    }

    /**
     * Creates a deep copy of this EPdfWord
     */
    public EPdfWord copy() {
        EPdfWord copy = new EPdfWord();
        copy.characters = this.characters.stream()
                .map(EPdfCharacterInfo::copy)
                .collect(Collectors.toList());
        copy.content = this.content;
        copy.x1 = this.x1;
        copy.y1 = this.y1;
        copy.x2 = this.x2;
        copy.y2 = this.y2;
        copy.x3 = this.x3;
        copy.y3 = this.y3;
        copy.x4 = this.x4;
        copy.y4 = this.y4;
        return copy;
    }

    /**
     * Gets the text content of this word by concatenating all characters
     */
    public String getText() {
        return content;
    }

    /**
     * Generates the content string from the characters, sorted by X and Y coordinates
     * to preserve reading order
     */
    public String generateContent() {
        if (characters == null || characters.isEmpty()) {
            return "";
        }

        // Create a copy of the characters list to avoid modifying the original
        List<EPdfCharacterInfo> sortedCharacters = new ArrayList<>(characters);

        // Sort characters primarily by Y position (with a small tolerance for same line)
        // and secondarily by X position
        final float Y_TOLERANCE = 0.0f; // Tolerance for considering characters on the same line (in inches)

        sortedCharacters.sort((c1, c2) -> {
            // If characters are roughly on the same line, sort by X coordinate
            if (Math.abs(c1.getY() - c2.getY()) < Y_TOLERANCE) {
                return Float.compare(c1.getX(), c2.getX());
            }
            // Otherwise, sort by Y coordinate
            return Float.compare(c1.getY(), c2.getY());
        });

        // Build the content string from sorted characters
        StringBuilder text = new StringBuilder();
        for (EPdfCharacterInfo character : sortedCharacters) {
            text.append(character.getCharacter());
        }
        return text.toString();
    }
}
