package com.finboost.bank.statement.parser.service.document.extraction.post.processor;

import com.finboost.bank.statement.parser.config.requestlog.RequestStatus;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.representation.structureLogging.ExceptionDetails;
import com.finboost.bank.statement.parser.util.JsonUtil;
import com.finboost.bank.statement.parser.util.logging.LoggingPropertiesUtil;
import org.springframework.stereotype.Service;
import lombok.extern.slf4j.Slf4j;
import java.util.List;

@Service
@Slf4j
public class BankTransactionTableIdentifier {

    /**
     * Processes document extraction result to identify bank transaction tables
     * and sets isBankTransactions flag accordingly
     */
    public void identifyBankTransactionTables(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) {
            log.warn("Document extraction result or pages are null");
            return;
        }

        for (Page page : result.getPages().values()) {
            if (page.getTables() != null) {
                for (Table table : page.getTables().values()) {
                    if(!table.isBankTransactions()){
                        BankTransactionTableIdentifier.processSingleTable(table);
                    }
                }
            }
        }

//        result.getPages().values().forEach(page -> {
//            if (page.getTables() != null) {
//                page.getTables().values().forEach(BankTransactionTableIdentifier::processSingleTable);
//            }
//        });
    }

    /**
     * Processes a single table to identify if it's a bank transaction table
     * and updates the isBankTransactions flag
     */
    public static void processSingleTable(Table table) {
        if (table == null) {
            return;
        }

        try {
            if(!table.isBankTransactions()) {
                boolean isValidBankTable = validateBankTransactionTable(table);
                table.setBankTransactions(isValidBankTable);
            }

//            if (isValidBankTable) {
//                log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog("", "Valid bank transaction table identified")));
//            } else {
//                log.debug(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog("", "Table does not meet bank transaction criteria")));
//            }
        } catch (Exception e) {
            log.error(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(RequestStatus.FAILED.name(), "Error processing table for bank transaction identification", ExceptionDetails.exceptionDetails(e))));
            table.setBankTransactions(false);
        }
    }

    /**
     * Validates if a table meets all criteria for being a bank transaction table
     */
    public static boolean validateBankTransactionTable(Table table) {
        // Check for null or empty column types
        List<ColumnTransactionType> columnTypes = table.getTxnColType();
        if (columnTypes == null || columnTypes.isEmpty()) {
            log.debug("Table has no transaction column types");
            return false;
        }

        // Check minimum column requirement
        if (columnTypes.size() <= 2) {
            log.debug("Table has insufficient columns: {}", columnTypes.size());
            return false;
        }

        // Check for required column types
        return hasRequiredColumns(columnTypes);
    }

    /**
     * Checks if the table has all required column types for a bank transaction table
     */
    public static boolean hasRequiredColumns(List<ColumnTransactionType> columnTypes) {
        // Check for Transaction Date
        boolean hasTransactionDate = columnTypes.contains(ColumnTransactionType.TransactionDate);
        if (!hasTransactionDate) {
            log.debug("Missing TransactionDate column");
            return false;
        }

        // Check for Balance
        boolean hasBalance = columnTypes.contains(ColumnTransactionType.Balance);
        if (!hasBalance) {
            log.debug("Missing Balance column");
            return false;
        }

        // Check for either Credit/Debit combination or AmountType
        boolean hasCreditDebit = columnTypes.contains(ColumnTransactionType.Credit) ||
                columnTypes.contains(ColumnTransactionType.Debit);
        boolean hasAmountType = columnTypes.contains(ColumnTransactionType.AmountType);

        if (!hasCreditDebit && !hasAmountType) {
            log.debug("Missing required amount columns (Credit/Debit or AmountType)");
            return false;
        }

        // All criteria met
        return true;
    }
}
package com.finboost.bank.statement.parser.service.document.extraction.post.processor;

import com.finboost.bank.statement.parser.representation.document.extraction.ColumnDataType;
import com.finboost.bank.statement.parser.representation.document.extraction.ColumnTransactionType;
import com.finboost.bank.statement.parser.representation.document.extraction.PreProcessVerificationResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;

import java.util.List;

public class BankTransactionTableUtil {



    public static boolean isValidBankTransactionTable(Table table, PreProcessVerificationResult preProcessVerificationResult) {
        if(table == null || table.getColType() == null || table.getColType().isEmpty()) {
            return false;
        }

        if(preProcessVerificationResult == null || preProcessVerificationResult.getValidColumnTransactionTypes() == null || preProcessVerificationResult.getValidColumnTransactionTypes().isEmpty()) {
            return false;
        }

        List<ColumnTransactionType> validColumnTransactionTypes = preProcessVerificationResult.getValidColumnTransactionTypes();
        List<ColumnDataType> columnDataTypes = table.getColType();
        // Check for transactionDate
        boolean isTransactionDateMatched = false;
        boolean containsValueDate = false;
        boolean isValueDateMatched = false;
        boolean isBalanceMatched = false;
        boolean isAmountMatched = false;
        boolean isAmountTypeMatched = false;
        int matchedCount = 0;
        for(int i = 0; i < validColumnTransactionTypes.size(); i++) {
            ColumnTransactionType columnTransactionType = validColumnTransactionTypes.get(i);

            if(columnTransactionType == ColumnTransactionType.TransactionDate && columnDataTypes.get(i) == ColumnDataType.Date){
                isTransactionDateMatched = true;
                matchedCount++;
            }

            if(columnTransactionType == ColumnTransactionType.ValueDate){
                containsValueDate = true;
                if(columnDataTypes.get(i) == ColumnDataType.Date){
                    isValueDateMatched = true;
                }
            }

            if(columnTransactionType == ColumnTransactionType.Balance && columnDataTypes.get(i) == ColumnDataType.Amount){
                isBalanceMatched = true;
                matchedCount++;
            }

            if((columnTransactionType == ColumnTransactionType.Credit ||
                    columnTransactionType == ColumnTransactionType.Debit ||
                    columnTransactionType == ColumnTransactionType.Amount)  && columnDataTypes.get(i) == ColumnDataType.Amount){
                isTransactionDateMatched = true;
                matchedCount++;
            }

            if(columnTransactionType == ColumnTransactionType.AmountType && columnDataTypes.get(i) == ColumnDataType.CR_DR){
                isAmountTypeMatched = true;
                matchedCount++;
            }

        }

        return (isValueDateMatched && matchedCount >= 3) || (!isValueDateMatched && matchedCount >= 2);
    }
}

