package com.finboost.bank.statement.parser.service.document.extraction.nativetable.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A horizontal or vertical ruling (table border) found in the content stream of a PDF page.
 * All coordinates are in inches with the origin at the top-left corner of the page, which is
 * the same coordinate space used by {@link com.finboost.bank.statement.parser.representation.document.extraction.Word}.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeRuling {

    private float x1;
    private float y1;
    private float x2;
    private float y2;
    private boolean horizontal;

    public static NativeRuling horizontal(float y, float xStart, float xEnd) {
        return new NativeRuling(Math.min(xStart, xEnd), y, Math.max(xStart, xEnd), y, true);
    }

    public static NativeRuling vertical(float x, float yStart, float yEnd) {
        return new NativeRuling(x, Math.min(yStart, yEnd), x, Math.max(yStart, yEnd), false);
    }

    public float length() {
        return horizontal ? Math.abs(x2 - x1) : Math.abs(y2 - y1);
    }

    /** Position of the ruling on the axis it is constant on. */
    public float position() {
        return horizontal ? (y1 + y2) / 2f : (x1 + x2) / 2f;
    }

    public float start() {
        return horizontal ? Math.min(x1, x2) : Math.min(y1, y2);
    }

    public float end() {
        return horizontal ? Math.max(x1, x2) : Math.max(y1, y2);
    }

    public boolean overlaps(NativeRuling other, float tolerance) {
        return start() - tolerance <= other.end() && other.start() - tolerance <= end();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A rectangle (drawn box or shaded band) found in the content stream of a PDF page.
 * All coordinates are in inches with the origin at the top-left corner of the page.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeBox {

    private float left;
    private float top;
    private float right;
    private float bottom;
    /** {@code true} when the rectangle was painted (shaded band), {@code false} when only stroked. */
    private boolean filled;

    public float width() {
        return right - left;
    }

    public float height() {
        return bottom - top;
    }

    public float area() {
        return Math.max(0f, width()) * Math.max(0f, height());
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    public boolean containsVertically(float y) {
        return y >= top && y <= bottom;
    }

    public boolean verticallyOverlaps(NativeBox other, float tolerance) {
        return top - tolerance <= other.bottom && other.top - tolerance <= bottom;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.model;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * A single visual text line of a page: the words that share the same baseline band.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeTextLine {

    private List<Word> words = new ArrayList<>();
    private float top;
    private float bottom;

    public void add(Word word) {
        if (words.isEmpty()) {
            top = word.getY1();
            bottom = word.getY3();
        } else {
            top = Math.min(top, word.getY1());
            bottom = Math.max(bottom, word.getY3());
        }
        words.add(word);
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    public float height() {
        return bottom - top;
    }

    public float minX() {
        return (float) words.stream().mapToDouble(Word::getX1).min().orElse(0d);
    }

    public float maxX() {
        return (float) words.stream().mapToDouble(Word::getX3).max().orElse(0d);
    }

    public List<Word> orderedWords() {
        return words.stream()
                .sorted(Comparator.comparing(Word::getX1))
                .collect(Collectors.toList());
    }

    public String text() {
        return orderedWords().stream()
                .map(Word::getContent)
                .filter(content -> content != null && !content.isBlank())
                .collect(Collectors.joining(" "));
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.model;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;

import java.util.ArrayList;
import java.util.List;

/**
 * Everything the native extraction knows about a single PDF page: the text (as words and text
 * lines) and the vector guides (rulings and boxes) that can be used to recover the table grid.
 * All coordinates are in inches with the origin at the top-left corner of the page.
 */
@Data
public class NativePageContent {

    private int pageNumber;
    private float width;
    private float height;
    private List<Word> words = new ArrayList<>();
    private List<NativeTextLine> textLines = new ArrayList<>();
    private List<NativeRuling> horizontalRulings = new ArrayList<>();
    private List<NativeRuling> verticalRulings = new ArrayList<>();
    private List<NativeBox> boxes = new ArrayList<>();
    private String text = "";

    public boolean hasText() {
        return !words.isEmpty();
    }

    public boolean hasVectorGuides() {
        return !horizontalRulings.isEmpty() || !verticalRulings.isEmpty() || !boxes.isEmpty();
    }

    /** Median height of the text lines of the page, used to derive geometric tolerances. */
    public float medianLineHeight() {
        if (textLines.isEmpty()) {
            return 0.12f;
        }
        List<Float> heights = new ArrayList<>();
        for (NativeTextLine line : textLines) {
            heights.add(line.height());
        }
        heights.sort(Float::compareTo);
        float median = heights.get(heights.size() / 2);
        return median <= 0f ? 0.12f : median;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeBox;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;

import java.awt.geom.Point2D;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Walks the content stream of a single PDF page and collects the vector guides that banks use
 * to draw their transaction tables: axis aligned rulings (either stroked paths or hair thin
 * filled rectangles) and rectangles/shaded bands.
 * <p>
 * The engine works completely offline - no remote ML service is involved.
 * </p>
 * Coordinates handed out by PDFBox are in PDF user space (origin bottom-left, unit = point).
 * They are converted to the coordinate space used by the rest of the extraction pipeline:
 * inches, origin at the top-left corner of the crop box.
 */
@Slf4j
public class NativePageGeometryEngine extends PDFGraphicsStreamEngine {

    private static final float POINTS_PER_INCH = 72.0f;

    /** Maximum thickness (inches) for a rectangle to be treated as a ruling instead of a box. */
    private static final float MAX_RULING_THICKNESS = 0.035f;
    /** Minimum length (inches) of a ruling that is kept. */
    private static final float MIN_HORIZONTAL_RULING_LENGTH = 0.15f;
    private static final float MIN_VERTICAL_RULING_LENGTH = 0.08f;
    /** Minimum size (inches) of a rectangle to be treated as a row/cell box. */
    private static final float MIN_BOX_WIDTH = 0.25f;
    private static final float MIN_BOX_HEIGHT = 0.04f;

    private final List<NativeRuling> horizontalRulings = new LinkedList<>();
    private final List<NativeRuling> verticalRulings = new LinkedList<>();
    private final List<NativeBox> boxes = new LinkedList<>();

    private final List<Point2D> currentPath = new ArrayList<>();
    private final List<float[]> pendingRectangles = new ArrayList<>();

    private final float offsetX;
    private final float offsetTopY;
    private final float pageWidthInches;
    private final float pageHeightInches;

    public NativePageGeometryEngine(PDPage page) {
        super(page);
        PDRectangle cropBox = page.getCropBox();
        this.offsetX = cropBox.getLowerLeftX();
        this.offsetTopY = cropBox.getUpperRightY();
        this.pageWidthInches = cropBox.getWidth() / POINTS_PER_INCH;
        this.pageHeightInches = cropBox.getHeight() / POINTS_PER_INCH;
    }

    /**
     * Processes the page. Failures of a single page never abort the extraction, the caller simply
     * ends up with fewer (or no) vector guides and the layout strategies decide what to do.
     */
    public void extract() {
        try {
            processPage(getPage());
        } catch (Exception e) {
            log.debug("Unable to read vector guides of page: {}", e.getMessage());
        }
    }

    public List<NativeRuling> getHorizontalRulings() {
        return horizontalRulings;
    }

    public List<NativeRuling> getVerticalRulings() {
        return verticalRulings;
    }

    public List<NativeBox> getBoxes() {
        return boxes;
    }

    public float getPageWidthInches() {
        return pageWidthInches;
    }

    public float getPageHeightInches() {
        return pageHeightInches;
    }

    private float toInchesX(double x) {
        return (float) ((x - offsetX) / POINTS_PER_INCH);
    }

    private float toInchesY(double y) {
        return (float) ((offsetTopY - y) / POINTS_PER_INCH);
    }

    @Override
    public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
        float left = toInchesX(Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX())));
        float right = toInchesX(Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX())));
        // y is flipped by the conversion, therefore the maximum PDF y becomes the minimum (top) value
        float top = toInchesY(Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY())));
        float bottom = toInchesY(Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY())));
        pendingRectangles.add(new float[]{left, top, right, bottom});
    }

    @Override
    public void drawImage(PDImage pdImage) {
        // images carry no table structure for the native path
    }

    @Override
    public void clip(int windingRule) {
        // clipping does not paint anything
    }

    @Override
    public void moveTo(float x, float y) {
        currentPath.add(new Point2D.Float(x, y));
    }

    @Override
    public void lineTo(float x, float y) {
        currentPath.add(new Point2D.Float(x, y));
    }

    @Override
    public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
        // curves are never table borders, only remember the end point to keep the path continuous
        currentPath.add(new Point2D.Float(x3, y3));
    }

    @Override
    public Point2D getCurrentPoint() {
        return currentPath.isEmpty() ? new Point2D.Float(0, 0) : currentPath.get(currentPath.size() - 1);
    }

    @Override
    public void closePath() {
        if (currentPath.size() > 2) {
            currentPath.add(currentPath.get(0));
        }
    }

    @Override
    public void endPath() {
        currentPath.clear();
        pendingRectangles.clear();
    }

    @Override
    public void strokePath() {
        flushPath(false);
    }

    @Override
    public void fillPath(int windingRule) {
        flushPath(true);
    }

    @Override
    public void fillAndStrokePath(int windingRule) {
        flushPath(true);
    }

    @Override
    public void shadingFill(COSName shadingName) {
        // gradients are decoration only
    }

    private void flushPath(boolean filled) {
        for (int i = 0; i + 1 < currentPath.size(); i++) {
            addSegment(currentPath.get(i), currentPath.get(i + 1));
        }
        for (float[] rectangle : pendingRectangles) {
            addRectangle(rectangle[0], rectangle[1], rectangle[2], rectangle[3], filled);
        }
        currentPath.clear();
        pendingRectangles.clear();
    }

    private void addSegment(Point2D from, Point2D to) {
        float x1 = toInchesX(from.getX());
        float y1 = toInchesY(from.getY());
        float x2 = toInchesX(to.getX());
        float y2 = toInchesY(to.getY());

        float dx = Math.abs(x2 - x1);
        float dy = Math.abs(y2 - y1);

        if (dy <= MAX_RULING_THICKNESS && dx >= MIN_HORIZONTAL_RULING_LENGTH) {
            horizontalRulings.add(NativeRuling.horizontal((y1 + y2) / 2f, x1, x2));
        } else if (dx <= MAX_RULING_THICKNESS && dy >= MIN_VERTICAL_RULING_LENGTH) {
            verticalRulings.add(NativeRuling.vertical((x1 + x2) / 2f, y1, y2));
        }
    }

    private void addRectangle(float left, float top, float right, float bottom, boolean filled) {
        float width = right - left;
        float height = bottom - top;

        if (width <= 0f || height < 0f) {
            return;
        }

        // a page sized rectangle is a background, not a table guide
        boolean pageBackground = width >= pageWidthInches * 0.95f && height >= pageHeightInches * 0.85f;
        if (pageBackground) {
            return;
        }

        if (height <= MAX_RULING_THICKNESS && width >= MIN_HORIZONTAL_RULING_LENGTH) {
            horizontalRulings.add(NativeRuling.horizontal((top + bottom) / 2f, left, right));
            return;
        }
        if (width <= MAX_RULING_THICKNESS && height >= MIN_VERTICAL_RULING_LENGTH) {
            verticalRulings.add(NativeRuling.vertical((left + right) / 2f, top, bottom));
            return;
        }
        if (width >= MIN_BOX_WIDTH && height >= MIN_BOX_HEIGHT) {
            boxes.add(new NativeBox(left, top, right, bottom, filled));
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Small geometry helpers shared by the native table layout strategies.
 * Every value is expressed in inches.
 */
public final class NativeGeometryUtil {

    private NativeGeometryUtil() {
    }

    /**
     * Merges rulings that describe the same border. PDF producers frequently emit a single visual
     * line as dozens of tiny segments, or draw the very same line twice.
     *
     * @param rulings           rulings of one orientation
     * @param positionTolerance how far apart two rulings may be on their constant axis
     * @param gapTolerance      how large the gap between two collinear rulings may be to still merge them
     * @return merged rulings sorted by position
     */
    public static List<NativeRuling> mergeRulings(List<NativeRuling> rulings, float positionTolerance, float gapTolerance) {
        List<NativeRuling> merged = new LinkedList<>();
        if (rulings == null || rulings.isEmpty()) {
            return merged;
        }

        List<NativeRuling> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparing(NativeRuling::position).thenComparing(NativeRuling::start));

        for (NativeRuling ruling : sorted) {
            NativeRuling candidate = null;
            for (int i = merged.size() - 1; i >= 0; i--) {
                NativeRuling existing = merged.get(i);
                if (Math.abs(existing.position() - ruling.position()) > positionTolerance) {
                    break;
                }
                if (existing.overlaps(ruling, gapTolerance)) {
                    candidate = existing;
                    break;
                }
            }
            if (candidate == null) {
                merged.add(copy(ruling));
            } else {
                extend(candidate, ruling);
            }
        }

        merged.sort(Comparator.comparing(NativeRuling::position));
        return merged;
    }

    private static NativeRuling copy(NativeRuling ruling) {
        return new NativeRuling(ruling.getX1(), ruling.getY1(), ruling.getX2(), ruling.getY2(), ruling.isHorizontal());
    }

    private static void extend(NativeRuling target, NativeRuling addition) {
        float start = Math.min(target.start(), addition.start());
        float end = Math.max(target.end(), addition.end());
        if (target.isHorizontal()) {
            target.setX1(start);
            target.setX2(end);
        } else {
            target.setY1(start);
            target.setY2(end);
        }
    }

    /**
     * Groups nearby values and returns the mean of every group. Used to turn a cloud of ruling
     * positions or word edges into a small set of column/row separators.
     */
    public static List<Float> clusterValues(List<Float> values, float tolerance) {
        List<Float> clusters = new LinkedList<>();
        if (values == null || values.isEmpty()) {
            return clusters;
        }
        List<Float> sorted = new ArrayList<>(values);
        sorted.sort(Float::compareTo);

        float sum = sorted.get(0);
        int count = 1;
        float last = sorted.get(0);
        for (int i = 1; i < sorted.size(); i++) {
            float value = sorted.get(i);
            if (value - last <= tolerance) {
                sum += value;
                count++;
            } else {
                clusters.add(sum / count);
                sum = value;
                count = 1;
            }
            last = value;
        }
        clusters.add(sum / count);
        return clusters;
    }

    /** Returns the median of the given values, or {@code fallback} for an empty input. */
    public static float median(List<Float> values, float fallback) {
        if (values == null || values.isEmpty()) {
            return fallback;
        }
        List<Float> sorted = new ArrayList<>(values);
        sorted.sort(Float::compareTo);
        return sorted.get(sorted.size() / 2);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.EPdfCharacterInfo;
import com.finboost.bank.statement.parser.representation.document.extraction.EPdfPageCharacters;
import com.finboost.bank.statement.parser.representation.document.extraction.EPdfWord;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Turns the characters of an electronic (text based) PDF page into
 * {@link Word}s and visual text lines.
 * <p>
 * The produced words use exactly the same coordinate convention as the words returned by the
 * remote ML extraction (inches, origin top-left, polygon ordered top-left, top-right,
 * bottom-right, bottom-left) so that every downstream post processor keeps working unchanged.
 * </p>
 */
@Component
public class NativeWordAssembler {

    /** Minimum horizontal gap (inches) that always separates two words. */
    private static final float MIN_WORD_GAP = 0.018f;
    /** Fraction of the median character width that separates two words. */
    private static final float WORD_GAP_RATIO = 0.28f;
    /** Minimum vertical distance (inches) between two text lines. */
    private static final float MIN_LINE_GAP = 0.03f;
    /** Fraction of the character height used to decide whether two characters share a line. */
    private static final float LINE_GAP_RATIO = 0.4f;

    /**
     * Assembles the words of a page.
     *
     * @param pageCharacters characters of the page as extracted by the character extraction service
     * @param pageNumber     one based page number
     * @param firstWordIndex running word index of the document (mirrors the ML mapper behaviour)
     * @return the text lines of the page, each holding its words
     */
    public List<NativeTextLine> assemble(EPdfPageCharacters pageCharacters, int pageNumber, int firstWordIndex) {
        List<NativeTextLine> lines = new LinkedList<>();
        if (pageCharacters == null || pageCharacters.getCharacters() == null || pageCharacters.getCharacters().isEmpty()) {
            return lines;
        }

        List<EPdfCharacterInfo> characters = new ArrayList<>();
        for (EPdfCharacterInfo character : pageCharacters.getCharacters()) {
            if (isPrintable(character)) {
                characters.add(character);
            }
        }
        if (characters.isEmpty()) {
            return lines;
        }

        characters.sort(Comparator.comparingDouble(NativeWordAssembler::centerY)
                .thenComparingDouble(EPdfCharacterInfo::getX));

        int wordIndex = firstWordIndex;
        List<List<EPdfCharacterInfo>> characterLines = groupIntoLines(characters);
        for (List<EPdfCharacterInfo> characterLine : characterLines) {
            NativeTextLine line = new NativeTextLine();
            for (List<EPdfCharacterInfo> wordCharacters : splitIntoWords(characterLine)) {
                Word word = toWord(wordCharacters, pageNumber, wordIndex++);
                if (word != null) {
                    line.add(word);
                }
            }
            if (!line.getWords().isEmpty()) {
                lines.add(line);
            }
        }

        lines.sort(Comparator.comparing(NativeTextLine::centerY));
        return lines;
    }

    /** Number of words produced for the given text lines. */
    public int countWords(List<NativeTextLine> lines) {
        int count = 0;
        for (NativeTextLine line : lines) {
            count += line.getWords().size();
        }
        return count;
    }

    private boolean isPrintable(EPdfCharacterInfo character) {
        if (character == null || character.getCharacter() == null || character.getCharacter().isEmpty()) {
            return false;
        }
        String value = character.getCharacter();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (!Character.isWhitespace(c) && !Character.isISOControl(c)) {
                return true;
            }
        }
        return false;
    }

    private List<List<EPdfCharacterInfo>> groupIntoLines(List<EPdfCharacterInfo> characters) {
        List<List<EPdfCharacterInfo>> lines = new LinkedList<>();
        List<EPdfCharacterInfo> current = new ArrayList<>();
        float currentCenter = centerY(characters.get(0));

        for (EPdfCharacterInfo character : characters) {
            float center = centerY(character);
            float tolerance = Math.max(MIN_LINE_GAP, character.getHeight() * LINE_GAP_RATIO);
            if (current.isEmpty() || Math.abs(center - currentCenter) <= tolerance) {
                current.add(character);
                // keep the reference center on the first character of the line, the vertical
                // jitter inside one line is far smaller than the distance to the next line
                if (current.size() == 1) {
                    currentCenter = center;
                }
            } else {
                lines.add(current);
                current = new ArrayList<>();
                current.add(character);
                currentCenter = center;
            }
        }
        if (!current.isEmpty()) {
            lines.add(current);
        }
        return lines;
    }

    private List<List<EPdfCharacterInfo>> splitIntoWords(List<EPdfCharacterInfo> characterLine) {
        List<List<EPdfCharacterInfo>> words = new LinkedList<>();
        List<EPdfCharacterInfo> sorted = new ArrayList<>(characterLine);
        sorted.sort(Comparator.comparingDouble(EPdfCharacterInfo::getX));

        List<Float> widths = new ArrayList<>();
        for (EPdfCharacterInfo character : sorted) {
            if (character.getWidth() > 0f) {
                widths.add(character.getWidth());
            }
        }
        float gapThreshold = Math.max(MIN_WORD_GAP, NativeGeometryUtil.median(widths, 0.06f) * WORD_GAP_RATIO);

        List<EPdfCharacterInfo> current = new ArrayList<>();
        float previousRight = Float.NaN;
        for (EPdfCharacterInfo character : sorted) {
            boolean newWord = !current.isEmpty() && (character.getX() - previousRight) > gapThreshold;
            if (newWord) {
                words.add(current);
                current = new ArrayList<>();
            }
            current.add(character);
            float right = character.getX() + Math.max(0f, character.getWidth());
            previousRight = Float.isNaN(previousRight) || right > previousRight || newWord ? right : previousRight;
        }
        if (!current.isEmpty()) {
            words.add(current);
        }
        return words;
    }

    private Word toWord(List<EPdfCharacterInfo> characters, int pageNumber, int wordIndex) {
        if (characters.isEmpty()) {
            return null;
        }

        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        float top = Float.MAX_VALUE;
        float bottom = -Float.MAX_VALUE;
        StringBuilder content = new StringBuilder();

        for (EPdfCharacterInfo character : characters) {
            left = Math.min(left, character.getX());
            right = Math.max(right, character.getX() + Math.max(0f, character.getWidth()));
            top = Math.min(top, character.getY() - Math.max(0f, character.getHeight()));
            bottom = Math.max(bottom, character.getY());
            content.append(character.getCharacter());
            character.setAssigned(true);
        }

        String text = content.toString().trim();
        if (text.isEmpty()) {
            return null;
        }

        Word word = new Word(text, left, top, right, top, right, bottom, left, bottom,
                pageNumber, right - left, bottom - top, pageNumber, wordIndex);

        EPdfWord ePdfWord = new EPdfWord();
        ePdfWord.setCharacters(new ArrayList<>(characters));
        // the characters are already ordered left to right, keep that order for the content
        ePdfWord.setContent(text);
        ePdfWord.setX1(left);
        ePdfWord.setY1(top);
        ePdfWord.setX2(right);
        ePdfWord.setY2(top);
        ePdfWord.setX3(right);
        ePdfWord.setY3(bottom);
        ePdfWord.setX4(left);
        ePdfWord.setY4(bottom);
        word.setEPdfWord(ePdfWord);

        return word;
    }

    private static float centerY(EPdfCharacterInfo character) {
        return character.getY() - (Math.max(0f, character.getHeight()) / 2f);
    }
}

