package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.EPdfPageCharacters;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.EPdfCharacterExtractionService;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Reads a statement PDF completely offline and produces, for every page, the text (words and
 * text lines) together with the vector guides (rulings and boxes) of the page.
 */
@Component
@Slf4j
public class NativePageContentExtractor {

    @Setter(onMethod_ = @Autowired)
    private EPdfCharacterExtractionService ePdfCharacterExtractionService;

    @Setter(onMethod_ = @Autowired)
    private NativeWordAssembler nativeWordAssembler;

    /**
     * @param statementFile the (already decrypted) statement PDF
     * @return the native content of every page, an empty list when the document carries no text
     * @throws IOException when the file cannot be read at all
     */
    public List<NativePageContent> extract(File statementFile) throws IOException {
        List<NativePageContent> pages = new ArrayList<>();

        Map<Integer, EPdfPageCharacters> charactersByPage = new HashMap<>();
        for (EPdfPageCharacters pageCharacters : ePdfCharacterExtractionService.extractCharactersFromPDF(statementFile)) {
            charactersByPage.put(pageCharacters.getPageNumber(), pageCharacters);
        }

        try (PDDocument document = Loader.loadPDF(statementFile)) {
            int wordIndex = 1;
            for (int pageIndex = 0; pageIndex < document.getNumberOfPages(); pageIndex++) {
                int pageNumber = pageIndex + 1;
                PDPage pdPage = document.getPage(pageIndex);

                NativePageGeometryEngine engine = new NativePageGeometryEngine(pdPage);
                engine.extract();

                NativePageContent content = new NativePageContent();
                content.setPageNumber(pageNumber);
                content.setWidth(engine.getPageWidthInches());
                content.setHeight(engine.getPageHeightInches());

                List<NativeTextLine> textLines =
                        nativeWordAssembler.assemble(charactersByPage.get(pageNumber), pageNumber, wordIndex);
                wordIndex += nativeWordAssembler.countWords(textLines);

                content.setTextLines(textLines);
                content.setWords(textLines.stream()
                        .flatMap(line -> line.getWords().stream())
                        .collect(Collectors.toList()));
                content.setText(textLines.stream()
                        .map(NativeTextLine::text)
                        .collect(Collectors.joining("\n")));

                float lineHeight = content.medianLineHeight();
                content.setHorizontalRulings(NativeGeometryUtil.mergeRulings(
                        engine.getHorizontalRulings(), lineHeight * 0.25f, lineHeight));
                content.setVerticalRulings(NativeGeometryUtil.mergeRulings(
                        engine.getVerticalRulings(), lineHeight * 0.25f, lineHeight));
                content.setBoxes(engine.getBoxes());

                pages.add(content);
            }
        }

        return pages;
    }

    /** Total number of words of all pages. */
    public int totalWords(List<NativePageContent> pages) {
        int total = 0;
        for (NativePageContent page : pages) {
            List<Word> words = page.getWords();
            total += words == null ? 0 : words.size();
        }
        return total;
    }
}

