package com.finboost.bank.statement.parser.service.document.extraction.post.processor;

import com.finboost.bank.statement.parser.representation.document.extraction.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Slf4j
@Service
public class ColumnTypeIdentifier {

    private static final Pattern DATE_REGEX = Pattern.compile("(([0-9]{4}[-][0-1][0-9][-][0-3][0-9])|((^|\\s)?[0-3]?[0-9][-|/| |\\.][0-1]?[0-9][-|/| |\\.]([0-9]{2}([\\s]|$)|[0-9]{4}([\\s]+|$))?(?!([0-9]{3}([\\s]+|$))))|((^|\\s)?[0-1]?[0-9][-|/| ][0-3]?[0-9][-|/| ])([0-9]{2}([^0-9]|[\\s]+|$)|[0-9]{4}([^0-9]|[\\s]+|$))|((^|\\s)?[0-3]?[0-9][-|/| ][A-z]{3}[-|/| ][0-9]{2,4})|((^|\\s)?[0-3]?[0-9][-|/| ](jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec))|((^|\\s)?[0-3][0-9](jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)(20)?[0-9]{2}$)|((^|\\s)?[0-3][0-9][,][0-1][0-9][,](20)[0-9]{2}$))|(?i)(?:January|February|March|April|May|June|July|August|September|October|November|December)\\s*\\d{1,2}\\s*\\d{4}");
    private static final Pattern DATE_FLAG_REGEX = Pattern.compile("(([0-3]?[0-9])([-|\\/])((jan)|(feb)|(mar)|(apr)|(may)|(jun)|(jul)|(aug)|(sep(t))|(oct)|(nov)|(dec))([-|\\/])[0-9]{2,4})|(((jan)|(feb)|(mar)|(apr)|(may)|(jun)|(jul)|(aug)|(sep(t))|(oct)|(nov)|(dec))([0-3]?[0-9])[0-9]{2,4})");
    private static final Pattern TIME_REGEX_TO_REPLACE= Pattern.compile("(?:(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9])");
    private static final Pattern CR_DR_TYPE_REGEX = Pattern.compile("(Cr|Dr|CR|DR|dr|cr)");
    private static final Pattern CR_DR_TYPE_REGEX_large2 = Pattern.compile("(credit|debit)");

    public DocumentExtractionResult identifyColumnTypes(DocumentExtractionResult document) {
        //Map<Integer, List<ColumnDataType>> result = new HashMap<>();

        if (document != null && document.getPages() != null) {
            // Iterate through each page
            for (Page page : document.getPages().values()) {
                if (page.getTables() != null) {
                    // Process each table in the page
                    for (Map.Entry<Integer, Table> tableEntry : page.getTables().entrySet()) {
                        Table table = tableEntry.getValue();

                        // Check if it's a bank transaction table
                        if(true){ //if (table.isBankTransactions()) {
                            // Get table index and identify column types
                            Integer tableIndex = tableEntry.getKey();
                            List<ColumnDataType> columnTypes = identifyColumnTypes(table);

                            // Convert the column types to list and store in result
                            //List<ColumnDataType> columnTypeList = new ArrayList<>(columnTypes.values());
                            //result.put(tableIndex, columnTypes);

                            // Update the table's column types
                            table.setColType(columnTypes);

//                            log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog("" , "Processed bank transaction table" + tableIndex + "on page" + page.getPageNumber() + ":" + columnTypes.size() + " columns identified")));
                        }
                    }
                }
            }
        }

        return document;


    }

    public List<ColumnDataType> identifyColumnTypes(Table table) {
        List<ColumnDataType> columnDataTypes = new LinkedList<>();

        // Process each column in the table
//        for (Map.Entry<Integer, Map<Integer, TableCell>> rowEntry : table.getCells().entrySet()) {
//            for (Map.Entry<Integer, TableCell> cellEntry : rowEntry.getValue().entrySet()) {
//                int columnIndex = cellEntry.getKey();
//                if (!columnTypeMap.containsKey(columnIndex)) {
//                    ColumnDataType type = identifyColumnType(table, columnIndex);
//                    columnTypeMap.put(columnIndex, type);
//                }
//            }
//        }
        for(int i = 0 ; i< table.getTotalColumns() ; i++){
            ColumnDataType type = identifyColumnType(table, i);
            columnDataTypes.add(i, type);
        }

        return columnDataTypes;
    }

    private ColumnDataType identifyColumnType(Table table, int columnIndex) {
        List<ColumnDataType> columnTypes = new ArrayList<>();
        int emptyCount = 0;

        // Analyze each row for the given column
        for (Map.Entry<Integer, Map<Integer, TableCell>> rowEntry : table.getCells().entrySet()) {
            TableCell cell = rowEntry.getValue().get(columnIndex);
            if (cell == null || cell.getWords() == null || cell.getWords().isEmpty()) {
                emptyCount++;
                continue;
            }

//            String content = cell.getWords().stream()
//                    .map(Word::getContent)
//                    .collect(Collectors.joining(" "));
            String content = cell.getContent();

            if (content == null || content.trim().isEmpty()) {
                emptyCount++;
            } else if (isDateType(content)) {
                columnTypes.add(ColumnDataType.Date);
            } else if (isAmountType(content)) {
                columnTypes.add(ColumnDataType.Amount);
            } else if (isCrDrType(content)) {
                columnTypes.add(ColumnDataType.CR_DR);
            } else if (content.trim().length() > 2) { //if content has more than 2 char then it is Text
                columnTypes.add(ColumnDataType.Text);
            } else{
                emptyCount++;
            }
        }

        // Return the most frequent type or Text if no clear pattern
        return getMostFrequentType(columnTypes);
    }

    public  boolean isDateType(String content) {
        content = content.replaceAll("\\s+", "").toLowerCase();
        content = content.replaceAll(TIME_REGEX_TO_REPLACE.pattern(), "");
        content = content.replaceAll(",", "");
        if (DATE_REGEX.matcher(content).find() &&
                content.replaceAll(DATE_REGEX.pattern(), "").length() < 5) {
                //content.replace("[^a-z]", "").length() < 5) {
            if (content.contains(".") && content.chars().filter(ch -> ch == '.').count() != 2) {
                return false;
            }
            return true;
        }
        return DATE_FLAG_REGEX.matcher(content).find() &&
                content.replaceAll(DATE_FLAG_REGEX.pattern(),"").length() < 5;
                //content.replaceAll("[^a-z]", "").length() < 5;
    }

    public boolean isAmountType(String content) {
        content = content.toLowerCase();
        content = content.replaceAll("(inr)|(₹)", "");

        // Check for amount with commas and decimals
        if (content.contains(",")) {
            String commaAmountPattern = "((^|[\\s])[+|-]?((([0-9])+,)+[0-9]{1,3}\\.[0-9]{0,2})[\\s]*((-|Cr|Dr|CR|DR|dr|cr|\\(Cr\\)|\\(Dr\\))|([a-zA-z]{1,2}))?([\\s]*|$))";
            String commaOnlyPattern = "((^|[\\s])[+|-]?(([0-9])+,)+[0-9]{1,3}[\\s]*((-|Cr|Dr|CR|DR|dr|cr|\\(Cr\\)|\\(Dr\\))|([a-zA-z]{1,2}))?([\\s]*|$))";

            return (Pattern.compile(commaAmountPattern).matcher(content).find() ||
                    Pattern.compile(commaOnlyPattern).matcher(content).find()) &&
                    content.replaceAll("[^a-z]", "").length() < 5;
        }

        // Check for decimal amounts
        if (content.contains(".")) {
            String decimalPattern = "((^|[\\s])[+|-]?([0-9]+\\.[0-9]{0,2})[\\s]*((-|Cr|Dr|CR|DR|dr|cr|\\(Cr\\)|\\(Dr\\))|([a-zA-z]{1,2}))?([\\s]*|$))";
            String decimalOnlyPattern = "((^|[\\s])[+|-]?(\\.[0-9]{1,2})[\\s]*((-|Cr|Dr|CR|DR|dr|cr|\\(Cr\\)|\\(Dr\\))|([a-zA-z]{1,2}))?([\\s]*|$))";

            return (Pattern.compile(decimalPattern).matcher(content).find() ||
                    Pattern.compile(decimalOnlyPattern).matcher(content).find()) &&
                    content.replaceAll("[^a-z]", "").length() < 5;
        }

        // Check for whole numbers
        String wholeNumberPattern = "((^|[\\s])[+|-]?([0-9]{1,})[\\s]*((-|Cr|Dr|CR|DR|dr|cr|\\(Cr\\)|\\(Dr\\))|([a-zA-z]{1,2}))?([\\s]*|$))";
        return Pattern.compile(wholeNumberPattern).matcher(content).find() &&
                content.replaceFirst(wholeNumberPattern, "").length() <= 2;
    }

    private boolean isCrDrType(String content) {
        content = content.toLowerCase();
        return (CR_DR_TYPE_REGEX.matcher(content).find() && content.length() <= 4)
                || (CR_DR_TYPE_REGEX_large2.matcher(content).find() && (content.length() >= 5 && content.length() <= 6));
    }

    private ColumnDataType getMostFrequentType(List<ColumnDataType> types) {
        if (types.isEmpty()) {
            return ColumnDataType.Text;
        }

        Map<ColumnDataType, Long> frequencyMap = types.stream()
                .collect(Collectors.groupingBy(type -> type, Collectors.counting()));

        // Find the maximum frequency count
        long maxFrequency = frequencyMap.values().stream()
                .mapToLong(Long::longValue)
                .max()
                .orElse(0L);

        // Get all types that have the maximum frequency
        List<ColumnDataType> maxFrequencyTypes = frequencyMap.entrySet().stream()
                .filter(entry -> entry.getValue() == maxFrequency)
                .map(Map.Entry::getKey)
                .toList();

        // If only one type has max frequency, return it
        if (maxFrequencyTypes.size() == 1) {
            return maxFrequencyTypes.get(0);
        }

        // If multiple types have max frequency, use priority order
        if (maxFrequencyTypes.contains(ColumnDataType.Date)) {
            return ColumnDataType.Date;
        } else if (maxFrequencyTypes.contains(ColumnDataType.Amount)) {
            return ColumnDataType.Amount;
        } else if (maxFrequencyTypes.contains(ColumnDataType.CR_DR)) {
            return ColumnDataType.CR_DR;
        } else {
            return ColumnDataType.Text;
        }
    }
}

