package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Derives the column boundaries of a native transaction table.
 * <p>
 * Three sources are supported, in decreasing order of reliability:
 * <ol>
 *     <li>column rulings drawn by the bank (bordered grids),</li>
 *     <li>the alignment of the header line combined with the body words,</li>
 *     <li>the vertical whitespace that is present in <em>every</em> row of the table body.</li>
 * </ol>
 * A boundary list always contains {@code columnCount + 1} ascending x values.
 */
@Component
public class NativeColumnDetector {

    /** Minimum width (inches) of a column. */
    private static final float MIN_COLUMN_WIDTH = 0.12f;
    /** Minimum whitespace (inches) between two columns. */
    private static final float MIN_COLUMN_GAP = 0.07f;
    /** Bin size (inches) of the horizontal occupancy profile. */
    private static final float PROFILE_BIN = 0.01f;
    /** Upper bound for the number of detected columns, larger values are never real statements. */
    private static final int MAX_COLUMNS = 14;

    /**
     * Column boundaries taken from the vertical rulings that cross the given vertical range.
     */
    public List<Float> fromRulings(List<NativeRuling> verticalRulings, float top, float bottom, float minCoverage) {
        List<Float> positions = new ArrayList<>();
        float height = bottom - top;
        for (NativeRuling ruling : verticalRulings) {
            float overlap = Math.min(bottom, ruling.end()) - Math.max(top, ruling.start());
            if (height <= 0f || overlap >= height * minCoverage) {
                positions.add(ruling.position());
            }
        }
        List<Float> boundaries = NativeGeometryUtil.clusterValues(positions, MIN_COLUMN_WIDTH);
        return sanitize(boundaries);
    }

    /**
     * Column boundaries derived from the header line. The words of the header line are grouped
     * into header cells, the boundary between two neighbouring header cells is placed in the
     * middle of the whitespace between them and afterwards moved so that no body word is cut
     * into two pieces.
     */
    public List<Float> fromHeaderLine(NativeTextLine headerLine, List<Word> bodyWords, float left, float right) {
        if (headerLine == null || headerLine.getWords().isEmpty()) {
            return new LinkedList<>();
        }

        List<Word> headerWords = headerLine.orderedWords();
        List<float[]> groups = new ArrayList<>();
        float groupLeft = headerWords.get(0).getX1();
        float groupRight = headerWords.get(0).getX3();
        for (int i = 1; i < headerWords.size(); i++) {
            Word word = headerWords.get(i);
            if (word.getX1() - groupRight > MIN_COLUMN_GAP) {
                groups.add(new float[]{groupLeft, groupRight});
                groupLeft = word.getX1();
            }
            groupRight = Math.max(groupRight, word.getX3());
        }
        groups.add(new float[]{groupLeft, groupRight});

        if (groups.size() < 3) {
            return new LinkedList<>();
        }

        List<Float> boundaries = new ArrayList<>();
        boundaries.add(Math.min(left, groups.get(0)[0]) - 0.02f);
        for (int i = 1; i < groups.size(); i++) {
            float gapStart = groups.get(i - 1)[1];
            float gapEnd = groups.get(i)[0];
            float boundary = (gapStart + gapEnd) / 2f;
            boundaries.add(adjustToWhitespace(boundary, gapStart, gapEnd, bodyWords));
        }
        boundaries.add(Math.max(right, groups.get(groups.size() - 1)[1]) + 0.02f);

        return sanitize(boundaries);
    }

    /**
     * Column boundaries derived from the vertical whitespace of the given words. A boundary is
     * only created where no word of any row has ink, which makes the result stable for tables
     * without any column ruling.
     */
    public List<Float> fromWhitespaceProfile(List<Word> words, float left, float right) {
        List<Float> boundaries = new LinkedList<>();
        if (words == null || words.isEmpty() || right - left <= MIN_COLUMN_WIDTH) {
            return boundaries;
        }

        int bins = (int) Math.ceil((right - left) / PROFILE_BIN) + 1;
        boolean[] occupied = new boolean[bins];
        for (Word word : words) {
            int from = binOf(word.getX1(), left, bins);
            int to = binOf(word.getX3(), left, bins);
            for (int i = from; i <= to; i++) {
                occupied[i] = true;
            }
        }

        int minGapBins = Math.max(1, Math.round(MIN_COLUMN_GAP / PROFILE_BIN));
        List<Float> result = new ArrayList<>();
        result.add(left - 0.02f);

        int gapStart = -1;
        for (int i = 0; i < bins; i++) {
            if (!occupied[i]) {
                if (gapStart < 0) {
                    gapStart = i;
                }
                continue;
            }
            if (gapStart >= 0) {
                int gapLength = i - gapStart;
                if (gapLength >= minGapBins && gapStart > 0) {
                    result.add(left + (gapStart + gapLength / 2f) * PROFILE_BIN);
                }
                gapStart = -1;
            }
        }
        result.add(right + 0.02f);

        return sanitize(result);
    }

    /**
     * Moves a boundary into the widest whitespace of the body words so that no word is split.
     */
    private float adjustToWhitespace(float boundary, float gapStart, float gapEnd, List<Word> bodyWords) {
        if (bodyWords == null || bodyWords.isEmpty()) {
            return boundary;
        }
        List<Word> crossing = new ArrayList<>();
        for (Word word : bodyWords) {
            if (word.getX1() < boundary && word.getX3() > boundary) {
                crossing.add(word);
            }
        }
        if (crossing.isEmpty()) {
            return boundary;
        }
        crossing.sort(Comparator.comparing(Word::getX1));
        // move the boundary to the left edge of the left most crossing word when that still keeps
        // it inside the header whitespace, otherwise to the right edge of the last crossing word
        float leftCandidate = crossing.get(0).getX1() - 0.01f;
        float rightCandidate = crossing.get(crossing.size() - 1).getX3() + 0.01f;
        if (leftCandidate > gapStart) {
            return leftCandidate;
        }
        if (rightCandidate < gapEnd) {
            return rightCandidate;
        }
        return boundary;
    }

    private int binOf(float value, float left, int bins) {
        int bin = Math.round((value - left) / PROFILE_BIN);
        if (bin < 0) {
            return 0;
        }
        return Math.min(bin, bins - 1);
    }

    /** Removes boundaries that are too close to each other and enforces the column limit. */
    private List<Float> sanitize(List<Float> boundaries) {
        List<Float> result = new LinkedList<>();
        if (boundaries == null || boundaries.isEmpty()) {
            return result;
        }
        List<Float> sorted = new ArrayList<>(boundaries);
        sorted.sort(Float::compareTo);
        result.add(sorted.get(0));
        for (int i = 1; i < sorted.size(); i++) {
            if (sorted.get(i) - result.get(result.size() - 1) >= MIN_COLUMN_WIDTH) {
                result.add(sorted.get(i));
            }
        }
        if (result.size() - 1 > MAX_COLUMNS) {
            return new LinkedList<>();
        }
        return result;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.BankTransactionTableHeaderIdentifier;
import org.springframework.stereotype.Component;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Locates the header line of a transaction table inside the text lines of a page.
 * The very same header keyword patterns that the existing post processors use are reused, so a
 * line that is accepted here is also understood by the downstream column type identification.
 */
@Component
public class NativeHeaderLocator {

    /** Keyword groups that a transaction table header has to cover. */
    private static final List<String> DATE_KEYS = Arrays.asList("date", "value_date");
    private static final List<String> DESCRIPTION_KEYS = Arrays.asList("description");
    private static final List<String> AMOUNT_KEYS = Arrays.asList("credit", "debit", "amount", "amount_type");
    private static final List<String> BALANCE_KEYS = Arrays.asList("balance_after_transaction");

    /**
     * @return the first line that looks like a transaction table header, or {@code null}
     */
    public NativeTextLine locate(List<NativeTextLine> lines) {
        if (lines == null) {
            return null;
        }
        for (NativeTextLine line : lines) {
            if (isHeaderLine(line)) {
                return line;
            }
        }
        return null;
    }

    /**
     * A line is treated as a header when it carries a date keyword, an amount keyword and either a
     * balance or a description keyword, and when it is short enough to be a header (a transaction
     * row with a long narration is never a header).
     */
    public boolean isHeaderLine(NativeTextLine line) {
        if (line == null || line.getWords().size() < 3 || line.getWords().size() > 16) {
            return false;
        }
        String text = line.text();
        if (text == null || text.isBlank() || text.length() > 160) {
            return false;
        }

        Set<String> matched = matchedKeywordGroups(text);
        boolean hasDate = containsAny(matched, DATE_KEYS);
        boolean hasAmount = containsAny(matched, AMOUNT_KEYS);
        boolean hasBalance = containsAny(matched, BALANCE_KEYS);
        boolean hasDescription = containsAny(matched, DESCRIPTION_KEYS);

        return hasDate && hasAmount && (hasBalance || hasDescription);
    }

    private Set<String> matchedKeywordGroups(String text) {
        Set<String> matched = new LinkedHashSet<>();
        for (java.util.Map.Entry<String, Pattern> entry
                : BankTransactionTableHeaderIdentifier.HEADER_KEYWORD_REGEX_MAP.entrySet()) {
            if (entry.getValue().matcher(text).find()) {
                matched.add(entry.getKey());
            }
        }
        return matched;
    }

    private boolean containsAny(Set<String> matched, List<String> keys) {
        for (String key : keys) {
            if (matched.contains(key)) {
                return true;
            }
        }
        return false;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.ColumnDataType;
import com.finboost.bank.statement.parser.representation.document.extraction.ColumnTransactionType;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Assembles a {@link Table} - shaped exactly like the tables produced by the remote ML mapper -
 * out of native row bands / row line groups and column boundaries. Because the structure and the
 * coordinate space are identical, every downstream post processor (column normalisation, column
 * type identification, header/footer detection, transaction extraction) keeps working unchanged.
 */
@Component
public class NativeTableBuilder {

    /**
     * Builds a table where the rows are given as vertical bands and the words are distributed by
     * their center point.
     *
     * @param pageNumber       one based page number
     * @param columnBoundaries ascending column boundaries, {@code columnCount + 1} entries
     * @param rowBands         row bands as {@code {top, bottom}} pairs, ordered top to bottom
     * @param words            candidate words of the page
     */
    public Table buildFromBands(int pageNumber, List<Float> columnBoundaries, List<float[]> rowBands, List<Word> words) {
        List<List<Word>> rows = new ArrayList<>();
        for (float[] band : rowBands) {
            List<Word> rowWords = new LinkedList<>();
            for (Word word : words) {
                float centerY = (word.getY1() + word.getY3()) / 2f;
                if (centerY >= band[0] && centerY <= band[1]) {
                    rowWords.add(word);
                }
            }
            rows.add(rowWords);
        }
        return build(pageNumber, columnBoundaries, rowBands, rows);
    }

    /**
     * Builds a table where every row is an explicit group of text lines (used when the rows have
     * to be selected from the text flow instead of from drawn guides).
     */
    public Table buildFromLineGroups(int pageNumber, List<Float> columnBoundaries, List<List<NativeTextLine>> rowGroups) {
        List<float[]> bands = new ArrayList<>();
        List<List<Word>> rows = new ArrayList<>();

        for (List<NativeTextLine> group : rowGroups) {
            if (group.isEmpty()) {
                continue;
            }
            float top = Float.MAX_VALUE;
            float bottom = -Float.MAX_VALUE;
            List<Word> rowWords = new LinkedList<>();
            for (NativeTextLine line : group) {
                top = Math.min(top, line.getTop());
                bottom = Math.max(bottom, line.getBottom());
                rowWords.addAll(line.getWords());
            }
            bands.add(new float[]{top, bottom});
            rows.add(rowWords);
        }

        return build(pageNumber, columnBoundaries, bands, rows);
    }

    private Table build(int pageNumber, List<Float> columnBoundaries, List<float[]> rowBands, List<List<Word>> rowWords) {
        int columnCount = columnBoundaries.size() - 1;
        if (columnCount < 2 || rowBands.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        int rowIndex = 0;
        for (int i = 0; i < rowBands.size(); i++) {
            List<Word> words = rowWords.get(i);
            if (words.isEmpty()) {
                // completely empty bands are separators, not rows
                continue;
            }
            float[] band = rowBands.get(i);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            for (int column = 0; column < columnCount; column++) {
                row.put(column, createCell(rowIndex, column, columnBoundaries.get(column),
                        columnBoundaries.get(column + 1), band[0], band[1]));
            }
            for (Word word : words) {
                int column = columnOf(word, columnBoundaries);
                if (column >= 0) {
                    row.get(column).getWords().add(word);
                }
            }
            cells.put(rowIndex, row);
            rowIndex++;
        }

        if (cells.isEmpty()) {
            return null;
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setCells(cells);
        table.setTotalRows(cells.size());
        table.setTotalColumns(columnCount);
        table.setColType(new ArrayList<ColumnDataType>());
        table.setTxnColType(new ArrayList<ColumnTransactionType>());
        // the native path has no markdown span, keep the fields non null for the downstream code
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColumnBoundaries(new ArrayList<>(columnBoundaries));

        float left = columnBoundaries.get(0);
        float right = columnBoundaries.get(columnBoundaries.size() - 1);
        float top = rowBands.get(0)[0];
        float bottom = rowBands.get(rowBands.size() - 1)[1];
        table.setX1(left);
        table.setY1(top);
        table.setX2(right);
        table.setY2(top);
        table.setX3(right);
        table.setY3(bottom);
        table.setX4(left);
        table.setY4(bottom);

        return table;
    }

    private TableCell createCell(int rowIndex, int columnIndex, float left, float right, float top, float bottom) {
        TableCell cell = new TableCell();
        cell.setRowindex(rowIndex);
        cell.setColindex(columnIndex);
        cell.setRowspan(1);
        cell.setColspan(1);
        cell.setWords(new LinkedList<>());
        cell.setX1(left);
        cell.setY1(top);
        cell.setX2(right);
        cell.setY2(top);
        cell.setX3(right);
        cell.setY3(bottom);
        cell.setX4(left);
        cell.setY4(bottom);
        return cell;
    }

    /**
     * Column of a word, determined by its horizontal center. Words that stick out of the table
     * (page numbers, footers) are dropped by returning a negative index.
     */
    private int columnOf(Word word, List<Float> columnBoundaries) {
        float center = (word.getX1() + word.getX3()) / 2f;
        float first = columnBoundaries.get(0);
        float last = columnBoundaries.get(columnBoundaries.size() - 1);
        if (center < first) {
            return center >= first - 0.25f ? 0 : -1;
        }
        if (center > last) {
            return center <= last + 0.25f ? columnBoundaries.size() - 2 : -1;
        }
        for (int i = 0; i < columnBoundaries.size() - 1; i++) {
            if (center >= columnBoundaries.get(i) && center <= columnBoundaries.get(i + 1)) {
                return i;
            }
        }
        return -1;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import lombok.Setter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.Map;

/**
 * Decides whether a natively built table really looks like a bank transaction table.
 * The same content classifiers that the existing pipeline uses ({@link ColumnTypeIdentifier})
 * are reused so that a table accepted here is also usable for the downstream analysis.
 */
@Component
public class NativeTableValidator {

    /** A table is only accepted when this share of its rows looks like a transaction. */
    private static final double MIN_TRANSACTION_ROW_RATIO = 0.4d;
    /** Minimum number of columns of a transaction table (date, amount, balance). */
    private static final int MIN_COLUMNS = 3;

    @Setter(onMethod_ = @Autowired)
    private ColumnTypeIdentifier columnTypeIdentifier;

    /**
     * @return number of rows of the table that carry a date and at least one amount, or {@code 0}
     * when the table is not usable at all
     */
    public int countTransactionRows(Table table) {
        if (table == null || table.getCells() == null || table.getTotalColumns() == null
                || table.getTotalColumns() < MIN_COLUMNS) {
            return 0;
        }

        int transactionRows = 0;
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            if (looksLikeTransactionRow(row)) {
                transactionRows++;
            }
        }
        return transactionRows;
    }

    /**
     * A table is structurally valid when it has enough columns and enough of its rows look like
     * transactions - a page header block that accidentally produced a grid is rejected this way.
     */
    public boolean isStructurallyValid(Table table, int minTransactionRows) {
        int transactionRows = countTransactionRows(table);
        if (transactionRows < minTransactionRows) {
            return false;
        }
        int rows = table.getCells().size();
        return rows > 0 && ((double) transactionRows / rows) >= MIN_TRANSACTION_ROW_RATIO;
    }

    private boolean looksLikeTransactionRow(Map<Integer, TableCell> row) {
        if (row == null || row.isEmpty()) {
            return false;
        }
        boolean hasDate = false;
        int amountCells = 0;
        for (TableCell cell : row.values()) {
            String content = cell == null ? null : cell.getContent();
            if (content == null || content.isBlank()) {
                continue;
            }
            String trimmed = content.trim();
            if (!hasDate && columnTypeIdentifier.isDateType(trimmed)) {
                hasDate = true;
                continue;
            }
            if (columnTypeIdentifier.isAmountType(trimmed)) {
                amountCells++;
            }
        }
        return hasDate && amountCells >= 1;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;

import java.util.List;

/**
 * A native (offline) transaction table extraction strategy for one statement layout family.
 */
public interface NativeTableStrategy {

    /** The layout this strategy implements. */
    NativeTableLayout layout();

    /**
     * Extracts the transaction table(s) of a single page.
     *
     * @param page native content (text and vector guides) of the page
     * @return the tables found on that page, never {@code null}
     */
    List<Table> extractTables(NativePageContent page);
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeColumnDetector;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeGeometryUtil;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableBuilder;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Native strategy for statements whose transaction table is drawn as a complete grid: full width
 * row rulings plus column rulings that span the table body.
 * <p>
 * The grid is recovered from the vector guides only:
 * <ol>
 *     <li>the row rulings are grouped into contiguous blocks - a large vertical gap separates two
 *     independent tables (summary block versus transaction block),</li>
 *     <li>for every block the column rulings that cross the block define the column boundaries,</li>
 *     <li>consecutive row rulings become the row bands and the words are distributed into the
 *     resulting cells.</li>
 * </ol>
 */
@Component
@Slf4j
public class BorderedGridTableStrategy implements NativeTableStrategy {

    /** A row ruling has to cover this share of the table width. */
    private static final float MIN_ROW_RULING_COVERAGE = 0.6f;
    /** A column ruling has to cover this share of the block height. */
    private static final float MIN_COLUMN_RULING_COVERAGE = 0.55f;
    /** Multiple of the line height that separates two independent grids. */
    private static final float BLOCK_SEPARATION_FACTOR = 3.0f;
    /** Minimum number of row rulings of a grid (header ruling + 2 row rulings). */
    private static final int MIN_ROW_RULINGS = 3;

    @Setter(onMethod_ = @Autowired)
    private NativeColumnDetector nativeColumnDetector;

    @Setter(onMethod_ = @Autowired)
    private NativeTableBuilder nativeTableBuilder;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.BORDERED_GRID;
    }

    @Override
    public List<Table> extractTables(NativePageContent page) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText() || page.getVerticalRulings().isEmpty()
                || page.getHorizontalRulings().isEmpty()) {
            return tables;
        }

        float lineHeight = page.medianLineHeight();
        List<NativeRuling> columnRulings = longRulings(page.getVerticalRulings(), lineHeight * 1.2f);
        if (columnRulings.size() < 3) {
            return tables;
        }

        float gridLeft = Float.MAX_VALUE;
        float gridRight = -Float.MAX_VALUE;
        for (NativeRuling ruling : columnRulings) {
            gridLeft = Math.min(gridLeft, ruling.position());
            gridRight = Math.max(gridRight, ruling.position());
        }
        float gridWidth = gridRight - gridLeft;
        if (gridWidth <= 0.5f) {
            return tables;
        }

        List<Float> rowRulingPositions = new ArrayList<>();
        for (NativeRuling ruling : page.getHorizontalRulings()) {
            float overlap = Math.min(gridRight, ruling.end()) - Math.max(gridLeft, ruling.start());
            if (overlap >= gridWidth * MIN_ROW_RULING_COVERAGE) {
                rowRulingPositions.add(ruling.position());
            }
        }

        List<Float> separators = NativeGeometryUtil.clusterValues(rowRulingPositions, lineHeight * 0.35f);
        for (List<Float> block : splitIntoBlocks(separators, lineHeight * BLOCK_SEPARATION_FACTOR)) {
            Table table = buildBlock(page, block, columnRulings);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private Table buildBlock(NativePageContent page, List<Float> separators, List<NativeRuling> columnRulings) {
        if (separators.size() < MIN_ROW_RULINGS) {
            return null;
        }

        float top = separators.get(0);
        float bottom = separators.get(separators.size() - 1);
        List<Float> boundaries = nativeColumnDetector.fromRulings(columnRulings, top, bottom, MIN_COLUMN_RULING_COVERAGE);
        if (boundaries.size() < 4) {
            return null;
        }

        List<float[]> bands = new ArrayList<>();
        for (int i = 0; i < separators.size() - 1; i++) {
            bands.add(new float[]{separators.get(i), separators.get(i + 1)});
        }

        List<Word> words = new LinkedList<>();
        for (Word word : page.getWords()) {
            float centerY = (word.getY1() + word.getY3()) / 2f;
            if (centerY >= top && centerY <= bottom) {
                words.add(word);
            }
        }
        if (words.isEmpty()) {
            return null;
        }

        return nativeTableBuilder.buildFromBands(page.getPageNumber(), boundaries, bands, words);
    }

    /** Splits the row separators into contiguous grids. */
    private List<List<Float>> splitIntoBlocks(List<Float> separators, float maxGap) {
        List<List<Float>> blocks = new LinkedList<>();
        List<Float> current = new ArrayList<>();
        for (Float separator : separators) {
            if (!current.isEmpty() && separator - current.get(current.size() - 1) > maxGap) {
                blocks.add(current);
                current = new ArrayList<>();
            }
            current.add(separator);
        }
        if (!current.isEmpty()) {
            blocks.add(current);
        }
        return blocks;
    }

    private List<NativeRuling> longRulings(List<NativeRuling> rulings, float minLength) {
        List<NativeRuling> result = new LinkedList<>();
        for (NativeRuling ruling : rulings) {
            if (ruling.length() >= minLength) {
                result.add(ruling);
            }
        }
        return result;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeColumnDetector;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeGeometryUtil;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeHeaderLocator;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableBuilder;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeBox;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Native strategy for statements that do not draw a full grid but guide every transaction row with
 * a drawn box: either one shaded/stroked band per row, one rectangle per cell, or a full width
 * horizontal rule between two rows (AXIS, ICICI, BOB, INDIAN, DEUTSCHE style statements).
 * <p>
 * Rows come from the boxes (or the row rules), the columns come - in this order - from the box
 * edges, from column rulings, from the header alignment or from the vertical whitespace that is
 * free in every row.
 */
@Component
@Slf4j
public class BoxGuidedTableStrategy implements NativeTableStrategy {

    /** A row guide has to cover this share of the page width. */
    private static final float MIN_ROW_GUIDE_WIDTH_RATIO = 0.3f;
    /** Vertical overlap needed to put two boxes into the same row band. */
    private static final float ROW_OVERLAP_RATIO = 0.5f;
    /** Multiple of the line height that separates two independent blocks. */
    private static final float BLOCK_SEPARATION_FACTOR = 4.0f;
    /** Minimum number of row bands of a table. */
    private static final int MIN_ROW_BANDS = 3;
    /** Number of boxes a row band needs to expose usable column edges. */
    private static final int MIN_BOXES_FOR_COLUMN_EDGES = 3;

    @Setter(onMethod_ = @Autowired)
    private NativeColumnDetector nativeColumnDetector;

    @Setter(onMethod_ = @Autowired)
    private NativeTableBuilder nativeTableBuilder;

    @Setter(onMethod_ = @Autowired)
    private NativeHeaderLocator nativeHeaderLocator;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.BOX_GUIDED;
    }

    @Override
    public List<Table> extractTables(NativePageContent page) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        float lineHeight = page.medianLineHeight();
        List<List<NativeBox>> rowBands = groupBoxesIntoRows(page, lineHeight);
        List<float[]> bands = new ArrayList<>();
        List<List<NativeBox>> bandBoxes = new ArrayList<>();

        if (rowBands.size() >= MIN_ROW_BANDS) {
            for (List<NativeBox> boxes : rowBands) {
                float top = Float.MAX_VALUE;
                float bottom = -Float.MAX_VALUE;
                for (NativeBox box : boxes) {
                    top = Math.min(top, box.getTop());
                    bottom = Math.max(bottom, box.getBottom());
                }
                bands.add(new float[]{top, bottom});
                bandBoxes.add(boxes);
            }
        } else {
            for (float[] band : bandsFromRowRules(page, lineHeight)) {
                bands.add(band);
                bandBoxes.add(new ArrayList<>());
            }
        }

        if (bands.size() < MIN_ROW_BANDS) {
            return tables;
        }

        for (int[] block : splitIntoBlocks(bands, lineHeight * BLOCK_SEPARATION_FACTOR)) {
            Table table = buildBlock(page, bands, bandBoxes, block[0], block[1], lineHeight);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private Table buildBlock(NativePageContent page, List<float[]> bands, List<List<NativeBox>> bandBoxes,
                             int from, int to, float lineHeight) {
        if (to - from + 1 < MIN_ROW_BANDS) {
            return null;
        }

        float top = bands.get(from)[0];
        float bottom = bands.get(to)[1];

        List<Word> blockWords = new LinkedList<>();
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (Word word : page.getWords()) {
            float centerY = (word.getY1() + word.getY3()) / 2f;
            if (centerY >= top - lineHeight && centerY <= bottom + lineHeight) {
                blockWords.add(word);
                left = Math.min(left, word.getX1());
                right = Math.max(right, word.getX3());
            }
        }
        if (blockWords.isEmpty()) {
            return null;
        }

        List<float[]> blockBands = new ArrayList<>();
        List<NativeBox> blockBoxes = new ArrayList<>();
        for (int i = from; i <= to; i++) {
            blockBands.add(bands.get(i));
            blockBoxes.addAll(bandBoxes.get(i));
        }

        // the header of a box guided table is often placed above the first guided row, add it as
        // an own row band so that the downstream header based column typing still sees it
        NativeTextLine headerLine = findHeaderLine(page, top, lineHeight);
        if (headerLine != null) {
            blockBands.add(0, new float[]{headerLine.getTop() - 0.01f, headerLine.getBottom() + 0.01f});
            for (Word word : headerLine.getWords()) {
                if (!blockWords.contains(word)) {
                    blockWords.add(word);
                    left = Math.min(left, word.getX1());
                    right = Math.max(right, word.getX3());
                }
            }
        }

        List<Float> boundaries = resolveColumns(page, headerLine, blockBoxes, blockWords, left, right, top, bottom);
        if (boundaries.size() < 4) {
            return null;
        }

        return nativeTableBuilder.buildFromBands(page.getPageNumber(), boundaries, blockBands, blockWords);
    }

    /**
     * Resolves the column boundaries of a block. Drawn cell boxes are the most reliable source,
     * then column rulings, then the header alignment and finally the vertical whitespace.
     */
    private List<Float> resolveColumns(NativePageContent page, NativeTextLine headerLine, List<NativeBox> boxes,
                                       List<Word> words, float left, float right, float top, float bottom) {
        List<Float> edges = new ArrayList<>();
        int cellBoxes = 0;
        for (NativeBox box : boxes) {
            if (box.width() < right - left) {
                cellBoxes++;
                edges.add(box.getLeft());
                edges.add(box.getRight());
            }
        }
        if (cellBoxes >= MIN_BOXES_FOR_COLUMN_EDGES) {
            List<Float> boundaries = NativeGeometryUtil.clusterValues(edges, 0.12f);
            if (boundaries.size() >= 4) {
                return boundaries;
            }
        }

        List<Float> fromRulings = nativeColumnDetector.fromRulings(page.getVerticalRulings(), top, bottom, 0.5f);
        if (fromRulings.size() >= 4) {
            return fromRulings;
        }

        if (headerLine != null) {
            List<Float> fromHeader = nativeColumnDetector.fromHeaderLine(headerLine, words, left, right);
            if (fromHeader.size() >= 4) {
                return fromHeader;
            }
        }

        return nativeColumnDetector.fromWhitespaceProfile(words, left, right);
    }

    private NativeTextLine findHeaderLine(NativePageContent page, float tableTop, float lineHeight) {
        NativeTextLine best = null;
        for (NativeTextLine line : page.getTextLines()) {
            if (line.getBottom() > tableTop + lineHeight) {
                continue;
            }
            if (nativeHeaderLocator.isHeaderLine(line)) {
                best = line;
            }
        }
        return best;
    }

    /** Groups the row guiding boxes of a page into row bands. */
    private List<List<NativeBox>> groupBoxesIntoRows(NativePageContent page, float lineHeight) {
        List<NativeBox> candidates = new ArrayList<>();
        for (NativeBox box : page.getBoxes()) {
            float height = box.height();
            if (height < lineHeight * 0.4f || height > lineHeight * 8f) {
                continue;
            }
            if (box.width() < 0.1f || box.height() >= page.getHeight() * 0.8f) {
                continue;
            }
            candidates.add(box);
        }
        candidates.sort(Comparator.comparing(NativeBox::getTop));

        List<List<NativeBox>> bands = new LinkedList<>();
        List<NativeBox> current = new ArrayList<>();
        float currentTop = 0f;
        float currentBottom = 0f;
        for (NativeBox box : candidates) {
            if (current.isEmpty()) {
                current.add(box);
                currentTop = box.getTop();
                currentBottom = box.getBottom();
                continue;
            }
            float overlap = Math.min(currentBottom, box.getBottom()) - Math.max(currentTop, box.getTop());
            float minHeight = Math.min(currentBottom - currentTop, box.height());
            if (minHeight > 0f && overlap >= minHeight * ROW_OVERLAP_RATIO) {
                current.add(box);
                currentTop = Math.min(currentTop, box.getTop());
                currentBottom = Math.max(currentBottom, box.getBottom());
            } else {
                bands.add(current);
                current = new ArrayList<>();
                current.add(box);
                currentTop = box.getTop();
                currentBottom = box.getBottom();
            }
        }
        if (!current.isEmpty()) {
            bands.add(current);
        }

        // only keep bands that guide a row of text
        List<List<NativeBox>> withText = new LinkedList<>();
        for (List<NativeBox> band : bands) {
            float top = Float.MAX_VALUE;
            float bottom = -Float.MAX_VALUE;
            float width = 0f;
            for (NativeBox box : band) {
                top = Math.min(top, box.getTop());
                bottom = Math.max(bottom, box.getBottom());
                width = Math.max(width, box.width());
            }
            if (width < page.getWidth() * MIN_ROW_GUIDE_WIDTH_RATIO && band.size() < MIN_BOXES_FOR_COLUMN_EDGES) {
                continue;
            }
            if (containsText(page, top, bottom)) {
                withText.add(band);
            }
        }
        return withText;
    }

    /** Row bands taken from full width horizontal rules when no row boxes are drawn. */
    private List<float[]> bandsFromRowRules(NativePageContent page, float lineHeight) {
        List<Float> positions = new ArrayList<>();
        for (NativeRuling ruling : page.getHorizontalRulings()) {
            if (ruling.length() >= page.getWidth() * MIN_ROW_GUIDE_WIDTH_RATIO) {
                positions.add(ruling.position());
            }
        }
        List<Float> separators = NativeGeometryUtil.clusterValues(positions, lineHeight * 0.35f);

        List<float[]> bands = new ArrayList<>();
        for (int i = 0; i < separators.size() - 1; i++) {
            float top = separators.get(i);
            float bottom = separators.get(i + 1);
            if (containsText(page, top, bottom)) {
                bands.add(new float[]{top, bottom});
            }
        }
        return bands;
    }

    private boolean containsText(NativePageContent page, float top, float bottom) {
        for (NativeTextLine line : page.getTextLines()) {
            float center = line.centerY();
            if (center >= top && center <= bottom) {
                return true;
            }
        }
        return false;
    }

    /** Splits the row bands into contiguous blocks, returning {@code {fromIndex, toIndex}} pairs. */
    private List<int[]> splitIntoBlocks(List<float[]> bands, float maxGap) {
        List<int[]> blocks = new LinkedList<>();
        int from = 0;
        for (int i = 1; i < bands.size(); i++) {
            if (bands.get(i)[0] - bands.get(i - 1)[1] > maxGap) {
                blocks.add(new int[]{from, i - 1});
                from = i;
            }
        }
        blocks.add(new int[]{from, bands.size() - 1});
        return blocks;
    }
}

