 * Continuation pages frequently repeat neither the table header nor the vector guides, the context
 * lets a strategy reuse the geometry it derived from the first page of the statement.
 */
@Data
public class NativeExtractionContext {

    /** Column boundaries of the last table that was built successfully. */
    private List<Float> columnBoundaries;

    /** Index of the transaction date column of the last table that was built successfully. */
    private Integer dateColumnIndex;

    public boolean hasColumnBoundaries() {
        return columnBoundaries != null && columnBoundaries.size() >= 4;
    }
}

