package com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeColumnDetector;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeExtractionContext;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeHeaderLocator;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableBuilder;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Native strategy for statements without any vector guide. The table is recovered purely from the
 * text: the header line is located by the well known header keywords, the columns are derived from
 * the header alignment (refined with the body words) and the rows are <em>selected</em> from the
 * text lines - a line that carries a date in the date column starts a new transaction row while the
 * following lines are merged into that row as wrapped narration.
 */
@Component
@Slf4j
public class TextAlignedRowSelectedTableStrategy implements NativeTableStrategy {

    /** Maximum vertical distance (as a multiple of the line height) of a continuation line. */
    private static final float MAX_CONTINUATION_GAP = 2.5f;
    /** Minimum number of transaction rows a page has to contribute. */
    private static final int MIN_ROWS = 2;

    @Setter(onMethod_ = @Autowired)
    private NativeColumnDetector nativeColumnDetector;

    @Setter(onMethod_ = @Autowired)
    private NativeTableBuilder nativeTableBuilder;

    @Setter(onMethod_ = @Autowired)
    private NativeHeaderLocator nativeHeaderLocator;

    @Setter(onMethod_ = @Autowired)
    private ColumnTypeIdentifier columnTypeIdentifier;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> extractTables(NativePageContent page, NativeExtractionContext context) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText() || page.getTextLines().size() < 3) {
            return tables;
        }

        NativeTextLine headerLine = nativeHeaderLocator.locate(page.getTextLines());
        List<NativeTextLine> bodyLines = bodyLines(page, headerLine);
        if (bodyLines.size() < MIN_ROWS) {
            return tables;
        }

        List<Float> boundaries = resolveColumns(page, headerLine, bodyLines, context);
        if (boundaries.size() < 4) {
            return tables;
        }

        int dateColumn = resolveDateColumn(bodyLines, boundaries, context);
        if (dateColumn < 0) {
            return tables;
        }

        List<List<NativeTextLine>> rows = selectRows(bodyLines, boundaries, dateColumn, page.medianLineHeight());
        if (rows.size() < MIN_ROWS) {
            return tables;
        }

        if (headerLine != null) {
            List<NativeTextLine> headerRow = new ArrayList<>();
            headerRow.add(headerLine);
            rows.add(0, headerRow);
        }

        Table table = nativeTableBuilder.buildFromLineGroups(page.getPageNumber(), boundaries, rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<NativeTextLine> bodyLines(NativePageContent page, NativeTextLine headerLine) {
        List<NativeTextLine> bodyLines = new LinkedList<>();
        for (NativeTextLine line : page.getTextLines()) {
            if (headerLine != null && line.getCenterY() <= headerLine.getBottom()) {
                continue;
            }
            if (!line.getWords().isEmpty()) {
                bodyLines.add(line);
            }
        }
        return bodyLines;
    }

    private List<Float> resolveColumns(NativePageContent page, NativeTextLine headerLine,
                                       List<NativeTextLine> bodyLines, NativeExtractionContext context) {
        List<Word> bodyWords = new LinkedList<>();
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (NativeTextLine line : bodyLines) {
            for (Word word : line.getWords()) {
                bodyWords.add(word);
                left = Math.min(left, word.getX1());
                right = Math.max(right, word.getX3());
            }
        }

        if (headerLine != null) {
            List<Float> fromHeader = nativeColumnDetector.fromHeaderLine(headerLine, bodyWords, left, right);
            if (fromHeader.size() >= 4) {
                return fromHeader;
            }
        }

        // continuation pages usually repeat neither header nor guides, reuse the known geometry
        if (context != null && context.hasColumnBoundaries()) {
            return context.getColumnBoundaries();
        }

        return nativeColumnDetector.fromWhitespaceProfile(bodyWords, left, right);
    }

    /**
     * Finds the column that carries the transaction date. The left most column with date content in
     * most of its non empty cells wins, which also covers statements that start with a serial number.
     */
    private int resolveDateColumn(List<NativeTextLine> bodyLines, List<Float> boundaries, NativeExtractionContext context) {
        int columnCount = boundaries.size() - 1;
        int[] dateHits = new int[columnCount];
        int[] filled = new int[columnCount];

        for (NativeTextLine line : bodyLines) {
            String[] contents = contentsOf(line, boundaries);
            for (int column = 0; column < columnCount; column++) {
                if (contents[column] == null || contents[column].isBlank()) {
                    continue;
                }
                filled[column]++;
                if (columnTypeIdentifier.isDateType(contents[column])) {
                    dateHits[column]++;
                }
            }
        }

        for (int column = 0; column < columnCount; column++) {
            if (dateHits[column] >= MIN_ROWS && dateHits[column] * 2 >= filled[column]) {
                return column;
            }
        }

        if (context != null && context.getDateColumnIndex() != null
                && context.getDateColumnIndex() < columnCount) {
            return context.getDateColumnIndex();
        }
        return -1;
    }

    /**
     * Selects the rows of the table: a line with a date in the date column and at least one amount
     * opens a new row, every following line that is close enough and has no own date is merged into
     * that row.
     */
    private List<List<NativeTextLine>> selectRows(List<NativeTextLine> bodyLines, List<Float> boundaries,
                                                  int dateColumn, float lineHeight) {
        List<List<NativeTextLine>> rows = new LinkedList<>();
        List<NativeTextLine> current = null;
        NativeTextLine previous = null;

        for (NativeTextLine line : bodyLines) {
            String[] contents = contentsOf(line, boundaries);
            boolean startsRow = contents[dateColumn] != null && !contents[dateColumn].isBlank()
                    && columnTypeIdentifier.isDateType(contents[dateColumn])
                    && hasAmount(contents, dateColumn);

            if (startsRow) {
                current = new ArrayList<>();
                current.add(line);
                rows.add(current);
            } else if (current != null && previous != null
                    && (line.getTop() - previous.getBottom()) <= lineHeight * MAX_CONTINUATION_GAP
                    && (contents[dateColumn] == null || contents[dateColumn].isBlank())) {
                current.add(line);
            } else {
                current = null;
            }
            previous = line;
        }

        return rows;
    }

    private boolean hasAmount(String[] contents, int dateColumn) {
        for (int column = 0; column < contents.length; column++) {
            if (column == dateColumn || contents[column] == null || contents[column].isBlank()) {
                continue;
            }
            if (columnTypeIdentifier.isAmountType(contents[column].trim())) {
                return true;
            }
        }
        return false;
    }

    /** Content of a text line split into the columns of the table. */
    private String[] contentsOf(NativeTextLine line, List<Float> boundaries) {
        int columnCount = boundaries.size() - 1;
        StringBuilder[] builders = new StringBuilder[columnCount];
        for (int i = 0; i < columnCount; i++) {
            builders[i] = new StringBuilder();
        }

        for (Word word : line.orderedWords()) {
            float center = (word.getX1() + word.getX3()) / 2f;
            for (int column = 0; column < columnCount; column++) {
                if (center >= boundaries.get(column) && center <= boundaries.get(column + 1)) {
                    if (builders[column].length() > 0) {
                        builders[column].append(' ');
                    }
                    builders[column].append(word.getContent() == null ? "" : word.getContent());
                    break;
                }
            }
        }

        String[] contents = new String[columnCount];
        for (int i = 0; i < columnCount; i++) {
            contents[i] = builders[i].toString().trim();
        }
        return contents;
    }
}

