package com.finboost.bank.statement.parser.config.document.extraction.nativetable;

import lombok.Data;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Configuration of the offline/native transaction table extraction.
 * <p>
 * Example:
 * <pre>
 * native.table.extraction.enabled=true
 * native.table.extraction.min-transaction-rows=3
 * native.table.extraction.bank-layouts.HDFC=BORDERED_GRID,BOX_GUIDED
 * </pre>
 * Banks that are not covered by the registry (and not configured here) keep using the remote ML
 * extraction, which stays the default for unknown or unsupported layouts.
 */
@Data
@Configuration
@ConfigurationProperties(prefix = "native.table.extraction")
public class NativeTableExtractionProperties {

    /** Master switch for the native transaction table path. */
    private boolean enabled = true;

    /** Minimum number of transaction rows a native result has to contain to be accepted. */
    private int minTransactionRows = 3;

    /**
     * Overrides / additions to the built in bank policy registry. The key is the bank code, the
     * value is a comma separated, ordered list of {@code NativeTableLayout} names. An empty value
     * disables the native path for that bank.
     */
    private Map<String, String> bankLayouts = new LinkedHashMap<>();

    /**
     * Layouts that are attempted for banks that are not part of the registry. Empty by default so
     * that unknown layouts are handed to the remote ML extraction.
     */
    private String unknownBankLayouts = "";
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.config.document.extraction.nativetable.NativeTableExtractionProperties;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Maps a bank format family to the ordered list of native layouts that should be attempted for it.
 * <p>
 * The mapping was derived by measuring the vector guides of every statement of the repository
 * fixture corpus ({@code src/test/resources/pdf-samples-latest}). For each bank the dominant guide
 * type decides the primary layout, the remaining observed variants are kept as ordered fallbacks:
 * </p>
 * <ul>
 *     <li>{@code BORDERED_GRID} - row rulings <em>and</em> body spanning column rulings
 *     (BANDHAN, FEDERAL, GS Mahanagar, HDFC, IDBI, IDFC, INDUSIND, PNB, STANDARD_CHARTERED,
 *     SURYODAY, TJSB, YES).</li>
 *     <li>{@code BOX_GUIDED} - per row / per cell rectangles or row rules without column rulings
 *     (AHMEDNAGAR, AXIS, BOB, DEUTSCHE, ICICI, INDIAN, INDIAN_OVERSEAS, RBL, SBI, UNION, CBI).</li>
 *     <li>{@code TEXT_ALIGNED_ROW_SELECTED} - no vector guides at all (CITI, KOTAK and the
 *     guide free variants of the banks above).</li>
 * </ul>
 * Every bank that is not listed here keeps using the remote ML extraction.
 */
@Component
@Slf4j
public class NativeLayoutPolicyRegistry {

    private static final Map<String, List<NativeTableLayout>> DEFAULT_POLICIES = createDefaultPolicies();

    @Setter(onMethod_ = @Autowired)
    private NativeTableExtractionProperties nativeTableExtractionProperties;

    /**
     * @param bankName bank code of the statement, may be {@code null}
     * @return ordered layouts to attempt, empty when the bank/layout is not supported natively
     */
    public List<NativeTableLayout> resolvePolicy(String bankName) {
        if (!nativeTableExtractionProperties.isEnabled()) {
            return Collections.emptyList();
        }

        String key = normalize(bankName);
        Map<String, String> overrides = nativeTableExtractionProperties.getBankLayouts();
        if (key != null && overrides != null) {
            for (Map.Entry<String, String> entry : overrides.entrySet()) {
                if (key.equals(normalize(entry.getKey()))) {
                    return parseLayouts(entry.getValue());
                }
            }
        }

        if (key != null && DEFAULT_POLICIES.containsKey(key)) {
            return DEFAULT_POLICIES.get(key);
        }

        return parseLayouts(nativeTableExtractionProperties.getUnknownBankLayouts());
    }

    /** @return {@code true} when at least one native layout is configured for the bank */
    public boolean isNativeSupported(String bankName) {
        return !resolvePolicy(bankName).isEmpty();
    }

    private List<NativeTableLayout> parseLayouts(String configured) {
        if (configured == null || configured.isBlank()) {
            return Collections.emptyList();
        }
        List<NativeTableLayout> layouts = new ArrayList<>();
        for (String token : configured.split(",")) {
            String name = token.trim().toUpperCase();
            if (name.isEmpty()) {
                continue;
            }
            try {
                NativeTableLayout layout = NativeTableLayout.valueOf(name);
                if (!layouts.contains(layout)) {
                    layouts.add(layout);
                }
            } catch (IllegalArgumentException e) {
                log.warn("Ignoring unknown native table layout '{}'", name);
            }
        }
        return layouts;
    }

    private String normalize(String bankName) {
        if (bankName == null || bankName.isBlank()) {
            return null;
        }
        return bankName.trim().toUpperCase().replaceAll("[^A-Z0-9]+", "_");
    }

    private static Map<String, List<NativeTableLayout>> createDefaultPolicies() {
        Map<String, List<NativeTableLayout>> policies = new LinkedHashMap<>();

        // bordered grid families: row rulings plus column rulings across the table body
        put(policies, "BANDHAN", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "FEDERAL", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "GS_MAHANAGAR_CO_OP_BANK", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "IDBI", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "IDFC", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "STANDARD_CHARTERED", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "SURYODAY_SMALL_FINANCE_BANK_LTD", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "TJSB_BANK", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);
        put(policies, "YES", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED);

        // bordered grid families that also ship guide free variants
        put(policies, "HDFC", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "INDUSIND", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "PNB", NativeTableLayout.BORDERED_GRID, NativeTableLayout.BOX_GUIDED,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);

        // box guided families: row/cell rectangles or row rules, no column rulings
        put(policies, "AHMEDNAGAR", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "AXIS", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "BOB", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "BANK_OF_BARODA", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "DEUSTCHE", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "DEUTSCHE", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "INDIAN", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "INDIAN_OVERSEAS", NativeTableLayout.BOX_GUIDED, NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);

        // box guided families that also ship bordered grid variants
        put(policies, "CBI", NativeTableLayout.BOX_GUIDED, NativeTableLayout.BORDERED_GRID,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "ICICI", NativeTableLayout.BOX_GUIDED, NativeTableLayout.BORDERED_GRID,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "RBL", NativeTableLayout.BOX_GUIDED, NativeTableLayout.BORDERED_GRID,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "SBI", NativeTableLayout.BOX_GUIDED, NativeTableLayout.BORDERED_GRID,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);
        put(policies, "UNION", NativeTableLayout.BOX_GUIDED, NativeTableLayout.BORDERED_GRID,
                NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED);

        // text aligned families: the fixtures carry no vector guides at all
        put(policies, "CITI", NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED, NativeTableLayout.BOX_GUIDED);
        put(policies, "KOTAK", NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED, NativeTableLayout.BOX_GUIDED);

        return Collections.unmodifiableMap(policies);
    }

    private static void put(Map<String, List<NativeTableLayout>> policies, String bank, NativeTableLayout... layouts) {
        policies.put(bank, Collections.unmodifiableList(Arrays.asList(layouts)));
    }
}

