import java.io.File;
import java.util.LinkedList;
import java.util.List;
import java.util.regex.Pattern;

@Component
public class FederalBankUtil {
    public static void identifyStatementFormatSpecificColumnType(DocumentExtractionResult result,  DocumentExtractionRequest documentExtractionRequest){
        try{
            String fileContent = PdfTextExtractionUtil.convertPDFToText(documentExtractionRequest.getStatementFile());
            if(Pattern.compile("(?m)^Date\\s*Value\\s*Date\\s*Particulars\\s*Tran$").matcher(fileContent).find() && Pattern.compile("(?m)^Type\\s*Tran\\s*ID\\s*Cheque$").matcher(fileContent).find() &&
                    Pattern.compile("(?m)^Details\\s*Withdrawals\\s*Deposits\\s*Balance\\s*Dr/Cr$").matcher(fileContent).find()){
                identifyColumnHavingCrDrAfterBalanceFormat(result);
            }
        }catch (Exception e){
            e.printStackTrace();
        }
    }

    public static void identifyColumnHavingCrDrAfterBalanceFormat(DocumentExtractionResult result){
        List<ColumnTransactionType> columnTransactionTypes = new LinkedList<>();
        columnTransactionTypes.add(0, ColumnTransactionType.TransactionDate);
        columnTransactionTypes.add(1, ColumnTransactionType.ValueDate);
        columnTransactionTypes.add(2, ColumnTransactionType.Description);
        columnTransactionTypes.add(3, ColumnTransactionType.Others);
        columnTransactionTypes.add(4, ColumnTransactionType.Others);
        columnTransactionTypes.add(5, ColumnTransactionType.ChequeOrRef);
        columnTransactionTypes.add(6, ColumnTransactionType.Debit);
        columnTransactionTypes.add(7, ColumnTransactionType.Credit);
        columnTransactionTypes.add(8, ColumnTransactionType.Balance);
        columnTransactionTypes.add(9, ColumnTransactionType.AmountType);

        for(Integer pageNumber : result.getPages().keySet()){
            if(result.getPages().get(pageNumber) == null){
                continue;
            }
            for(Integer tableNumber : result.getPages().get(pageNumber).getTables().keySet()){
                Table table = result.getPages().get(pageNumber).getTables().get(tableNumber);
                if(table != null && table.getCells() != null && !table.getCells().isEmpty()
                        && table.getCells().get(0) != null && table.getCells().get(0).get(0) != null &&
                        table.getCells().get(0).get(0).getContent().contains("Date")){
                    Table copyTable = table.copy();
                    for(Integer rowNumber : copyTable.getCells().keySet()){

                        if(copyTable.getCells().get(rowNumber).get(0).getContent().contains("Date")){
                            continue;
                        }

                        TableCell balanceCell = copyTable.getCells().get(rowNumber).get(8);
                        TableCell balanceTypeCell = copyTable.getCells().get(rowNumber).get(9);

                        if(balanceCell == null || balanceCell.getContent().isBlank() ||
                                balanceTypeCell == null || balanceTypeCell.getContent().isBlank()){
                            continue;
                        }

                        if(balanceTypeCell.getContent().toLowerCase().contains("cr") || balanceTypeCell.getContent().toLowerCase().contains("dr")){
                            TableCell copyCell = balanceTypeCell.copy();
                            Word word = copyCell.getWords().get(0);
                            balanceCell.getWords().add(word);
                        }
                    }
                    copyTable.setTxnColType(columnTransactionTypes);
                    copyTable.setBankTransactions(Boolean.TRUE);
                    result.getPages().get(pageNumber).getTables().put(tableNumber, copyTable);
                }
            }
        }
        result.setSkipFurtherProcessing(Boolean.TRUE);
    }
}

