package com.finboost.bank.statement.parser.service.document.extraction;

import com.finboost.bank.statement.parser.representation.document.extraction.ColumnTransactionType;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.EPdfCharacterExtractionService;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * The document analysis that is applied to the extracted tables no matter where they came from
 * (remote ML extraction or the offline/native table extraction): character level enrichment,
 * bank specific processing, column range verification and the full column/row analysis.
 * <p>
 * Keeping this in one place guarantees that a native result is carried through exactly the same
 * downstream analysis as an ML result, so the transaction and date parsing behaviour is unchanged.
 * </p>
 */
@Component
@Slf4j
public class StatementDocumentAnalysisPipeline {

    /** Number of leading pages used to verify the detected column ranges. */
    private static final int VERIFICATION_PAGE_COUNT = 5;

    @Setter(onMethod_ = @Autowired)
    private EPdfCharacterExtractionService ePdfCharacterExtractionService;

    @Setter(onMethod_ = @Autowired)
    private AnalyzeDocuments analyzeDocuments;

    @Setter(onMethod_ = @Autowired)
    private IBankSpecificParsingService bankSpecificParsingService;

    /**
     * Runs the downstream analysis on an extraction result.
     *
     * @param result                    the extracted document
     * @param request                   the original extraction request
     * @param enhanceWithCharacterInfo  {@code true} for results whose words do not carry character
     *                                  level information yet (the ML path), {@code false} for the
     *                                  native path which already works on PDF characters
     */
    public DocumentExtractionResult analyze(DocumentExtractionResult result, DocumentExtractionRequest request,
                                            boolean enhanceWithCharacterInfo) {
        if (result == null) {
            return null;
        }

        if (enhanceWithCharacterInfo) {
            try {
                boolean enhanced = ePdfCharacterExtractionService
                        .enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
                if (enhanced) {
                    log.info("Successfully enhanced document with character-level information");
                } else {
                    log.info("Document could not be enhanced with character-level information (likely a scanned PDF)");
                }
            } catch (Exception e) {
                log.warn("Failed to enhance document with character-level information: {}", e.getMessage());
            }
        }

        //check if the bank statement parsing happen bank specific
        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if (result.isSkipFurtherProcessing()) {
            return result;
        }

        DocumentExtractionResult preProcessedResultByHeader =
                analyzeDocuments.preProcessForVerificationByHeader(result, VERIFICATION_PAGE_COUNT);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            int pageCount = result.getNoOfPages() == null ? 0 : result.getNoOfPages();
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, pageCount);
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }

        analyzeDocuments.analyzeDocument(result, true, true, true);

        return result;
    }

    /**
     * @return {@code true} when the analysed document contains at least one table that the
     * downstream transaction extraction can use
     */
    public boolean hasUsableTransactionTable(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null) {
            return false;
        }
        for (Page page : result.getPages().values()) {
            if (page == null || page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                if (table == null || !table.getIsTransactionTable()) {
                    continue;
                }
                List<ColumnTransactionType> columnTypes = table.getTxnColType();
                if (columnTypes != null && columnTypes.contains(ColumnTransactionType.TransactionDate)) {
                    return true;
                }
            }
        }
        return false;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.azure;

import com.azure.ai.documentintelligence.models.AnalyzeResult;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.StatementDocumentAnalysisPipeline;
import com.finboost.bank.statement.parser.util.document.extraction.DocumentExtractionRequestFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;

/**
 * Remote ML (Azure Document Intelligence) extraction. This is the default extraction path for
 * unknown or natively unsupported statement layouts.
 */
@Service
@Slf4j
public class AzureDocumentExtractionServiceImpl implements DocumentExtractionService {

    private AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor;
    private AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper;
    private StatementDocumentAnalysisPipeline statementDocumentAnalysisPipeline;

    @Autowired
    public void setAzureDocumentIntelligenceProcessor(AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor) {
        this.azureDocumentIntelligenceProcessor = azureDocumentIntelligenceProcessor;
    }

    @Autowired
    public void setAzureDocumentIntelligenceResponseMapper(AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper) {
        this.azureDocumentIntelligenceResponseMapper = azureDocumentIntelligenceResponseMapper;
    }

    @Autowired
    public void setStatementDocumentAnalysisPipeline(StatementDocumentAnalysisPipeline statementDocumentAnalysisPipeline) {
        this.statementDocumentAnalysisPipeline = statementDocumentAnalysisPipeline;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        return extractDocument(DocumentExtractionRequestFactory.fromBankStatement(bankStatementVO));
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        // Process with Azure Document Intelligence
        AnalyzeResult analyzeResult = azureDocumentIntelligenceProcessor.processDocument(request.getStatementFile());
        DocumentExtractionResult result = azureDocumentIntelligenceResponseMapper.mapAnalyzeResultToDocument(analyzeResult);

        if (result.getNativeExtractionDiagnostics() == null) {
            result.setNativeExtractionDiagnostics(NativeExtractionDiagnostics.ml(null));
        }

        // Enhance with character-level information and run the shared downstream analysis
        return statementDocumentAnalysisPipeline.analyze(result, request, true);
    }
}

package com.finboost.bank.statement.parser.util.document.extraction;

import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import lombok.extern.slf4j.Slf4j;

/**
 * Builds a {@link DocumentExtractionRequest} out of a {@link BankStatementVO}. Shared by every
 * extraction path so that the native and the ML path see exactly the same request.
 */
@Slf4j
public final class DocumentExtractionRequestFactory {

    private DocumentExtractionRequestFactory() {
    }

    public static DocumentExtractionRequest fromBankStatement(BankStatementVO bankStatementVO) {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(
                    BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}",
                    bankStatementVO.getBankAccountDetailsVO() == null
                            ? null : bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        return documentExtractionRequest;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionMode;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.Data;

import java.util.ArrayList;
import java.util.List;

/**
 * Result of an attempt to extract the transaction tables of a statement natively.
 */
@Data
public class NativeExtractionOutcome {

    /** The natively extracted document, {@code null} when no layout produced a usable table. */
    private DocumentExtractionResult result;

    private NativeExtractionDiagnostics diagnostics;

    public boolean isSuccessful() {
        return result != null;
    }

    public static NativeExtractionOutcome success(DocumentExtractionResult result, NativeTableLayout appliedLayout,
                                                 List<NativeTableLayout> attemptedLayouts, int rowCount, int tableCount) {
        NativeExtractionDiagnostics diagnostics = new NativeExtractionDiagnostics();
        diagnostics.setExtractionMode(ExtractionMode.NATIVE);
        diagnostics.setAppliedLayout(appliedLayout);
        diagnostics.setAttemptedLayouts(new ArrayList<>(attemptedLayouts));
        diagnostics.setNativeRowCount(rowCount);
        diagnostics.setNativeTableCount(tableCount);

        NativeExtractionOutcome outcome = new NativeExtractionOutcome();
        outcome.setResult(result);
        outcome.setDiagnostics(diagnostics);
        return outcome;
    }

    public static NativeExtractionOutcome failure(List<NativeTableLayout> attemptedLayouts, String reason) {
        NativeExtractionDiagnostics diagnostics = new NativeExtractionDiagnostics();
        diagnostics.setExtractionMode(attemptedLayouts == null || attemptedLayouts.isEmpty()
                ? ExtractionMode.ML : ExtractionMode.NATIVE_FALLBACK_ML);
        diagnostics.setAttemptedLayouts(attemptedLayouts == null ? new ArrayList<>() : new ArrayList<>(attemptedLayouts));
        diagnostics.setFallbackReason(reason);

        NativeExtractionOutcome outcome = new NativeExtractionOutcome();
        outcome.setDiagnostics(diagnostics);
        return outcome;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.config.document.extraction.nativetable.NativeTableExtractionProperties;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy.NativeTableStrategy;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Offline transaction table extraction. For the bank format families that the
 * {@link NativeLayoutPolicyRegistry} declares as supported the statement PDF is parsed locally -
 * words from the PDF characters, table structure from the vector guides or the text alignment - and
 * the resulting document has exactly the same shape as a remotely extracted one.
 * <p>
 * The service never throws: whenever the native path cannot produce a usable table it reports a
 * failure outcome, and the caller falls back to the remote ML extraction.
 * </p>
 */
@Service
@Slf4j
public class NativeTableExtractionService {

    /** A PDF with less text than this is treated as scanned - only the ML path can read it. */
    private static final int MIN_WORDS_FOR_NATIVE_EXTRACTION = 40;

    private final Map<NativeTableLayout, NativeTableStrategy> strategies = new EnumMap<>(NativeTableLayout.class);

    @Setter(onMethod_ = @Autowired)
    private NativeLayoutPolicyRegistry nativeLayoutPolicyRegistry;

    @Setter(onMethod_ = @Autowired)
    private NativePageContentExtractor nativePageContentExtractor;

    @Setter(onMethod_ = @Autowired)
    private NativeTableValidator nativeTableValidator;

    @Setter(onMethod_ = @Autowired)
    private NativeTableExtractionProperties nativeTableExtractionProperties;

    @Autowired
    public void setNativeTableStrategies(List<NativeTableStrategy> nativeTableStrategies) {
        for (NativeTableStrategy strategy : nativeTableStrategies) {
            strategies.put(strategy.layout(), strategy);
        }
    }

    /**
     * Tries to extract the statement natively.
     *
     * @param request the extraction request, the bank name selects the native policy
     * @return the outcome, never {@code null}
     */
    public NativeExtractionOutcome extract(DocumentExtractionRequest request) {
        List<NativeTableLayout> policy = nativeLayoutPolicyRegistry.resolvePolicy(
                request == null ? null : request.getBankName());

        if (policy.isEmpty()) {
            return NativeExtractionOutcome.failure(policy,
                    "No native layout policy configured for bank " + (request == null ? null : request.getBankName()));
        }

        File statementFile = request.getStatementFile();
        if (statementFile == null || !statementFile.exists()) {
            return NativeExtractionOutcome.failure(policy, "Statement file is not available for native extraction");
        }

        List<NativePageContent> pages;
        try {
            pages = nativePageContentExtractor.extract(statementFile);
        } catch (Exception e) {
            log.info("Native extraction could not read the statement natively: {}", e.getMessage());
            return NativeExtractionOutcome.failure(policy, "Statement could not be read natively: " + e.getMessage());
        }

        if (pages.isEmpty()) {
            return NativeExtractionOutcome.failure(policy, "Statement has no pages");
        }
        if (nativePageContentExtractor.totalWords(pages) < MIN_WORDS_FOR_NATIVE_EXTRACTION) {
            return NativeExtractionOutcome.failure(policy, "Statement carries no extractable text (scanned document)");
        }

        List<NativeTableLayout> attempted = new ArrayList<>();
        for (NativeTableLayout layout : policy) {
            NativeTableStrategy strategy = strategies.get(layout);
            if (strategy == null) {
                continue;
            }
            attempted.add(layout);
            try {
                NativeExtractionOutcome outcome = applyStrategy(strategy, pages, attempted);
                if (outcome != null) {
                    return outcome;
                }
            } catch (Exception e) {
                log.info("Native layout {} failed: {}", layout, e.getMessage());
            }
        }

        return NativeExtractionOutcome.failure(attempted,
                "No native layout produced a usable transaction table");
    }

    private NativeExtractionOutcome applyStrategy(NativeTableStrategy strategy, List<NativePageContent> pages,
                                                  List<NativeTableLayout> attempted) {
        NativeExtractionContext context = new NativeExtractionContext();
        Map<Integer, Page> resultPages = new LinkedHashMap<>();
        int transactionRows = 0;
        int validTables = 0;

        for (NativePageContent pageContent : pages) {
            Page page = new Page();
            page.setPageNumber(pageContent.getPageNumber());
            page.setWidth((double) pageContent.getWidth());
            page.setHeight((double) pageContent.getHeight());
            page.setWords(new ArrayList<>(pageContent.getWords()));
            page.setContent(pageContent.getText());

            Map<Integer, Table> tables = new LinkedHashMap<>();
            int tableIndex = 0;
            for (Table table : strategy.extractTables(pageContent, context)) {
                if (table == null) {
                    continue;
                }
                int rows = nativeTableValidator.countTransactionRows(table);
                if (nativeTableValidator.isStructurallyValid(table, 1)) {
                    validTables++;
                    transactionRows += rows;
                    updateContext(context, table);
                }
                tables.put(tableIndex++, table);
            }

            page.setTables(tables);
            resultPages.put(pageContent.getPageNumber(), page);
        }

        int minRows = Math.max(1, nativeTableExtractionProperties.getMinTransactionRows());
        if (validTables == 0 || transactionRows < minRows) {
            log.debug("Native layout {} produced {} valid tables with {} transaction rows",
                    strategy.layout(), validTables, transactionRows);
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(resultPages);
        result.setNoOfPages(resultPages.size());

        return NativeExtractionOutcome.success(result, strategy.layout(), attempted, transactionRows, validTables);
    }

    /** Remembers the geometry of a recognised table so continuation pages can reuse it. */
    private void updateContext(NativeExtractionContext context, Table table) {
        if (table.getColumnBoundaries() != null && table.getColumnBoundaries().size() >= 4) {
            context.setColumnBoundaries(new ArrayList<>(table.getColumnBoundaries()));
        }
        Integer dateColumn = findDateColumn(table);
        if (dateColumn != null) {
            context.setDateColumnIndex(dateColumn);
        }
    }

    private Integer findDateColumn(Table table) {
        if (table.getCells() == null || table.getTotalColumns() == null) {
            return null;
        }
        int[] hits = new int[table.getTotalColumns()];
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            for (Map.Entry<Integer, TableCell> entry : row.entrySet()) {
                TableCell cell = entry.getValue();
                if (cell == null || entry.getKey() >= hits.length) {
                    continue;
                }
                String content = cell.getContent();
                if (content != null && !content.isBlank() && nativeTableValidator.isDateContent(content)) {
                    hits[entry.getKey()]++;
                }
            }
        }
        int best = -1;
        for (int column = 0; column < hits.length; column++) {
            if (hits[column] > 0 && (best < 0 || hits[column] > hits[best])) {
                best = column;
            }
        }
        return best < 0 ? null : best;
    }
}

