package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.config.requestlog.RequestStatus;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionMode;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.StatementDocumentAnalysisPipeline;
import com.finboost.bank.statement.parser.util.JsonUtil;
import com.finboost.bank.statement.parser.util.document.extraction.DocumentExtractionRequestFactory;
import com.finboost.bank.statement.parser.util.logging.LoggingPropertiesUtil;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

import java.io.IOException;

/**
 * Entry point of the statement table extraction.
 * <p>
 * For the bank format families with a native policy the offline extraction is attempted first. When
 * it produces a transaction table that survives the shared downstream analysis, that result is used
 * and no remote ML call happens at all. For unknown or unsupported layouts - and whenever the native
 * attempt does not yield a usable table - the remote ML extraction is used, which keeps the existing
 * behaviour as the default.
 * </p>
 */
@Service
@Slf4j
public class NativeFirstDocumentExtractionServiceImpl implements DocumentExtractionService {

    @Setter(onMethod_ = @Autowired)
    private NativeTableExtractionService nativeTableExtractionService;

    @Setter(onMethod_ = @Autowired)
    private StatementDocumentAnalysisPipeline statementDocumentAnalysisPipeline;

    private DocumentExtractionService mlDocumentExtractionService;

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setMlDocumentExtractionService(DocumentExtractionService mlDocumentExtractionService) {
        this.mlDocumentExtractionService = mlDocumentExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionResult result =
                extractDocument(DocumentExtractionRequestFactory.fromBankStatement(bankStatementVO));
        applyDiagnostics(bankStatementVO, result);
        return result;
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        NativeExtractionOutcome outcome = nativeTableExtractionService.extract(request);
        NativeExtractionDiagnostics diagnostics = outcome.getDiagnostics();

        if (outcome.isSuccessful()) {
            DocumentExtractionResult nativeResult = outcome.getResult();
            nativeResult.setNativeExtractionDiagnostics(diagnostics);
            try {
                statementDocumentAnalysisPipeline.analyze(nativeResult, request, false);
                if (statementDocumentAnalysisPipeline.hasUsableTransactionTable(nativeResult)) {
                    log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog(
                            RequestStatus.DOCUMENT_ANALYSIS_COMPLETED.name(),
                            "Statement extracted natively using layout " + diagnostics.getAppliedLayoutName()
                                    + ", remote ML extraction skipped")));
                    return nativeResult;
                }
                diagnostics = fallbackDiagnostics(diagnostics,
                        "Native tables were rejected by the downstream document analysis");
            } catch (Exception e) {
                diagnostics = fallbackDiagnostics(diagnostics,
                        "Native document analysis failed: " + e.getMessage());
            }
        }

        if (diagnostics.getExtractionMode() == ExtractionMode.NATIVE_FALLBACK_ML) {
            log.info(" " + JsonUtil.getJsonStringFromObject(LoggingPropertiesUtil.doLog("",
                    "Falling back to remote ML extraction: " + diagnostics.getFallbackReason())));
        }

        DocumentExtractionResult mlResult = mlDocumentExtractionService.extractDocument(request);
        if (mlResult != null) {
            mlResult.setNativeExtractionDiagnostics(diagnostics);
        }
        return mlResult;
    }

    private NativeExtractionDiagnostics fallbackDiagnostics(NativeExtractionDiagnostics diagnostics, String reason) {
        NativeExtractionDiagnostics fallback = diagnostics == null
                ? new NativeExtractionDiagnostics() : diagnostics.copy();
        fallback.setExtractionMode(ExtractionMode.NATIVE_FALLBACK_ML);
        fallback.setAppliedLayout(null);
        fallback.setNativeRowCount(null);
        fallback.setNativeTableCount(null);
        fallback.setFallbackReason(reason);
        return fallback;
    }

    /** Copies the diagnostics of the extraction onto the statement so the API and logs can use them. */
    private void applyDiagnostics(BankStatementVO bankStatementVO, DocumentExtractionResult result) {
        if (bankStatementVO == null || result == null || result.getNativeExtractionDiagnostics() == null) {
            return;
        }
        NativeExtractionDiagnostics diagnostics = result.getNativeExtractionDiagnostics();
        bankStatementVO.setExtractionMode(diagnostics.getExtractionMode());
        bankStatementVO.setNativeTableLayout(diagnostics.getAppliedLayout());
        bankStatementVO.setExtractionFallbackReason(diagnostics.getFallbackReason());
    }
}

