package com.finboost.bank.statement.parser.representation.bankAccount;

import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Per statement extraction diagnostics that are returned to the API client: whether the statement
 * was parsed by the offline/native table extraction, by the remote ML extraction, or natively with
 * a fallback to the remote ML extraction.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class StatementExtractionDiagnosticsVO {

    private String fileId;
    private String fileName;
    private String bank;
    /** NATIVE, ML or NATIVE_FALLBACK_ML. */
    private String extractionMode;
    /** Native layout that produced the tables, {@code null} for the ML path. */
    private String nativeLayout;
    /** Why the native path was skipped or abandoned. */
    private String fallbackReason;

    public static StatementExtractionDiagnosticsVO of(BankStatementVO bankStatementVO) {
        if (bankStatementVO == null) {
            return null;
        }
        StatementExtractionDiagnosticsVO diagnostics = new StatementExtractionDiagnosticsVO();
        diagnostics.setFileId(bankStatementVO.getFileId());
        diagnostics.setFileName(bankStatementVO.getOriginalFileName());
        diagnostics.setBank(bankStatementVO.getBank());
        diagnostics.setExtractionMode(bankStatementVO.getExtractionMode() == null
                ? null : bankStatementVO.getExtractionMode().name());
        diagnostics.setNativeLayout(bankStatementVO.getNativeTableLayout() == null
                ? null : bankStatementVO.getNativeTableLayout().name());
        diagnostics.setFallbackReason(bankStatementVO.getExtractionFallbackReason());
        return diagnostics;
    }
}

