import com.finboost.bank.statement.parser.config.document.extraction.nativetable.NativeTableExtractionProperties;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;

import java.io.File;
import java.util.*;

public class NativeHarness {

    static NativeTableExtractionService service;
    static AnalyzeDocuments analyzeDocuments;

    public static void main(String[] args) throws Exception {
        wire();
        File root = new File(args[0]);
        File[] banks = root.listFiles();
        Arrays.sort(banks);
        int nativeOk = 0, total = 0;
        for (File bank : banks) {
            if (!bank.isDirectory()) continue;
            if (args.length > 1 && !bank.getName().equals(args[1])) continue;
            File[] pdfs = bank.listFiles();
            Arrays.sort(pdfs);
            for (File pdf : pdfs) {
                total++;
                if (run(bank.getName(), pdf)) nativeOk++;
            }
        }
        System.out.printf("NATIVE OK %d / %d%n", nativeOk, total);
    }

    static boolean run(String bank, File pdf) {
        try {
            DocumentExtractionRequest request = new DocumentExtractionRequest();
            request.setStatementFile(pdf);
            request.setBankName(bank);
            NativeExtractionOutcome outcome = service.extract(request);
            if (!outcome.isSuccessful()) {
                System.out.printf("%-30s %-14s FAIL  %s%n", bank, pdf.getName(), outcome.getDiagnostics().getFallbackReason());
                return false;
            }
            DocumentExtractionResult result = outcome.getResult();
            analyzeDocuments.analyzeDocument(result, true, true, true);

            List<BankStatementVO> vos = new LinkedList<>();
            BankStatementVO vo = new BankStatementVO();
            vo.setDocumentExtractionResult(result);
            vos.add(vo);
            BankStatementProcessorImpl.extractTransactions(vos);
            List<BankTransactionVO> txns = vos.get(0).getBankTransactions();
            int count = txns == null ? 0 : txns.size();
            String sample = "";
            if (count > 0) {
                BankTransactionVO t = txns.get(0);
                sample = String.format("first[%tF %s %s bal=%s desc=%.40s]", t.getTransactionDate(),
                        t.getTransactionType(), t.getTransactionAmount(), t.getTransactionBalance(),
                        String.valueOf(t.getTransactionDescription()));
            }
            System.out.printf("%-30s %-14s OK %-26s rows=%-5d txns=%-5d %s%n", bank, pdf.getName(),
                    outcome.getDiagnostics().getAppliedLayoutName(), outcome.getDiagnostics().getNativeRowCount(), count, sample);
            return count > 0;
        } catch (Exception e) {
            System.out.printf("%-30s %-14s ERROR %s%n", bank, pdf.getName(), e);
            return false;
        }
    }

    static void wire() {
        EPdfCharacterExtractionService chars = new EPdfCharacterExtractionService();
        NativeWordAssembler assembler = new NativeWordAssembler();
        NativePageContentExtractor extractor = new NativePageContentExtractor();
        extractor.setEPdfCharacterExtractionService(chars);
        extractor.setNativeWordAssembler(assembler);

        ColumnTypeIdentifier columnTypeIdentifier = new ColumnTypeIdentifier();
        NativeColumnDetector detector = new NativeColumnDetector();
        NativeTableBuilder builder = new NativeTableBuilder();
        NativeHeaderLocator locator = new NativeHeaderLocator();
        NativeTableValidator validator = new NativeTableValidator();
        validator.setColumnTypeIdentifier(columnTypeIdentifier);

        BorderedGridTableStrategy grid = new BorderedGridTableStrategy();
        grid.setNativeColumnDetector(detector);
        grid.setNativeTableBuilder(builder);

        BoxGuidedTableStrategy box = new BoxGuidedTableStrategy();
        box.setNativeColumnDetector(detector);
        box.setNativeTableBuilder(builder);
        box.setNativeHeaderLocator(locator);

        TextAlignedRowSelectedTableStrategy text = new TextAlignedRowSelectedTableStrategy();
        text.setNativeColumnDetector(detector);
        text.setNativeTableBuilder(builder);
        text.setNativeHeaderLocator(locator);
        text.setColumnTypeIdentifier(columnTypeIdentifier);

        NativeTableExtractionProperties properties = new NativeTableExtractionProperties();
        NativeLayoutPolicyRegistry registry = new NativeLayoutPolicyRegistry();
        registry.setNativeTableExtractionProperties(properties);

        service = new NativeTableExtractionService();
        service.setNativeLayoutPolicyRegistry(registry);
        service.setNativePageContentExtractor(extractor);
        service.setNativeTableValidator(validator);
        service.setNativeTableExtractionProperties(properties);
        service.setNativeTableStrategies(Arrays.asList(grid, box, text));

        BankTransactionTableHeaderIdentifier headerIdentifier = new BankTransactionTableHeaderIdentifier();
        headerIdentifier.setColumnTypeIdentifier(columnTypeIdentifier);

        analyzeDocuments = new AnalyzeDocuments();
        analyzeDocuments.setColumnTypeIdentifier(columnTypeIdentifier);
        analyzeDocuments.setBankTransactionColumnTypeIdentifier(new BankTransactionColumnTypeIdentifier());
        analyzeDocuments.setBankTransactionTableIdentifier(new BankTransactionTableIdentifier());
        analyzeDocuments.setTableColumnNormalizer(new TableColumnNormalizer());
        analyzeDocuments.setTableRowNormalizer(new TableRowNormalizer());
        analyzeDocuments.setBankTransactionRowNormalizer(new BankTransactionRowNormalizer());
        analyzeDocuments.setBankTransactionTableHeaderIdentifier(headerIdentifier);
        analyzeDocuments.setBankTransactionTableFooterIdentifier(new BankTransactionTableFooterIdentifier());
        analyzeDocuments.setStatementBasicDetailExtractor(new StatementBasicDetailExtractor());
        analyzeDocuments.setBankSpecificParsingService(new com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankSpecificParsingServiceImpl());
    }
}

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;

import java.io.File;
import java.math.BigDecimal;
import java.text.SimpleDateFormat;
import java.util.*;

/** Compares the native extraction against the expected transactions of the fixture corpus. */
public class NativeAccuracy {

    public static void main(String[] args) throws Exception {
        NativeHarness.wire();
        ObjectMapper mapper = new ObjectMapper();
        JsonNode config = mapper.readTree(new File(args[0]));
        String filterBank = args.length > 1 ? args[1] : null;
        SimpleDateFormat sdf = new SimpleDateFormat("dd/MM/yyyy");

        int files = 0, nativeFiles = 0, matched = 0, expectedTotal = 0, perfectFiles = 0;
        for (JsonNode testCase : config.get("testCases")) {
            String pdfPath = testCase.get("pdfPath").asText().replace("classpath:", "/app/src/test/resources/");
            File pdf = new File(pdfPath);
            String bank = pdf.getParentFile().getName();
            if (filterBank != null && !bank.equals(filterBank)) continue;
            if (!pdf.exists()) continue;
            files++;

            List<BankTransactionVO> txns = extract(bank, pdf);
            if (txns == null) {
                System.out.printf("%-30s %-14s NATIVE-FALLBACK%n", bank, pdf.getName());
                continue;
            }
            nativeFiles++;

            int localMatched = 0, localExpected = 0;
            List<String> problems = new ArrayList<>();
            for (JsonNode expected : testCase.get("expectedTransactions")) {
                localExpected++;
                expectedTotal++;
                int index = expected.get("index").asInt();
                if (index >= txns.size()) {
                    problems.add("idx" + index + ":missing(size=" + txns.size() + ")");
                    continue;
                }
                BankTransactionVO actual = txns.get(index);
                boolean ok = true;
                StringBuilder detail = new StringBuilder("idx" + index + ":");
                String expectedDate = expected.get("transactionDate").asText();
                String actualDate = actual.getTransactionDate() == null ? "null" : sdf.format(actual.getTransactionDate());
                if (!expectedDate.equals(actualDate)) { ok = false; detail.append(" date ").append(expectedDate).append("!=").append(actualDate); }
                String expectedType = expected.get("type").asText();
                String actualType = actual.getTransactionType() == null ? "null" : actual.getTransactionType().name();
                if (!expectedType.equals(actualType)) { ok = false; detail.append(" type ").append(expectedType).append("!=").append(actualType); }
                BigDecimal expectedAmount = expected.get("amount").decimalValue();
                if (actual.getTransactionAmount() == null || expectedAmount.compareTo(actual.getTransactionAmount()) != 0) {
                    ok = false; detail.append(" amt ").append(expectedAmount).append("!=").append(actual.getTransactionAmount());
                }
                BigDecimal expectedBalance = expected.get("balance").decimalValue();
                if (actual.getTransactionBalance() == null || expectedBalance.compareTo(actual.getTransactionBalance()) != 0) {
                    ok = false; detail.append(" bal ").append(expectedBalance).append("!=").append(actual.getTransactionBalance());
                }
                if (ok) { matched++; localMatched++; } else { problems.add(detail.toString()); }
            }
            if (localMatched == localExpected) perfectFiles++;
            System.out.printf("%-30s %-14s NATIVE txns=%-5d matched=%d/%d %s%n", bank, pdf.getName(),
                    txns.size(), localMatched, localExpected, problems.isEmpty() ? "" : problems.toString());
        }
        System.out.printf("FILES=%d NATIVE=%d PERFECT=%d EXPECTED_TXNS=%d MATCHED=%d%n",
                files, nativeFiles, perfectFiles, expectedTotal, matched);
    }

    static List<BankTransactionVO> extract(String bank, File pdf) {
        try {
            DocumentExtractionRequest request = new DocumentExtractionRequest();
            request.setStatementFile(pdf);
            request.setBankName(bank);
            NativeExtractionOutcome outcome = NativeHarness.service.extract(request);
            if (!outcome.isSuccessful()) return null;
            DocumentExtractionResult result = outcome.getResult();
            NativeHarness.analyzeDocuments.analyzeDocument(result, true, true, true);
            List<BankStatementVO> vos = new LinkedList<>();
            BankStatementVO vo = new BankStatementVO();
            vo.setDocumentExtractionResult(result);
            vos.add(vo);
            BankStatementProcessorImpl.extractTransactions(vos);
            return vos.get(0).getBankTransactions() == null ? new ArrayList<>() : vos.get(0).getBankTransactions();
        } catch (Exception e) {
            System.out.println("   error " + e);
            return null;
        }
    }
}

