import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;

import java.io.File;
import java.util.*;

/** Prints the native page geometry and the built tables for a single PDF. */
public class NativeDebug {

    public static void main(String[] args) throws Exception {
        NativeHarness.wire();
        File pdf = new File(args[0]);
        String layoutName = args.length > 1 ? args[1] : "BOX_GUIDED";
        int maxPages = args.length > 2 ? Integer.parseInt(args[2]) : 3;
        boolean dump = args.length > 3;

        EPdfCharacterExtractionService chars = new EPdfCharacterExtractionService();
        NativeWordAssembler assembler = new NativeWordAssembler();
        NativePageContentExtractor extractor = new NativePageContentExtractor();
        extractor.setEPdfCharacterExtractionService(chars);
        extractor.setNativeWordAssembler(assembler);

        ColumnTypeIdentifier cti = new ColumnTypeIdentifier();
        NativeColumnDetector detector = new NativeColumnDetector();
        NativeTableBuilder builder = new NativeTableBuilder();
        NativeHeaderLocator locator = new NativeHeaderLocator();

        NativeTableStrategy strategy;
        if (layoutName.equals("BORDERED_GRID")) {
            BorderedGridTableStrategy s = new BorderedGridTableStrategy();
            s.setNativeColumnDetector(detector); s.setNativeTableBuilder(builder);
            strategy = s;
        } else if (layoutName.equals("BOX_GUIDED")) {
            BoxGuidedTableStrategy s = new BoxGuidedTableStrategy();
            s.setNativeColumnDetector(detector); s.setNativeTableBuilder(builder); s.setNativeHeaderLocator(locator);
            strategy = s;
        } else {
            TextAlignedRowSelectedTableStrategy s = new TextAlignedRowSelectedTableStrategy();
            s.setNativeColumnDetector(detector); s.setNativeTableBuilder(builder); s.setNativeHeaderLocator(locator);
            s.setColumnTypeIdentifier(cti);
            strategy = s;
        }

        NativeExtractionContext context = new NativeExtractionContext();
        List<NativePageContent> pages = extractor.extract(pdf);
        for (NativePageContent page : pages) {
            if (page.getPageNumber() > maxPages) break;
            System.out.printf("PAGE %d size=%.2fx%.2f words=%d lines=%d hRul=%d vRul=%d boxes=%d lineH=%.3f%n",
                    page.getPageNumber(), page.getWidth(), page.getHeight(), page.getWords().size(),
                    page.getTextLines().size(), page.getHorizontalRulings().size(),
                    page.getVerticalRulings().size(), page.getBoxes().size(), page.medianLineHeight());
            List<Table> tables = strategy.extractTables(page, context);
            System.out.printf("  tables=%d%n", tables.size());
            for (Table table : tables) {
                System.out.printf("  TABLE rows=%d cols=%d bounds=%s%n", table.getTotalRows(), table.getTotalColumns(),
                        table.getColumnBoundaries());
                if (table.getColumnBoundaries() != null && table.getColumnBoundaries().size() >= 4) {
                    context.setColumnBoundaries(table.getColumnBoundaries());
                }
                if (dump) {
                    for (Map.Entry<Integer, Map<Integer, TableCell>> row : table.getCells().entrySet()) {
                        StringBuilder sb = new StringBuilder("    r" + row.getKey() + " |");
                        for (Map.Entry<Integer, TableCell> cell : row.getValue().entrySet()) {
                            sb.append(' ').append(cell.getValue().getContent()).append(" |");
                        }
                        System.out.println(sb);
                    }
                }
            }
        }
    }
}

