/** Dumps the raw native geometry of one page. */
public class GeomDump {
    public static void main(String[] args) throws Exception {
        File pdf = new File(args[0]);
        int pageNo = Integer.parseInt(args[1]);
        EPdfCharacterExtractionService chars = new EPdfCharacterExtractionService();
        NativeWordAssembler assembler = new NativeWordAssembler();
        NativePageContentExtractor extractor = new NativePageContentExtractor();
        extractor.setEPdfCharacterExtractionService(chars);
        extractor.setNativeWordAssembler(assembler);
        for (NativePageContent page : extractor.extract(pdf)) {
            if (page.getPageNumber() != pageNo) continue;
            System.out.printf("page %d %.2fx%.2f lineH=%.3f%n", page.getPageNumber(), page.getWidth(), page.getHeight(), page.medianLineHeight());
            System.out.println("-- boxes --");
            List<NativeBox> boxes = new ArrayList<>(page.getBoxes());
            boxes.sort(Comparator.comparing(NativeBox::getTop));
            for (NativeBox b : boxes) {
                System.out.printf("  box l=%.3f r=%.3f t=%.3f b=%.3f w=%.3f h=%.3f filled=%s%n",
                        b.getLeft(), b.getRight(), b.getTop(), b.getBottom(), b.width(), b.height(), b.isFilled());
            }
            System.out.println("-- h rulings --");
            for (NativeRuling r : page.getHorizontalRulings()) {
                System.out.printf("  h y=%.3f x=[%.3f..%.3f] len=%.3f%n", r.position(), r.start(), r.end(), r.length());
            }
            System.out.println("-- v rulings --");
            for (NativeRuling r : page.getVerticalRulings()) {
                System.out.printf("  v x=%.3f y=[%.3f..%.3f] len=%.3f%n", r.position(), r.start(), r.end(), r.length());
            }
            System.out.println("-- lines --");
            for (NativeTextLine l : page.getTextLines()) {
                System.out.printf("  line t=%.3f b=%.3f : %.120s%n", l.getTop(), l.getBottom(), l.text());
            }
        }
    }
}

