/** Groups the row guiding boxes of a page into row bands. */
private List<List<NativeBox>> groupBoxesIntoRows(NativePageContent page, float lineHeight) {
    // a row band is at least a fraction of a text line high and never taller than half a page
    float minBandHeight = Math.max(0.03f, lineHeight * 0.4f);
    float maxBandHeight = Math.min(page.getHeight() * 0.5f, MAX_ROW_BAND_HEIGHT);

    List<NativeBox> candidates = new ArrayList<>();
    for (NativeBox box : page.getBoxes()) {
        float height = box.height();
        if (height < minBandHeight || height > maxBandHeight) {
            continue;
        }
        if (box.width() < 0.1f) {
            continue;
        }
        candidates.add(box);
    }

