package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeTextLine;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import lombok.Setter;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Refines the row bands that were derived from the vector guides of a page.
 * <p>
 * Several banks draw one box (or one pair of row rules) around a group of transactions instead of
 * around every single transaction. Without a refinement all transactions of such a band would be
 * merged into one row and their dates and amounts would be concatenated. The refiner therefore
 * splits a band as soon as more than one of its text lines starts a transaction, which is detected
 * with the very same date/amount classifiers the downstream pipeline uses.
 * </p>
 */
@Component
public class NativeRowRefiner {

    /** A column has to carry at least this many dates to be considered the date column. */
    private static final int MIN_DATE_HITS = 2;

    @Setter(onMethod_ = @Autowired)
    private ColumnTypeIdentifier columnTypeIdentifier;

    /**
     * @param page       native content of the page
     * @param boundaries column boundaries of the table
     * @param bands      row bands as {@code {top, bottom}} pairs, ordered top to bottom
     * @return the refined row bands, ordered top to bottom
     */
    public List<float[]> refine(NativePageContent page, List<Float> boundaries, List<float[]> bands) {
        if (boundaries == null || boundaries.size() < 4 || bands == null || bands.isEmpty()) {
            return bands;
        }

        List<NativeTextLine> lines = new ArrayList<>(page.getTextLines());
        lines.sort(Comparator.comparing(NativeTextLine::getTop));
        if (lines.isEmpty()) {
            return bands;
        }

        int dateColumn = findDateColumn(lines, boundaries);
        if (dateColumn < 0) {
            return bands;
        }

        List<float[]> refined = new LinkedList<>();
        for (float[] band : bands) {
            List<NativeTextLine> bandLines = linesOf(lines, band);
            List<Integer> starts = transactionStarts(bandLines, boundaries, dateColumn);
            if (starts.size() < 2) {
                refined.add(band);
                continue;
            }
            refined.addAll(split(band, bandLines, starts));
        }
        return refined;
    }

    private List<float[]> split(float[] band, List<NativeTextLine> bandLines, List<Integer> starts) {
        List<float[]> parts = new LinkedList<>();
        float top = band[0];
        for (int i = 1; i < starts.size(); i++) {
            int startIndex = starts.get(i);
            NativeTextLine startLine = bandLines.get(startIndex);
            NativeTextLine previousLine = bandLines.get(startIndex - 1);
            float cut = (previousLine.getBottom() + startLine.getTop()) / 2f;
            if (cut <= top) {
                continue;
            }
            parts.add(new float[]{top, cut});
            top = cut;
        }
        parts.add(new float[]{top, band[1]});
        return parts;
    }

    private List<NativeTextLine> linesOf(List<NativeTextLine> lines, float[] band) {
        List<NativeTextLine> result = new ArrayList<>();
        for (NativeTextLine line : lines) {
            float center = line.centerY();
            if (center >= band[0] && center <= band[1]) {
                result.add(line);
            }
        }
        return result;
    }

    private List<Integer> transactionStarts(List<NativeTextLine> bandLines, List<Float> boundaries, int dateColumn) {
        List<Integer> starts = new ArrayList<>();
        for (int i = 0; i < bandLines.size(); i++) {
            String[] contents = NativeTableBuilder.columnContents(bandLines.get(i), boundaries);
            if (dateColumn >= contents.length) {
                continue;
            }
            String dateContent = contents[dateColumn];
            if (dateContent == null || dateContent.isBlank() || !columnTypeIdentifier.isDateType(dateContent)) {
                continue;
            }
            if (hasAmount(contents, dateColumn)) {
                starts.add(i);
            }
        }
        return starts;
    }

    private boolean hasAmount(String[] contents, int dateColumn) {
        for (int column = 0; column < contents.length; column++) {
            if (column == dateColumn || contents[column] == null || contents[column].isBlank()) {
                continue;
            }
            if (columnTypeIdentifier.isAmountType(contents[column].trim())) {
                return true;
            }
        }
        return false;
    }

    private int findDateColumn(List<NativeTextLine> lines, List<Float> boundaries) {
        int columnCount = boundaries.size() - 1;
        int[] hits = new int[columnCount];
        for (NativeTextLine line : lines) {
            String[] contents = NativeTableBuilder.columnContents(line, boundaries);
            for (int column = 0; column < columnCount; column++) {
                if (contents[column] != null && !contents[column].isBlank()
                        && columnTypeIdentifier.isDateType(contents[column])) {
                    hits[column]++;
                }
            }
        }
        int best = -1;
        for (int column = 0; column < columnCount; column++) {
            if (hits[column] >= MIN_DATE_HITS && (best < 0 || hits[column] > hits[best])) {
                best = column;
            }
        }
        return best;
    }
}

