/** Runs the full native path (service + downstream analysis) and dumps the final tables. */
public class NativeDebug2 {
    public static void main(String[] args) throws Exception {
        NativeHarness.wire();
        File pdf = new File(args[0]);
        String bank = args.length > 1 ? args[1] : pdf.getParentFile().getName();
        int maxPages = args.length > 2 ? Integer.parseInt(args[2]) : 2;

        DocumentExtractionRequest request = new DocumentExtractionRequest();
        request.setStatementFile(pdf);
        request.setBankName(bank);
        NativeExtractionOutcome outcome = NativeHarness.service.extract(request);
        System.out.println("mode=" + outcome.getDiagnostics().getExtractionModeName()
                + " layout=" + outcome.getDiagnostics().getAppliedLayoutName()
                + " rows=" + outcome.getDiagnostics().getNativeRowCount()
                + " tables=" + outcome.getDiagnostics().getNativeTableCount()
                + " reason=" + outcome.getDiagnostics().getFallbackReason());
        if (!outcome.isSuccessful()) return;

        DocumentExtractionResult result = outcome.getResult();
        NativeHarness.analyzeDocuments.analyzeDocument(result, true, true, true);
        for (Map.Entry<Integer, Page> pageEntry : result.getPages().entrySet()) {
            if (pageEntry.getKey() > maxPages) continue;
            for (Map.Entry<Integer, Table> tableEntry : pageEntry.getValue().getTables().entrySet()) {
                Table table = tableEntry.getValue();
                System.out.printf("PAGE %d TABLE %d txnTable=%s rows=%d cols=%d colType=%s txnColType=%s%n",
                        pageEntry.getKey(), tableEntry.getKey(), table.getIsTransactionTable(),
                        table.getTotalRows(), table.getTotalColumns(), table.getColType(), table.getTxnColType());
                for (Map.Entry<Integer, Map<Integer, TableCell>> row : table.getCells().entrySet()) {
                    StringBuilder sb = new StringBuilder("  r" + row.getKey() + " |");
                    for (Map.Entry<Integer, TableCell> cell : row.getValue().entrySet()) {
                        sb.append(' ').append(cell.getValue().getContent()).append(" |");
                    }
                    System.out.println(sb);
                }
            }
        }
        List<BankStatementVO> vos = new LinkedList<>();
        BankStatementVO vo = new BankStatementVO();
        vo.setDocumentExtractionResult(result);
        vos.add(vo);
        BankStatementProcessorImpl.extractTransactions(vos);
        List<BankTransactionVO> txns = vos.get(0).getBankTransactions();
        System.out.println("txns=" + (txns == null ? 0 : txns.size()));
    }
}

