    private float adjustToWhitespace(float boundary, float gapStart, float gapEnd, List<Word> bodyWords) {
        if (bodyWords == null || bodyWords.isEmpty()) {
            return boundary;
        }
        List<Word> crossing = new ArrayList<>();
        for (Word word : bodyWords) {
            if (word.getX1() < boundary && word.getX3() > boundary) {
                crossing.add(word);
            }
        }
        if (crossing.isEmpty()) {
            return boundary;
        }
        crossing.sort(Comparator.comparing(Word::getX1));
        // move the boundary to the left edge of the left most crossing word when that still keeps
        // it inside the header whitespace, otherwise to the right edge of the last crossing word
        float leftCandidate = crossing.get(0).getX1() - 0.01f;
        float rightCandidate = crossing.get(crossing.size() - 1).getX3() + 0.01f;
        if (leftCandidate > gapStart) {
