        int bestLength = 0;
        int runStart = -1;
        for (int i = from; i <= to; i++) {
            if (!occupied[i]) {
                if (runStart < 0) {
                    runStart = i;
                }
                int length = i - runStart + 1;
                if (length > bestLength) {
                    bestLength = length;
                    bestStart = runStart;
                }
            } else {
