package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.config.document.extraction.nativetable.NativeTableExtractionProperties;
import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.service.bankstatement.InconsistencyFinderService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

/**
 * Final quality gate of the native extraction path.
 * <p>
 * The natively built tables are run through the existing transaction extraction and the resulting
 * transactions are checked against the running balance of the statement. A native result is only
 * accepted when it yields enough transactions and when their balance chain is consistent - a row
 * that was missed or merged by the native geometry breaks the chain and the statement is handed to
 * the remote ML extraction instead.
 * </p>
 */
@Component
@Slf4j
public class NativeResultVerifier {

    @Setter(onMethod_ = @Autowired)
    private NativeTableExtractionProperties nativeTableExtractionProperties;

    /**
     * @param result the analysed native result
     * @return {@code null} when the result can be used, otherwise the reason for the ML fallback
     */
    public String verify(DocumentExtractionResult result) {
        List<BankTransactionVO> transactions = extractTransactions(result);
        int minRows = Math.max(1, nativeTableExtractionProperties.getMinTransactionRows());

        if (transactions.size() < minRows) {
            return "Native tables produced only " + transactions.size() + " transactions";
        }

        Integer inconsistencies = InconsistencyFinderService.checkInconsistencyForCount(transactions);
        if (inconsistencies == null) {
            return "Balance consistency of the native transactions could not be verified";
        }

        double allowed = Math.floor(transactions.size() * Math.max(0d,
                nativeTableExtractionProperties.getMaxInconsistencyRatio()));
        if (inconsistencies > allowed) {
            return "Native transactions are not balance consistent (" + inconsistencies + " of "
                    + transactions.size() + " transactions)";
        }

        return null;
    }

    private List<BankTransactionVO> extractTransactions(DocumentExtractionResult result) {
        try {
            BankStatementVO probe = new BankStatementVO();
            probe.setDocumentExtractionResult(result);
            List<BankStatementVO> probes = new ArrayList<>();
            probes.add(probe);
            BankStatementProcessorImpl.extractTransactions(probes);
            List<BankTransactionVO> transactions = probes.get(0).getBankTransactions();
            return transactions == null ? new ArrayList<>() : transactions;
        } catch (Exception e) {
            log.info("Native transactions could not be extracted for verification: {}", e.getMessage());
            return new ArrayList<>();
        }
    }
}

