import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;

import java.io.File;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

/** Prints the transactions around every balance chain break of the native extraction. */
public class InconsistencyDebug {
    public static void main(String[] args) throws Exception {
        NativeHarness.wire();
        File pdf = new File(args[0]);
        String bank = args.length > 1 ? args[1] : pdf.getParentFile().getName();

        DocumentExtractionRequest request = new DocumentExtractionRequest();
        request.setStatementFile(pdf);
        request.setBankName(bank);
        NativeExtractionOutcome outcome = NativeHarness.service.extract(request);
        if (!outcome.isSuccessful()) { System.out.println("native failed: " + outcome.getDiagnostics().getFallbackReason()); return; }
        DocumentExtractionResult result = outcome.getResult();
        System.out.println("layout=" + outcome.getDiagnostics().getAppliedLayoutName());
        NativeHarness.pipeline.analyze(result, request, false);

        BankStatementVO vo = new BankStatementVO();
        vo.setDocumentExtractionResult(result);
        List<BankStatementVO> vos = new LinkedList<>();
        vos.add(vo);
        BankStatementProcessorImpl.extractTransactions(vos);
        List<BankTransactionVO> txns = vos.get(0).getBankTransactions();
        System.out.println("txns=" + txns.size() + " reversed=" + result.isStatementWithReversedOrder()
                + " reversePerDate=" + result.isStatementWithReverseOrderPerDate());
        for (int i = 0; i < txns.size() - 1; i++) {
            BankTransactionVO a = txns.get(i), b = txns.get(i + 1);
            BigDecimal expected = "CREDIT".equals(String.valueOf(b.getTransactionType()))
                    ? a.getTransactionBalance().add(b.getTransactionAmount())
                    : a.getTransactionBalance().subtract(b.getTransactionAmount());
            if (expected.setScale(2, RoundingMode.HALF_UP).compareTo(b.getTransactionBalance().setScale(2, RoundingMode.HALF_UP)) != 0) {
                System.out.printf("BREAK at %d:%n  a[%tF %s %s bal=%s desc=%.60s]%n  b[%tF %s %s bal=%s desc=%.60s]%n",
                        i, a.getTransactionDate(), a.getTransactionType(), a.getTransactionAmount(), a.getTransactionBalance(), String.valueOf(a.getTransactionDescription()),
                        b.getTransactionDate(), b.getTransactionType(), b.getTransactionAmount(), b.getTransactionBalance(), String.valueOf(b.getTransactionDescription()));
            }
        }
    }
}

