package com.finboost.bank.statement.parser.service.document.extraction.nativetable.strategy;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeColumnDetector;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeExtractionContext;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeGeometryUtil;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeRowRefiner;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTableBuilder;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativePageContent;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.model.NativeRuling;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Native strategy for statements whose transaction table is bordered by rulings: column rulings that
 * span the table body, optionally combined with row rulings.
 * <p>
 * The grid is recovered from the vector guides only:
 * <ol>
 *     <li>the column rulings are grouped by their vertical extent - every group is one bordered
 *     region of the page (an account summary box is a different region than the transaction table),</li>
 *     <li>inside a region the ruling positions become the column boundaries and the row rulings that
 *     cross the region become the row separators,</li>
 *     <li>regions that only have an outer border are split into rows by the row refiner, which uses
 *     the date/amount content of the text lines.</li>
 * </ol>
 */
@Component
@Slf4j
public class BorderedGridTableStrategy implements NativeTableStrategy {

    /** A row ruling has to cover this share of the region width. */
    private static final float MIN_ROW_RULING_COVERAGE = 0.6f;
    /** Two column rulings belong to the same region when they overlap by this share. */
    private static final float REGION_OVERLAP_RATIO = 0.5f;
    /** Minimum number of column rulings of a bordered region (three columns). */
    private static final int MIN_COLUMN_RULINGS = 4;
    /** Minimum width (inches) of a bordered region. */
    private static final float MIN_REGION_WIDTH = 0.5f;

    @Setter(onMethod_ = @Autowired)
    private NativeColumnDetector nativeColumnDetector;

    @Setter(onMethod_ = @Autowired)
    private NativeTableBuilder nativeTableBuilder;

    @Setter(onMethod_ = @Autowired)
    private NativeRowRefiner nativeRowRefiner;

    @Override
    public NativeTableLayout layout() {
        return NativeTableLayout.BORDERED_GRID;
    }

    @Override
    public List<Table> extractTables(NativePageContent page, NativeExtractionContext context) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText() || page.getVerticalRulings().isEmpty()) {
            return tables;
        }

        float lineHeight = page.medianLineHeight();
        List<NativeRuling> columnRulings = longRulings(page.getVerticalRulings(), lineHeight * 1.2f);

        for (List<NativeRuling> region : groupIntoRegions(columnRulings)) {
            Table table = buildRegion(page, region, lineHeight);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private Table buildRegion(NativePageContent page, List<NativeRuling> regionRulings, float lineHeight) {
        if (regionRulings.size() < MIN_COLUMN_RULINGS) {
            return null;
        }

        float top = Float.MAX_VALUE;
        float bottom = -Float.MAX_VALUE;
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (NativeRuling ruling : regionRulings) {
            top = Math.min(top, ruling.start());
            bottom = Math.max(bottom, ruling.end());
            left = Math.min(left, ruling.position());
            right = Math.max(right, ruling.position());
        }
        if (right - left < MIN_REGION_WIDTH) {
            return null;
        }

        List<Float> boundaries = nativeColumnDetector.fromRulings(regionRulings, top, bottom, 0f);
        if (boundaries.size() < 4) {
            return null;
        }

        List<float[]> bands = bands(page, top, bottom, left, right, lineHeight);
        if (bands.isEmpty()) {
            return null;
        }

        List<Word> words = new LinkedList<>();
        for (Word word : page.getWords()) {
            float centerY = (word.getY1() + word.getY3()) / 2f;
            if (centerY >= top && centerY <= bottom) {
                words.add(word);
            }
        }
        if (words.isEmpty()) {
            return null;
        }

        // a bordered row may hold more than one transaction (or the region may only have an outer
        // border), split those bands by the transactions they contain
        bands = nativeRowRefiner.refine(page, boundaries, bands);

        return nativeTableBuilder.buildFromBands(page.getPageNumber(), boundaries, bands, words);
    }

    /** Row bands of a region, taken from the row rulings that cross it. */
    private List<float[]> bands(NativePageContent page, float top, float bottom, float left, float right,
                                float lineHeight) {
        float width = right - left;
        List<Float> positions = new ArrayList<>();
        positions.add(top);
        positions.add(bottom);
        for (NativeRuling ruling : page.getHorizontalRulings()) {
            if (ruling.position() < top - lineHeight * 0.5f || ruling.position() > bottom + lineHeight * 0.5f) {
                continue;
            }
            float overlap = Math.min(right, ruling.end()) - Math.max(left, ruling.start());
            if (width <= 0f || overlap >= width * MIN_ROW_RULING_COVERAGE) {
                positions.add(Math.min(Math.max(ruling.position(), top), bottom));
            }
        }

        List<Float> separators = NativeGeometryUtil.clusterValues(positions, lineHeight * 0.35f);
        List<float[]> bands = new ArrayList<>();
        for (int i = 0; i < separators.size() - 1; i++) {
            bands.add(new float[]{separators.get(i), separators.get(i + 1)});
        }
        return bands;
    }

    /**
     * Groups column rulings that share their vertical extent - every group borders one region of
     * the page.
     */
    private List<List<NativeRuling>> groupIntoRegions(List<NativeRuling> columnRulings) {
        List<NativeRuling> sorted = new ArrayList<>(columnRulings);
        sorted.sort(Comparator.comparing(NativeRuling::length).reversed());

        List<List<NativeRuling>> regions = new LinkedList<>();
        List<float[]> extents = new ArrayList<>();

        for (NativeRuling ruling : sorted) {
            int match = -1;
            for (int i = 0; i < extents.size(); i++) {
                float[] extent = extents.get(i);
                float overlap = Math.min(extent[1], ruling.end()) - Math.max(extent[0], ruling.start());
                float shorter = Math.min(extent[1] - extent[0], ruling.length());
                if (shorter > 0f && overlap >= shorter * REGION_OVERLAP_RATIO) {
                    match = i;
                    break;
                }
            }
            if (match < 0) {
                List<NativeRuling> region = new ArrayList<>();
                region.add(ruling);
                regions.add(region);
                extents.add(new float[]{ruling.start(), ruling.end()});
            } else {
                regions.get(match).add(ruling);
            }
        }

        return regions;
    }

    private List<NativeRuling> longRulings(List<NativeRuling> rulings, float minLength) {
        List<NativeRuling> result = new LinkedList<>();
        for (NativeRuling ruling : rulings) {
            if (ruling.length() >= minLength) {
                result.add(ruling);
            }
        }
        return result;
    }
}

